export default {"1":{"html":"<p>کرناٹک کے ایک پرسکون قصبے میں، ایک کسان نے تجارتی کھاتہ کھولا اور مستقبل اور اختیارات کی خرید و فروخت شروع کی۔ یہ 2014 کے آس پاس کی بات ہے۔ بہت سے ابتدائیوں کی طرح، اس نے بھی سرگرمی سے تجارت کی، اس امید پر کہ مارکیٹ کاشتکاری سے معمولی آمدنی میں اضافہ کرے گا۔ ایسا نہیں ہوا۔ جب وہ روکتا تھا، تب تک وہ اپنی ہی رقم میں سے تقریباً 26 لاکھ روپے کھو چکا تھا۔ کوئی فائدہ نہیں تھا، کوئی ہوا نہیں، جشن منانے کے لیے کچھ نہیں تھا۔ تو اس نے وہی کیا جو فطری محسوس ہوا۔ اس نے اکاؤنٹ بند کر دیا، نقصان کو نگل لیا، اور ان تجارتوں کے لیے انکم ٹیکس ریٹرن فائل نہیں کیا۔ اس کا استدلال سادہ تھا اور، زیادہ تر ابتدائیوں کے لیے، مکمل طور پر قابل فہم تھا۔ اگر کوئی منافع نہیں ہے، تو رپورٹ کرنے کے لئے کچھ بھی نہیں ہے.</p>\n<p>اس ایک مفروضے نے اسے تقریباً تباہ کر دیا تھا۔</p>\n<p>2021 میں، اس کے آگے بڑھنے کے برسوں بعد، محکمہ انکم ٹیکس نے اس کا کیس دوبارہ کھولا۔ جب انھوں نے اس کے PAN سے منسلک ریکارڈز کو کھینچا، تو انھیں وہ چیز ملی جس کے بارے میں انھوں نے کبھی سوچا بھی نہیں تھا۔ ان کے کل فیوچرز اور آپشنز ٹرن اوور، ان تمام تجارتوں کے ذریعے منتھلی ہوئی پوری قیمت، تقریباً 69 کروڑ روپے تک پہنچ گئی۔ اس کا نقصان نہیں، اس کا منافع نہیں، بلکہ سرگرمی کا سراسر سائز جو اس کے اکاؤنٹ سے گزرا تھا۔ ایک نوٹس نکلا جس میں اس سے وضاحت طلب کی گئی۔ اس نے اسے یاد کیا۔ وہ ایک کسان تھا، نہ کہ انکم ٹیکس پورٹل چیک کرنے والا۔ اور جب کوئی ٹیکس دہندہ جواب نہیں دیتا ہے، تو محکمہ کو اپنی تشخیص خود کرنے کی اجازت ہے۔ ریکارڈ پر کسی وضاحت کے بغیر، پورے 69 کروڑ روپے کے ٹرن اوور کو ایسا سمجھا گیا جیسے یہ آمدنی ہو۔ اس پر ٹیکس جمع جرمانہ اور سود کا مطالبہ تقریباً 68 کروڑ روپے تک پہنچا۔</p>\n<h2 id=\"how-a-small-loss-became-a-giant-demand\">کس طرح ایک چھوٹا سا نقصان ایک بڑا مطالبہ بن گیا</h2>\n<p>ایک لمحے کے لیے اس کے ساتھ بیٹھو۔ ایک شخص جس کو 26 لاکھ روپے کا نقصان ہوا اسے تقریباً 68 کروڑ روپے کا بل دیا گیا۔ ان دو نمبروں کے درمیان فرق اس کورس کے موجود ہونے کی پوری وجہ ہے۔</p>\n<p>اس نے کوئی بے ایمانی نہیں کی۔ اسے چھپانے کا کوئی فائدہ نہیں تھا۔ اس کی غلطی صرف خاموشی تھی۔ اس نے کبھی فائل نہیں دی، اس لیے اس نے کبھی بھی محکمے کو، اس کی اپنی زبان میں نہیں بتایا کہ یہ خسارہ ہے آمدنی نہیں ہے۔ نظام آپ کی طرف سے بہترین فرض نہیں کرتا ہے۔ جب آپ خاموش رہتے ہیں، تو یہ خالی جگہ کو بدترین کیس سے بھر دیتا ہے، اور یہاں سب سے بری صورت یہ تھی کہ کاروبار کا ہر روپیہ قابل ٹیکس تھا۔</p>\n<p>اگر اس نے نقصان کو ظاہر کرتے ہوئے محض ایک ریٹرن فائل کیا ہوتا تو اس میں سے تقریباً کچھ بھی نہ ہوتا۔ ایک اطلاع شدہ نقصان صرف ایک نقصان ہے۔ یہ آمدنی نہیں ہے، اس میں کوئی ٹیکس نہیں ہے، اور جیسا کہ آپ اس کورس میں بعد میں دیکھیں گے، اسے مستقبل کے سالوں میں ٹیکس بچانے کے لیے بھی آگے بڑھایا جا سکتا ہے۔ رپورٹنگ کا عمل وہ ہے جو آپ کی حفاظت کرتا ہے۔ کچھ نہ چھپانا اب بھی کچھ نہ کہنے سے بہت مختلف ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>خطرہ شاذ و نادر ہی ٹیکس ہی ہے۔ خطرہ فائل نہیں کر رہا ہے۔ ایک غیر رپورٹ شدہ اکاؤنٹ خالی چھوڑ دیتا ہے جسے محکمہ اپنے مفروضے سے بھرنے کے لیے آزاد ہے، اور یہ مفروضہ تقریباً کبھی بھی آپ کے حق میں نہیں ہوتا۔</p>\n</div></div>\n\n<figure class=\"lesson-shot\">\n<img src=\"/taxation/images/diagram-not-reporting.png\" alt=\"جب کوئی تاجر خاموش رہتا ہے، تو محکمہ ٹیکس پورے ٹرن اوور کو قابل ٹیکس آمدنی سمجھ سکتا ہے، اصل نفع یا نقصان کو نہیں۔ ریٹرن فائل کرنا وہی ہے جو ایک بڑے نمبر کو ایک سادہ، بے ضرر نقصان میں بدل دیتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>جب کوئی تاجر خاموش رہتا ہے، تو محکمہ ٹیکس پورے ٹرن اوور کو قابل ٹیکس آمدنی سمجھ سکتا ہے، اصل نفع یا نقصان کو نہیں۔ ریٹرن فائل کرنا وہی ہے جو ایک بڑے نمبر کو ایک سادہ، بے ضرر نقصان میں بدل دیتا ہے۔</figcaption></figure>\n<h2 id=\"the-department-already-sees-every-trade\">محکمہ پہلے ہی ہر تجارت کو دیکھتا ہے۔</h2>\n<p>بہت سے تاجر خاموشی سے یقین رکھتے ہیں کہ ان کی سرگرمی پوشیدہ ہے۔ یہ نہیں ہے، اور یہ سالوں سے نہیں ہے. مارکیٹ میں آپ جو کچھ بھی کرتے ہیں وہ ایک ڈیجیٹل نقش چھوڑتا ہے جو آپ کے PAN کے ساتھ، براہ راست ٹیکس ڈیپارٹمنٹ تک جاتا ہے۔</p>\n<p>پہلا ذریعہ سیکیورٹیز ٹرانزیکشن ٹیکس ہے، جسے عام طور پر STT کہا جاتا ہے۔ جب بھی آپ ایکسچینج پر شیئرز، فیوچرز، یا آپشنز خریدتے یا بیچتے ہیں، موقع پر ہی ایک چھوٹا سا ٹیکس جمع کیا جاتا ہے۔ 5,00,000 روپے کا ایک فیوچر لاٹ بیچیں اور 5,00,000 میں سے 0.05% کا STT، جو کہ 250 روپے ہے، خود بخود لے لیا جاتا ہے۔ ڈیلیوری کے لیے 100 روپے میں 500 شیئرز خریدیں، اور 50,000 میں سے 0.1% کا STT، جو کہ 50 روپے ہے، اکٹھا کیا جاتا ہے۔ ہو سکتا ہے کہ آپ ان چھوٹی مقداروں کو بھی نہ دیکھیں، لیکن ہر ایک ایک مہر شدہ ریکارڈ ہے کہ آپ کے نام کے نیچے، کس قیمت پر تجارت ہوئی۔</p>\n<p>دوسرا ذریعہ سالانہ معلومات کا بیان، یا AIS ہے۔ یہ ایک سالانہ خلاصہ ہے جو محکمہ آپ کے لیے تیار کرتا ہے، جو آپ کے تجارت، منافع، سود، بڑی خریداریوں، اور بہت کچھ کو جمع کرتا ہے، یہ سب بینکوں، بروکرز اور ایکسچینجز سے جمع ہوتا ہے۔ آپ کا بروکر آپ کے تجارتی ڈیٹا کی اطلاع دیتا ہے۔ ایکسچینج ٹرن اوور کی اطلاع دیتا ہے۔ آپ کے فائل کرنے کے لیے بیٹھنے سے بہت پہلے، یہ سب ایک جگہ، آپ کے PAN پر ٹیگ کیا جاتا ہے۔</p>\n<p>لہذا اصل تصویر اس کے برعکس ہے جو ابتدائی تصور کرتے ہیں۔ محکمہ اکثر آپ کے تجارتی سال کی شکل آپ سے پہلے جانتا ہے۔ فائل کرنا آپ رضاکارانہ طور پر ایک راز نہیں ہے۔ یہ آپ ایک کہانی کی تصدیق کر رہے ہیں جو وہ پہلے ہی آدھے جانتے ہیں۔ جب آپ کی واپسی ان کے ریکارڈ سے میل کھاتی ہے تو زندگی پرسکون ہوتی ہے۔ جب ایسا نہیں ہوتا ہے، یا جب اس کے مقابلے میں کوئی واپسی نہیں ہوتی ہے، تو وہ مماثلت بالکل وہی ہے جو نوٹس کو متحرک کرتی ہے۔</p>\n<p>اسے سکول حاضری کے رجسٹر کی طرح سمجھیں جسے کوئی اور پہلے سے رکھ رہا ہے۔ جب بھی آپ تجارت کرتے ہیں آپ کا بروکر آپ کو نشان زد کرتا ہے، اور ایکسچینج ہر پوزیشن کے سائز کو نوٹ کرتا ہے۔ سال کے آخر تک آپ کے نام کے ساتھ ایک مکمل ریکارڈ موجود ہے۔ اپنا ریٹرن فائل کرنا صرف یہ ہے کہ آپ اسی رجسٹر پر دستخط کرتے ہیں اور اس کے کہنے سے اتفاق کرتے ہیں۔ دستخط کرنے سے انکار کرنے سے اندراجات مٹ نہیں جاتے۔ یہ آپ کو صرف ایک شخص کی طرح دکھاتا ہے جو کسی ایسے ریکارڈ کی تصدیق نہیں کرے گا جو باقی سب پہلے ہی پڑھ سکتے ہیں۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>آپ فائل کر کے اپنی تجارت ظاہر نہیں کرتے۔ وہ پہلے ہی STT اور AIS کے ذریعے رپورٹ کیے گئے ہیں، آپ کے PAN پر ٹیگ کیے گئے ہیں۔ فائل کرنے سے آپ کا ورژن ان سے مماثل ہوتا ہے، جو آپ کو پریشانی سے دور رکھتا ہے۔</p>\n</div></div>\n<h2 id=\"profit-or-loss-you-still-file\">نفع یا نقصان، آپ پھر بھی فائل کریں۔</h2>\n<p>یہاں ایک ہی عادت ہے جس نے کرناٹک کے کسان کو بچایا ہوگا۔ آپ ہر سال تجارت کرتے ہوئے اپنا ریٹرن فائل کرتے ہیں، چاہے آپ نے پیسہ کمایا یا کھویا۔ نقصان فائلنگ کو چھوڑنے کی وجہ نہیں ہے۔ نقصان اضافی احتیاط کے ساتھ فائل کرنے کی ایک وجہ ہے، کیونکہ اس کی اطلاع دینا ہی آپ کی حفاظت کرتا ہے۔</p>\n<p>نقصان کی اطلاع دینا دو اچھے کام کرتا ہے۔ سب سے پہلے، یہ محکمے کو سچ بتاتا ہے، اس لیے بعد میں کوئی بھی آپ کے کاروبار کو آمدنی نہیں سمجھ سکتا۔ دوسرا، مناسب طریقے سے اطلاع دی گئی اور وقت پر ہونے والے نقصان کو آگے بڑھایا جا سکتا ہے اور بعد میں زیادہ منافع بخش سالوں میں ٹیکس کو کم کرنے کے لیے استعمال کیا جا سکتا ہے۔ واپسی کو چھوڑنا دونوں فائدے کو دور کر دیتا ہے۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>فرض کریں کہ اس سال آپ کی فیوچر اور آپشنز ٹریڈنگ 2,00,000 روپے کے خالص نقصان میں ختم ہوتی ہے۔ آپ اپنا ریٹرن وقت پر فائل کریں اور ایمانداری سے رپورٹ کریں۔ اگلے سال آپ کی ٹریڈنگ بدل جائے گی اور آپ کو 3,00,000 روپے کا منافع ہوگا۔ چونکہ آپ نے پچھلے سال کے نقصان کی اطلاع دی اور آگے بڑھایا، اس لیے آپ اسے اس سال کے فائدے کے مقابلے میں ختم کر سکتے ہیں۔ آپ پر مکمل 3,00,000 کی بجائے صرف 3,00,000 مائنس 2,00,000، جو کہ 1,00,000 روپے ہے، پر ٹیکس لگایا جاتا ہے۔ آپ نے جس نقصان کی اطلاع دینے کی زحمت کی وہ حقیقی رقم بن گئی۔ اگر آپ خاموش رہتے تو وہ 2,00,000 روپے غائب ہو جاتے۔</p>\n</div></div>\n<p>یہ فائلنگ کی خاموش طاقت ہے۔ یہاں تک کہ ایک تکلیف دہ سال کو بھی مستقبل کی بچت میں تبدیل کیا جاسکتا ہے، لیکن صرف اس صورت میں جب آپ اسے واپسی میں لکھیں جو وقت پر محکمہ تک پہنچ جائے۔</p>\n<p>کسان کے توازن کو برقرار رکھنے کے لیے ایک دوسری، نرم کہانی پر غور کریں۔ پریا نے ایک سال کے لیے فیوچر اور آپشنز کا کاروبار کیا اور 1,50,000 روپے کی کمی واقع ہوئی۔ وہ مایوس تھی، لیکن اس نے پھر بھی اپنا ریٹرن فائل کیا اور آخری تاریخ سے پہلے نقصان کی اطلاع دی۔ دو سال بعد اس نے اپنی غلطیوں سے سبق سیکھا اور 4,00,000 روپے کا منافع کمایا۔ چونکہ اس کے پہلے کے نقصان کی اطلاع دی گئی تھی اور اسے آگے بڑھایا گیا تھا، اس لیے اس نے اس منافع کے مقابلے میں 1,50,000 روپے مقرر کیے تھے اور اس پر صرف 2,50,000 روپے ٹیکس لگایا گیا تھا۔ وہ نقصان جو ایک بار خالص درد کی طرح محسوس ہوتا تھا اس کے مستقبل کے ٹیکس میں حقیقی کمی کے طور پر واپس آیا۔ اس وقت اس نے صرف ایک ہی کام کیا تھا وہ فائل تھی۔ اس کے بعد جو کچھ اچھا ہوا وہ نظم و ضبط کے اس ایک چھوٹے سے عمل سے پروان چڑھا۔</p>\n<h2 id=\"what-this-course-will-walk-you-through\">یہ کورس آپ کو کس چیز سے گزرے گا۔</h2>\n<p>تاجروں کے لیے ٹیکس زیادہ تر خوفناک محسوس ہوتا ہے کیونکہ کوئی بھی اس کی سادہ زبان میں وضاحت نہیں کرتا۔ یہ کورس اس کو ٹھیک کرنے کے لیے بنایا گیا ہے، ایک وقت میں ایک چھوٹا سا خیال، روپوں میں مثالوں اور کہانیوں کے ساتھ جن سے آپ تعلق رکھ سکتے ہیں۔</p>\n<p>آنے والے ابواب میں آپ سیکھیں گے کہ آپ کی آمدنی کن تین بالٹیوں میں پڑ سکتی ہے، اور کیوں بالٹی رقم سے زیادہ اہمیت رکھتی ہے۔ آپ دیکھیں گے کہ ٹیکس کا نیا نظام کس طرح کام کرتا ہے، اس کے سلیب، اس کی چھوٹ، اور ایڈوانس ٹیکس کی آخری تاریخ۔ آپ حصص اور میوچل فنڈز پر کیپیٹل گین کو سمجھیں گے، وہ چارجز جو ہر تجارت پر لگتے ہیں، اور کیوں فیوچرز اور آپشنز کو کیپٹل گین کے بجائے کاروباری آمدنی کے طور پر سمجھا جاتا ہے۔ آپ ٹرن اوور، ٹیکس آڈٹ، اور نقصانات کو کیسے ختم کیا جا سکتا ہے اور آگے بڑھایا جا سکتا ہے کے خیال کو پورا کریں گے۔ بعد کے ابواب US اسٹاکس، غیر ملکی اثاثوں کے انکشاف، کرپٹو، اور آخر میں ایک سادہ سال بھر کی چیک لسٹ کا احاطہ کرتے ہیں جس کی آپ حقیقت میں پیروی کرسکتے ہیں۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>محفوظ رہنے کے لیے آپ کو قانونی نمبروں کو حفظ کرنے کی ضرورت نہیں ہے۔ آپ کو تین عادات کی ضرورت ہے۔ ہر سال فائل کریں، وقت پر فائل کریں، اور کھوئے ہوئے سال میں بھی ایمانداری سے رپورٹ کریں۔ اس کورس میں باقی سب کچھ ان تینوں پر بنتا ہے۔</p>\n</div></div>\n<p>مقصد آپ کو اکاؤنٹنٹ میں تبدیل کرنا نہیں ہے۔ یہ خوف کو دور کرنے کے لیے ہے، تاکہ جب فائلنگ سیزن آئے تو آپ فکر مند اور الجھن کے بجائے پرسکون اور تیار محسوس کریں۔ کسان کی کہانی انتہائی ہے، لیکن اس کا سبق نرم ہے۔ ٹیکس کی پریشانی تقریبا کبھی نقصان کرنے سے نہیں آتی ہے۔ یہ اس کے بارے میں کچھ نہ کہنے سے آتا ہے۔ ایک بار جب آپ ہر سال رپورٹ کرنے کا فیصلہ کرتے ہیں، تو اس پورے موضوع کا سب سے خوفناک ورژن آپ کے پیچھے ہے۔</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>اطلاع شدہ نقصان بے ضرر ہے۔ غیر رپورٹ شدہ اکاؤنٹ وہ ہے جو خطرناک ہو جاتا ہے۔ سب سے سستا بیمہ جو ایک تاجر خرید سکتا ہے وہ ہر سال، وقت پر جمع کرائی گئی واپسی ہے۔</p>\n</div></div>\n<p>یہ باب صرف سیکھنے کے لیے ہے اور ٹیکس کا مشورہ نہیں ہے۔ ٹیکس کے قوانین اور شرحیں ہر سال تبدیل ہوتی ہیں، اس لیے فائل کرنے سے پہلے براہ کرم ایک قابل چارٹرڈ اکاؤنٹنٹ سے اپنی صورتحال کی تصدیق کریں۔</p>\n","toc":[{"level":2,"text":"کس طرح ایک چھوٹا سا نقصان ایک بڑا مطالبہ بن گیا","id":"how-a-small-loss-became-a-giant-demand"},{"level":2,"text":"محکمہ پہلے ہی ہر تجارت کو دیکھتا ہے۔","id":"the-department-already-sees-every-trade"},{"level":2,"text":"نفع یا نقصان، آپ پھر بھی فائل کریں۔","id":"profit-or-loss-you-still-file"},{"level":2,"text":"یہ کورس آپ کو کس چیز سے گزرے گا۔","id":"what-this-course-will-walk-you-through"}],"imgCount":1,"hasContent":true},"2":{"html":"<p>تین لوگوں کی تصویر بنائیں جو اپنا دن اسٹاک مارکیٹ میں گزارتے ہیں۔ پہلے اچھی کمپنیوں کے حصص خریدتا ہے اور انہیں سالوں تک اپنے پاس رکھتا ہے، صرف اور صرف قیمت چیک کرتا ہے۔ دوسرا اسکرین پر چپکا ہوا، ایک ہی دن میں ایک ہی اسٹاک کی خرید و فروخت کرتا ہے، چھوٹی چھوٹی حرکتوں کو نچوڑتا ہے۔ تیسرا فیوچر اور آپشنز کی تجارت کرتا ہے، بڑی پوزیشنیں لے کر جو تیزی سے جھومتا ہے۔ ایک بیرونی کے نزدیک وہ سب صرف \"تجارتی\" ہیں۔ ٹیکس ڈیپارٹمنٹ کے لیے، وہ تین مکمل طور پر مختلف قسم کے ٹیکس دہندگان ہیں، جن پر تین مختلف قواعد کے تحت ٹیکس لگایا جاتا ہے۔</p>\n<p>یہ پورے کورس میں سب سے اہم خیال ہے، اور یہ وہ بھی ہے جو ابتدائی طور پر اکثر غلط ہو جاتا ہے۔ آپ جو ٹیکس ادا کرتے ہیں اس کا انحصار صرف اس بات پر نہیں ہوتا کہ آپ نے کتنا کمایا ہے۔ یہ سب سے پہلے اس بات پر منحصر ہے کہ آپ کی سرگرمی کس بالٹی میں آتی ہے۔ بالٹی کو صحیح طریقے سے حاصل کریں، اور تقریبا ہر چیز کی پیروی کریں. اسے غلط سمجھیں، اور آپ بہت زیادہ ادائیگی کر سکتے ہیں، قیمتی فوائد سے محروم ہو سکتے ہیں، یا ریٹرن فائل کر سکتے ہیں جسے محکمہ عیب دار قرار دے کر مسترد کرتا ہے۔</p>\n<h2 id=\"the-three-buckets-at-a-glance\">ایک نظر میں تین بالٹیاں</h2>\n<p>اس کورس میں مارکیٹ کی ہر قسم کی سرگرمی تین میں سے ایک بالٹی میں گرتی ہے۔ ہر بالٹی کا اپنا اصول ہوتا ہے کہ آمدنی پر کس طرح ٹیکس لگایا جاتا ہے اور اتنا ہی اہم، اس کا اپنا اصول ہوتا ہے کہ نقصان کس چیز کے خلاف ہو سکتا ہے۔ \"سیٹ آف\" کا سیدھا مطلب ہے کہ کچھ فائدہ کو منسوخ کرنے کے لیے نقصان کا استعمال کریں، لہذا آپ صرف اس پر ٹیکس ادا کرتے ہیں جو بچا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>لین دین کی قسم</th>\n<th>کون سی بالٹی</th>\n<th>کیا نقصان کے خلاف مقرر کیا جا سکتا ہے</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>مستقبل اور اختیارات (ایکویٹی، کموڈٹی، کرنسی)</td>\n<td>غیر قیاس آرائی پر مبنی کاروباری آمدنی</td>\n<td>تنخواہ کے علاوہ زیادہ تر آمدنی کے سربراہ</td>\n</tr>\n<tr>\n<td>انٹرا ڈے ایکویٹی ٹریڈنگ</td>\n<td>قیاس آرائی پر مبنی کاروباری آمدنی</td>\n<td>صرف قیاس آرائی پر مبنی آمدنی</td>\n</tr>\n<tr>\n<td>ڈیلیوری ایکویٹی اور ایکویٹی میوچل فنڈز</td>\n<td>سرمایہ نفع، قلیل مدتی یا طویل مدتی</td>\n<td>صرف کیپٹل گین</td>\n</tr>\n</tbody></table>\n<p>اس تیسرے کالم کو غور سے پڑھیں، کیونکہ اصل اختلافات اسی میں رہتے ہیں۔ فیوچر اور آپشنز کا نقصان لچکدار ہوتا ہے اور اسے کئی قسم کی آمدنی کے خلاف سیٹ آف کیا جا سکتا ہے۔ انٹرا ڈے نقصان کو ایک چھوٹے باکس میں بند کر دیا جاتا ہے اور اسے صرف دوسرے انٹرا ڈے طرز کے فوائد کے لیے استعمال کیا جا سکتا ہے۔ سرمائے کا نقصان صرف سرمائے کے نفع کو پورا کر سکتا ہے۔ ایک ہی تاجر، ایک ہی بازار، تین بالکل مختلف اصول کتابیں۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/taxation/images/diagram-income-buckets.png\" alt=\"مارکیٹ کی ایک ہی سرگرمی تین ٹیکس بالٹیوں میں تقسیم ہوتی ہے۔ ڈیلیوری اور میوچل فنڈز کیپٹل گین ہیں، انٹرا ڈے قیاس آرائی پر مبنی کاروباری آمدنی ہے، اور فیوچرز اور آپشنز غیر قیاس آرائی پر مبنی کاروباری آمدنی ہیں، ہر ایک کا اپنا مقررہ اصول ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>مارکیٹ کی ایک ہی سرگرمی تین ٹیکس بالٹیوں میں تقسیم ہوتی ہے۔ ڈیلیوری اور میوچل فنڈز کیپٹل گین ہیں، انٹرا ڈے قیاس آرائی پر مبنی کاروباری آمدنی ہے، اور فیوچرز اور آپشنز غیر قیاس آرائی پر مبنی کاروباری آمدنی ہیں، ہر ایک کا اپنا مقررہ اصول ہے۔</figcaption></figure>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ٹریڈر ٹیکس میں پہلا سوال کبھی نہیں ہوتا کہ \"میں نے کتنا کمایا\"۔ یہ \"یہ کس بالٹی میں گرتا ہے\" ہے۔ بالٹی ٹیکس کی شرح، آپ کے دائر کردہ فارم، اور آپ کے نقصانات کو منسوخ کرنے کی اجازت دینے کا فیصلہ کرتی ہے۔</p>\n</div></div>\n<h2 id=\"the-simple-test-for-each-bucket\">ہر بالٹی کے لیے آسان ٹیسٹ</h2>\n<p>آپ کو اپنے کاروبار کو ترتیب دینے کے لیے قانونی تربیت کی ضرورت نہیں ہے۔ کچھ سادہ سوالات تقریبا کسی بھی سرگرمی کو صحیح بالٹی میں رکھیں گے۔</p>\n<p>پہلے پوچھیں، کیا میں نے ڈیلیوری لی اور شیئرز رکھے، یہاں تک کہ راتوں رات؟ اگر حصص درحقیقت آپ کے اکاؤنٹ میں داخل ہوئے اور آپ نے انہیں اپنے پاس رکھا تو یہ کیپٹل گین بالٹی ہے۔ آیا فائدہ قلیل مدتی ہے یا طویل مدتی اس کا انحصار صرف اس بات پر ہے کہ آپ نے کتنی دیر تک قبضہ کیا، جس کا بعد کے باب میں مکمل احاطہ کیا گیا ہے۔</p>\n<p>اگلا پوچھیں، کیا میں نے ڈیلیوری لیے بغیر وہی اسٹاک ایک ہی دن خریدا اور بیچا؟ یہ انٹرا ڈے ایکویٹی ٹریڈنگ ہے، اور یہ قیاس آرائی پر مبنی کاروباری بالٹی میں بیٹھتا ہے۔ یہاں لفظ \"قیاس آرائی\" صرف ایک ٹیکس لیبل ہے اس تجارت کے لیے جو ڈیلیوری کے بغیر طے کی گئی ہو۔ اس کا مطلب یہ نہیں کہ آپ لاپرواہ تھے۔</p>\n<p>آخر میں پوچھیں، کیا یہ مستقبل یا اختیارات کا معاہدہ تھا؟ فیوچر اور آپشنز ہمیشہ کاروباری آمدنی ہوتی ہیں، اور خاص طور پر غیر قیاس آرائی پر مبنی کاروباری آمدنی، اس سے کوئی فرق نہیں پڑتا ہے کہ آپ نے انہیں کتنا ہی مختصر یا طویل رکھا ہو۔ یہ بہت سے ابتدائی افراد کو حیران کر دیتا ہے جو یہ سمجھتے ہیں کہ چونکہ وہ \"تجارتی\" کر رہے ہیں، یہ سرمایہ کاری کے منافع کا ہونا ضروری ہے۔ یہ نہیں ہے. ٹیکس قانون کی نظر میں فیوچرز اور آپشنز ایک کاروبار ہیں۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>لفظ \"قیاس آرائی\" ٹیکس کی اصطلاح ہے، آپ کی مہارت کا فیصلہ نہیں۔ انٹرا ڈے ایکویٹی کو صرف قیاس آرائی پر مبنی کہا جاتا ہے کیونکہ حصص کبھی ڈیلیور نہیں ہوتے ہیں۔ ایک محتاط، نظم و ضبط والا انٹرا ڈے تاجر اب بھی قیاس آرائی کی بالٹی میں بیٹھا ہے۔</p>\n</div></div>\n<h2 id=\"meet-the-three-traders\">تین تاجروں سے ملو</h2>\n<p>جب وہ چہرہ پہنتے ہیں تو قواعد بہتر رہتے ہیں، لہذا آئیے ایک سال تک اپنے تین تاجروں کی پیروی کریں۔</p>\n<p>انیتا ایک ڈیلیوری سرمایہ کار ہے۔ وہ ٹھوس کمپنیوں کے حصص خریدتی ہے اور انہیں بیٹھنے دیتی ہے۔ اس سال اس نے کچھ ہولڈنگز بیچ کر فائدہ اٹھایا۔ اس کی سرگرمی کیپٹل گین ہے۔ اگر اس کے پاس بارہ ماہ یا اس سے کم کے لیے اسٹاک ہے، تو فائدہ قلیل مدتی ہے۔ اگر طویل ہے، تو یہ طویل مدتی ہے. اگر اسے کبھی نقصان بکنا چاہیے، تو اس نقصان کو صرف دوسرے سرمائے کے نفع سے ہی ختم کیا جا سکتا ہے، اس کی تنخواہ یا اس کے بینک کے سود کے خلاف نہیں۔</p>\n<p>راوی ایک انٹرا ڈے اسکیلپر ہے۔ وہ دن کے اندر وہی حصص خریدتا اور بیچتا ہے اور کبھی ڈیلیوری نہیں لیتا۔ اس کی سرگرمی قیاس آرائی پر مبنی کاروباری آمدنی ہے، جس پر اس کے سلیب ریٹ پر ٹیکس لگایا جاتا ہے۔ یہ وہ جال ہے جس کا اسے احترام کرنا چاہئے۔ اگر وہ انٹرا ڈے پر پیسے کھو دیتا ہے، تو اس نقصان کو صرف دوسری قیاس آرائی پر مبنی آمدنی کے مقابلے میں ختم کیا جا سکتا ہے۔ یہ اس کی تنخواہ کو چھو نہیں سکتا، اور اسے فیوچر اور آپشن منافع کے مقابلے میں بھی بند نہیں کیا جا سکتا۔</p>\n<p>میرا فیوچر اور آپشنز کی تجارت کرتی ہے۔ اس کی سرگرمی غیر قیاس آرائی پر مبنی کاروباری آمدنی ہے، جس پر سلیب کی شرحوں پر بھی ٹیکس لگایا جاتا ہے، لیکن نقصان کے زیادہ دوستانہ اصول کے ساتھ۔ فیوچرز اور آپشنز کا نقصان اس کی زیادہ تر آمدنی کے مقابلے میں طے کیا جا سکتا ہے، جس میں تنخواہ بنیادی استثناء ہے۔ یہ لچک ایک وجہ ہے کہ یہ بالٹی بہت اہمیت رکھتی ہے، اور کورس بعد میں اس پر تفصیل سے واپس آتا ہے۔</p>\n<p>غور کریں کہ روی اور میرا دونوں پر ان کے سلیب ریٹ پر ٹیکس لگایا جاتا ہے، کیونکہ انٹرا ڈے اور فیوچر اور آپشنز دونوں ہی کاروباری آمدنی ہیں۔ فرق ٹیکس کی شرح کا نہیں ہے۔ یہ نقصان کا اصول ہے۔ روی کا قیاس آرائی پر مبنی نقصان سختی سے بند ہے، جبکہ میرا کا غیر قیاس آرائی پر مبنی نقصان زیادہ تر آمدنی کے سروں پر آزادانہ طور پر گھومتا ہے۔ انیتا، کیپیٹل گینز بالٹی میں بیٹھی، ایک مکمل طور پر الگ ریٹ بک کے ساتھ کھیلتی ہے جسے بعد کا ایک باب کھولتا ہے۔ تین تاجر، تین اصول کی کتابیں، اور انہیں سیدھا رکھنے کا واحد طریقہ یہ ہے کہ پہلے بالٹی کا نام لیا جائے۔</p>\n<h2 id=\"a-worked-example-of-why-the-bucket-matters\">بالٹی کیوں اہمیت رکھتی ہے اس کی ایک عملی مثال</h2>\n<p>اس پر اصلی روپیہ ڈال دیں۔ تصور کریں کہ ایک ہی سال میں آپ کے تین نتائج ہیں۔ آپ 1,00,000 روپے ٹریڈنگ فیوچر اور آپشنز کا منافع کماتے ہیں۔ انٹرا ڈے ایکویٹی ٹریڈز پر آپ کو 40,000 روپے کا نقصان ہوتا ہے۔ اور آپ ان سب کے ساتھ تنخواہ کماتے ہیں۔</p>\n<p>یہ سوچنا پرکشش ہے کہ انٹرا ڈے نقصان صرف آپ کے فیوچر اور آپشنز کے منافع کو کم کر دیتا ہے، اس لیے آپ پر 1,00,000 مائنس 40,000، جو کہ 60,000 روپے ہے ٹیکس لگے گا۔ یہ غلط ہے، اور بالٹی اصول اس کی وجہ ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>آئٹم</th>\n<th>بالٹی</th>\n<th>رقم</th>\n<th>کیا یہ ایف اینڈ او کے منافع کو کم کر سکتا ہے؟</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>ایف اینڈ او منافع</td>\n<td>غیر قیاس آرائی پر مبنی کاروبار</td>\n<td>پلس 1,00,000 روپے</td>\n<td>یہ وہ منافع ہے جس پر ٹیکس لگایا جا رہا ہے۔</td>\n</tr>\n<tr>\n<td>انٹرا ڈے نقصان</td>\n<td>قیاس آرائی کا کاروبار</td>\n<td>مائنس 40,000 روپے</td>\n<td>نہیں، قیاس آرائی پر مبنی نقصان پر باڑ لگا دی گئی ہے۔</td>\n</tr>\n</tbody></table>\n<p>آپ کا 1,00,000 روپے کا فیوچر اور آپشن منافع خود ہی کھڑا ہے اور آپ کے سلیب ریٹ پر مکمل ٹیکس لگایا جاتا ہے۔ 40,000 روپے کا انٹرا ڈے نقصان قیاس آرائی کی بالٹی میں پھنس گیا ہے۔ یہ صرف انتظار کر سکتا ہے اور مستقبل کے قیاس آرائیوں کے خلاف منسوخ ہونے کی امید کر سکتا ہے۔ دو سرگرمیاں جو آپ کے لیے ایک \"تجارتی اکاؤنٹ\" کی طرح محسوس ہوتی ہیں، قواعد کے مطابق سختی سے الگ رکھی گئی ہیں۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>وہی تاجر، وہی سال۔ ایف اینڈ او کا منافع 1,00,000 روپے، انٹرا ڈے نقصان 40,000 روپے۔ کیونکہ بالٹیاں مختلف ہوتی ہیں، انٹرا ڈے نقصان F&amp;O منافع کو کم نہیں کر سکتا۔ آپ پر آپ کے سلیب ریٹ پر F&amp;O کی مکمل 1,00,000 روپے کی آمدنی پر ٹیکس لگایا جاتا ہے، جب کہ 40,000 روپے کے انٹرا ڈے نقصان کو قیاس آرائی کی بالٹی کے اندر لے جایا جاتا ہے، مستقبل کے انٹرا ڈے منافع کو پورا کرنے کے انتظار میں۔ دونوں کو ملانا آپ کے ٹیکس کو کم کر دے گا اور آپ کی واپسی کو ناقص بنا سکتا ہے۔</p>\n</div></div>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>کبھی یہ نہ سمجھیں کہ ایک بالٹی میں نقصان دوسری بالٹی میں نفع کو ختم کر سکتا ہے۔ انٹرا ڈے نقصانات صرف انٹرا ڈے فوائد کو پورا کرتے ہیں۔ سرمائے کے نقصانات صرف سرمائے کے منافع کو پورا کرتے ہیں۔ F&amp;O نقصانات لچکدار استثنیٰ ہیں، لیکن وہ بھی تنخواہ کو چھو نہیں سکتے۔</p>\n</div></div>\n<h2 id=\"why-this-is-the-foundation\">یہ بنیاد کیوں ہے؟</h2>\n<p>ایک بار جب آپ بالٹی کو نام دے سکتے ہیں، تو کورس کے باقی حصے صفائی کے ساتھ اوپر آتے ہیں۔ سرمائے کے منافع کی اپنی شرحیں ہوتی ہیں اور طویل مدتی بمقابلہ مختصر مدت کی تقسیم۔ قیاس آرائی پر مبنی اور غیر قیاس آرائی پر مبنی کاروباری آمدنی پر آپ کے سلیب پر ٹیکس لگایا جاتا ہے اور واپسی میں کاروبار کے طور پر رپورٹ کیا جاتا ہے۔ ہر بالٹی یہ بھی فیصلہ کرتی ہے کہ آپ کو کون سا انکم ٹیکس فارم استعمال کرنا چاہیے، اور غلط فارم کا استعمال ایک عام طریقہ ہے کہ واپسی کو ناقص قرار دیا جاتا ہے۔</p>\n<p>لہذا نرخوں، چھوٹوں، یا آخری تاریخوں کے بارے میں فکر کرنے سے پہلے، ہر تجارت پر بالٹی سوال پوچھنے کے لیے اپنے آپ کو تربیت دیں۔ ڈیلیوری اور میوچل فنڈز کیپٹل گین میں جاتے ہیں۔ انٹرا ڈے ایکویٹی قیاس آرائی پر مبنی کاروبار میں جاتی ہے۔ مستقبل اور اختیارات غیر قیاس آرائی پر مبنی کاروبار میں جاتے ہیں۔ یہ واحد چھانٹنے کی عادت آپ کی فائلنگ کو صاف رکھے گی اور آپ کے نقصانات کو قانونی طور پر جتنی محنت کر سکتے ہیں۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>اپنی ہر سرگرمی کے لیے ایک سادہ نوٹ رکھیں، اسے کیپیٹل گینز، انٹرا ڈے قیاس آرائی، یا F&amp;O کاروبار کے طور پر ٹیگ کریں۔ جب فائلنگ سیزن آتا ہے، تو وہ ایک لائن والا ٹیگ آپ کو شرح، سیٹ آف کا اصول، اور فارم، سب ایک ساتھ بتاتا ہے۔</p>\n</div></div>\n<p>یہ باب صرف تعلیم کے لیے ہے اور ٹیکس کا مشورہ نہیں ہے۔ یہاں کے قوانین اور نرخ سال بہ سال تبدیل ہو سکتے ہیں، اس لیے کسی اہل چارٹرڈ اکاؤنٹنٹ سے اپنی فائلنگ کی تصدیق کریں۔</p>\n","toc":[{"level":2,"text":"ایک نظر میں تین بالٹیاں","id":"the-three-buckets-at-a-glance"},{"level":2,"text":"ہر بالٹی کے لیے آسان ٹیسٹ","id":"the-simple-test-for-each-bucket"},{"level":2,"text":"تین تاجروں سے ملو","id":"meet-the-three-traders"},{"level":2,"text":"بالٹی کیوں اہمیت رکھتی ہے اس کی ایک عملی مثال","id":"a-worked-example-of-why-the-bucket-matters"},{"level":2,"text":"یہ بنیاد کیوں ہے؟","id":"why-this-is-the-foundation"}],"imgCount":1,"hasContent":true},"3":{"html":"<p>دو تاجر اس سال بالکل ایک جیسی آمدنی حاصل کرتے ہیں، پھر بھی ایک دوسرے سے زیادہ ٹیکس ادا کرتا ہے۔ ان کی تجارت کے بارے میں کچھ بھی مختلف نہیں تھا۔ فرق صرف اتنا تھا کہ انہوں نے انتخاب کیا، اکثر یہ سمجھے بغیر کہ وہ کس ٹیکس نظام کے تحت بیٹھے تھے۔ ہندوستان اب آپ کی آمدنی پر ٹیکس لگانے کے لیے دو متوازی نظام چلاتا ہے، ایک پرانا اور دوسرا نیا، اور ان کے درمیان انتخاب کے اصول خاموشی سے فیصلہ کرتے ہیں کہ آپ کتنی رقم رکھتے ہیں۔</p>\n<p>اچھی خبر یہ ہے کہ زیادہ تر لوگوں کے لیے فیصلہ پہلے سے زیادہ آسان ہو گیا ہے۔ نئی حکومت اب پہلے سے طے شدہ ہے۔ اگر آپ کچھ نہیں کرتے ہیں تو آپ اس میں ہیں۔ بہت سارے تاجروں اور سرمایہ کاروں کے لیے، یہ ڈیفالٹ بھی بہتر سودا ہے، کیونکہ نئی حکومت وسیع تر سلیب اور فراخدلی چھوٹ پیش کرتی ہے۔ پھر بھی، آپ کو دونوں کو سمجھنا چاہیے، کیونکہ چند حالات پرانی حکومت کو دوسری نظر آنے کے قابل بناتے ہیں، اور سوئچنگ کی اپنی اصولی کتاب ہوتی ہے۔</p>\n<h2 id=\"the-new-regime-is-the-default\">نئی حکومت پہلے سے طے شدہ ہے۔</h2>\n<p>سب سے اہم حقیقت کے ساتھ شروع کریں. مالی سال 2025-26 کے لیے، جو کہ سال 2026-27 ہے، نیا ٹیکس نظام خود بخود لاگو ہوتا ہے جب تک کہ آپ فعال طور پر دوسری صورت میں انتخاب نہ کریں۔ آپ آپٹ ان نہیں کرتے۔ آپ پہلے ہی اندر ہیں۔</p>\n<p>نئی حکومت آمدنی کو کئی سلیبوں میں پھیلا کر آپ کے ٹیکس کو آسان رکھتی ہے، ہر ایک پر بڑھتی ہوئی شرح سے ٹیکس لگایا جاتا ہے۔ آپ پہلے سلیب پر کچھ نہیں دیتے، اگلے پر کم شرح، اور اسی طرح، لہذا ہر بینڈ کے اندر صرف آمدنی کے حصے پر اس بینڈ کی شرح پر ٹیکس لگایا جاتا ہے۔ یہاں مکمل سلیب ٹیبل ہے کیونکہ چیزیں تشخیصی سال 2026-27 کے لیے کھڑی ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>قابل ٹیکس آمدنی</th>\n<th>ٹیکس کی شرح</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>4 لاکھ روپے تک</td>\n<td>صفر</td>\n</tr>\n<tr>\n<td>4 لاکھ سے 8 لاکھ روپے</td>\n<td>5%</td>\n</tr>\n<tr>\n<td>8 لاکھ سے 12 لاکھ روپے</td>\n<td>10%</td>\n</tr>\n<tr>\n<td>12 لاکھ سے 16 لاکھ روپے</td>\n<td>15%</td>\n</tr>\n<tr>\n<td>16 لاکھ سے 20 لاکھ روپے</td>\n<td>20%</td>\n</tr>\n<tr>\n<td>20 لاکھ سے 24 لاکھ روپے</td>\n<td>25%</td>\n</tr>\n<tr>\n<td>24 لاکھ روپے سے زیادہ</td>\n<td>30%</td>\n</tr>\n</tbody></table>\n<p>نوٹ کریں کہ سلیب کیسے کام کرتے ہیں۔ اگر آپ کی آمدنی 10 لاکھ روپے ہے، تو آپ پوری رقم پر 10٪ ادا نہیں کرتے ہیں۔ آپ پہلے 4 لاکھ پر صفر، اگلے 4 لاکھ پر 5%، اور تیسرے بینڈ میں بیٹھنے والے 2 لاکھ پر صرف 10% ادا کرتے ہیں۔ یہ مرحلہ وار ڈیزائن یہی وجہ ہے کہ آپ کی اوسط ٹیکس کی شرح ہمیشہ آپ کے اوپری سلیب سے کم ہوتی ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/taxation/images/diagram-new-regime-slabs.png\" alt=\"تشخیصی سال 2026-27 کے نئے نظام کے تحت، آمدنی پر بینڈ کے حساب سے ٹیکس لگایا جاتا ہے، پہلے 4 لاکھ روپے پر صفر سے لے کر 24 لاکھ روپے سے زیادہ کی آمدنی پر 30 فیصد تک۔ ہر بینڈ کے اندر صرف آمدنی کا ٹکڑا اس بینڈ کی شرح پر ٹیکس لگایا جاتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>تشخیصی سال 2026-27 کے نئے نظام کے تحت، آمدنی پر بینڈ کے حساب سے ٹیکس لگایا جاتا ہے، پہلے 4 لاکھ روپے پر صفر سے لے کر 24 لاکھ روپے سے زیادہ کی آمدنی پر 30 فیصد تک۔ ہر بینڈ کے اندر صرف آمدنی کے ٹکڑوں پر اس بینڈ کی شرح پر ٹیکس لگایا جاتا ہے۔</figcaption></figure>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>تشخیصی سال 2026-27 کے لیے نیا نظام خودکار ہے۔ آپ پر سلیب کے حساب سے ٹیکس لگایا جاتا ہے، لہذا ہر بینڈ کے اندر آنے والی آمدنی کا صرف حصہ اس بینڈ کی شرح سے وصول کیا جاتا ہے۔ سرخی 30% صرف 24 لاکھ روپے سے زیادہ کی آمدنی پر لاگو ہوتی ہے، آپ کی پوری آمدنی پر نہیں۔</p>\n</div></div>\n<h2 id=\"the-rebate-that-wipes-out-tax-up-to-rs-12-lakh\">چھوٹ جو 12 لاکھ روپے تک کے ٹیکس کو ختم کرتی ہے۔</h2>\n<p>یہ وہ حصہ ہے جو سب سے چھوٹے اور درمیانے سائز کے کمانے والوں کو خوش کرتا ہے۔ نئی حکومت میں سیکشن 87A کے تحت 60,000 روپے تک کی چھوٹ ہے۔ چھوٹ اس ٹیکس کی براہ راست کمی ہے جو آپ پر واجب الادا ہے، جو سلیب کے حساب کے بعد لاگو کیا جاتا ہے۔ اس کی وجہ سے، 12 لاکھ روپے تک قابل ٹیکس آمدنی والا ٹیکس دہندہ مؤثر طریقے سے کوئی ٹیکس ادا نہیں کرتا ہے۔</p>\n<p>دیکھیں کہ حقیقی نمبروں کے ساتھ یہ کیسے ہوتا ہے۔ فرض کریں کہ آپ کی قابل ٹیکس آمدنی بالکل 12 لاکھ روپے ہے۔ اسے سلیب کے ذریعے چلائیں۔ پہلے 4 لاکھ صفر ہے۔ اگلے 4 لاکھ، 4 سے 8 لاکھ تک، 5 فیصد ٹیکس ہے، جو کہ 20،000 روپے ہے۔ 8 سے 12 لاکھ تک کے ٹکڑوں پر 10 فیصد ٹیکس ہے، جو کہ 40،000 روپے ہے۔ ان کو شامل کریں اور آپ کا ٹیکس چھوٹ سے پہلے 20,000 جمع 40,000 ہے، جو کہ 60,000 روپے ہے۔ سیکشن 87A 60,000 روپے تک کی چھوٹ پھر بالکل اسی رقم کو منسوخ کر دیتی ہے، جس سے آپ کا ٹیکس صفر رہ جاتا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>12 لاکھ روپے کے اندر انکم بینڈ</th>\n<th>شرح</th>\n<th>ٹیکس</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>پہلے 4 لاکھ روپے</td>\n<td>صفر</td>\n<td>0 روپے</td>\n</tr>\n<tr>\n<td>4 لاکھ سے 8 لاکھ روپے</td>\n<td>5%</td>\n<td>20,000 روپے</td>\n</tr>\n<tr>\n<td>8 لاکھ سے 12 لاکھ روپے</td>\n<td>10%</td>\n<td>40,000 روپے</td>\n</tr>\n<tr>\n<td>چھوٹ سے پہلے ٹیکس</td>\n<td></td>\n<td>60,000 روپے</td>\n</tr>\n<tr>\n<td>کم سیکشن 87A چھوٹ</td>\n<td></td>\n<td>مائنس 60,000 روپے</td>\n</tr>\n<tr>\n<td>حتمی ٹیکس</td>\n<td></td>\n<td>0 روپے</td>\n</tr>\n</tbody></table>\n<p>پرانی حکومت کی اپنی، بہت چھوٹی چھوٹ ہے، 12,500 روپے تک، اور صرف اس صورت میں جب آمدنی 5 لاکھ روپے یا اس سے کم ہو۔ آپ دیکھ سکتے ہیں کہ نئی حکومت بہت سے لوگوں کو کیوں اپیل کرتی ہے۔ اس کی چھوٹ بہت زیادہ ہے، آمدنی کے پورے 12 لاکھ روپے تک۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>12 لاکھ روپے کی \"کوئی ٹیکس نہیں\" لائن چھوٹ سے آتی ہے، صفر سے نہیں۔ آپ کا ٹیکس اب بھی عام طور پر شمار کیا جاتا ہے، اور پھر چھوٹ اسے منسوخ کر دیتی ہے۔ اس لائن کو عبور کریں، یہاں تک کہ تھوڑا سا، اور چھوٹ اب پوری طرح سے لاگو نہیں ہوتی ہے، لہذا ٹیکس دوبارہ ظاہر ہوتا ہے۔ مارجنل ریلیف نامی ایک چھوٹی ریلیف 12 لاکھ روپے سے اوپر کی چھلانگ کو نرم کرتی ہے، تاکہ اضافی آمدنی کی ایک چھوٹی سی رقم غیر متناسب طور پر بڑے ٹیکس کو متحرک نہ کرے۔</p>\n</div></div>\n<h2 id=\"one-catch-for-traders-and-investors\">تاجروں اور سرمایہ کاروں کے لیے ایک کیچ</h2>\n<p>سیکشن 87A چھوٹ فراخدلی ہے، لیکن اس کی ایک اہم حد ہے جو خاص طور پر ان لوگوں کے لیے اہمیت رکھتی ہے جو تجارت اور سرمایہ کاری کرتے ہیں۔ چھوٹ آپ کی عام آمدنی پر لاگو ہوتی ہے جس پر سلیب ریٹ پر ٹیکس لگایا جاتا ہے، جس میں F&amp;O اور انٹرا ڈے منافع شامل ہیں۔ یہ NOT ایک خاص، مقررہ شرح پر ٹیکس کی گئی آمدنی تک توسیع کرتا ہے، اور ایک سرمایہ کار کے لیے دو بڑے ہیں درج شدہ حصص پر قلیل مدتی کیپٹل گین (سیکشن 111A کے تحت 20% پر ٹیکس) اور حصص پر طویل مدتی کیپٹل گین (سیکشن 112A کے تحت 12.5% ​​پر ٹیکس)۔</p>\n<p>عملی اثر یہ ہے۔ آپ کی کل آمدنی 12 لاکھ روپے کے اندر ہو سکتی ہے اور پھر بھی ٹیکس واجب الادا ہے، اگر اس آمدنی کا ایک حصہ ایکویٹی کیپٹل گین ہے۔ سلیب ریٹ والے حصے کو چھوٹ کے ذریعے ختم کیا جا سکتا ہے، لیکن خصوصی شرح کیپٹل گین پر ٹیکس کا الگ سے حساب لگایا جاتا ہے اور اسے چھوٹ کے ذریعے منسوخ نہیں کیا جاتا ہے۔ لہذا ایک سرمایہ کار جو حصص فروخت کرتا ہے اسے کبھی بھی یہ نہیں سمجھنا چاہئے کہ 12 لاکھ روپے سے کم رہنے کا مطلب خود بخود صفر ٹیکس ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>12 لاکھ روپے کی \"کوئی ٹیکس نہیں\" کی سہولت سلیب ریٹ کی آمدنی پر لاگو ہوتی ہے، ایکویٹی کیپیٹل گین پر نہیں۔ 20% پر قلیل مدتی فوائد اور 12.5% ​​پر طویل مدتی فوائد ان کے اپنے مقررہ نرخوں پر وصول کیے جاتے ہیں اور سیکشن 87A کی چھوٹ انہیں نہیں مٹاتی ہے۔ اگر آپ حصص یا ایکویٹی فنڈز بیچتے ہیں، تو خود ہی کیپٹل گین ٹیکس لگائیں، یہاں تک کہ جب آپ کی کل آمدنی چھوٹ کے اندر محفوظ نظر آئے۔</p>\n</div></div>\n<h2 id=\"a-worked-tax-example-above-the-rebate-line\">ریبیٹ لائن کے اوپر ٹیکس کی ایک کام کی مثال</h2>\n<p>آئیے ایک ایسے تاجر کی پیروی کریں جس کی آمدنی آرام سے چھوٹ سے اوپر ہے، تاکہ آپ دیکھ سکیں کہ حقیقی ٹیکس ادا ہوتا ہے۔ میرا کی سال بھر کے لیے قابل ٹیکس آمدنی، اس کے تمام تجارتی منافع اور دیگر کمائیوں کے بعد، 16 لاکھ روپے ہے۔ وہ بطور ڈیفالٹ نئی حکومت میں ہے۔</p>\n<p>اسے سلیب کے ذریعے سلیب چلائیں۔ پہلے 4 لاکھ صفر ہے۔ 4 سے 8 لاکھ تک، 4 لاکھ کا 5% 20,000 روپے ہے۔ 8 سے 12 لاکھ تک، 4 لاکھ کا 10% 40,000 روپے ہے۔ 12 سے 16 لاکھ تک، 4 لاکھ کا 15% 60،000 روپے ہے۔ اس کی آمدنی 16 لاکھ پر رک جاتی ہے، لہذا اعلی بینڈ لاگو نہیں ہوتے ہیں۔ ٹکڑوں کو شامل کریں، 20,000 جمع 40,000 جمع 60,000، اور سیس سے پہلے اس کا ٹیکس 1,20,000 روپے ہے۔ کیونکہ اس کی آمدنی 12 لاکھ روپے سے زیادہ ہے، اس لیے 87A کی مکمل چھوٹ اسے یہاں نہیں بچاتی، اس لیے ٹیکس کھڑا ہے۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>میرا کی قابل ٹیکس آمدنی 16 لاکھ روپے، نئی حکومت۔ ٹیکس پہلے 4 لاکھ پر صفر، 4 سے 8 لاکھ بینڈ پر 20,000 روپے، 8 سے 12 لاکھ بینڈ پر 40,000 روپے، اور 12 سے 16 لاکھ بینڈ پر 60,000 روپے بنتا ہے۔ یہ سیس سے پہلے 1,20,000 روپے بنتا ہے۔ 1,20,000 پر 4% صحت اور تعلیم کا سیس 4,800 روپے ہے۔ اس کا حتمی ٹیکس 1,20,000 جمع 4,800 ہے، جو کہ 1,24,800 روپے ہے۔</p>\n</div></div>\n<h2 id=\"surcharge-and-the-four-percent-cess\">سرچارج اور چار فیصد سیس</h2>\n<p>دو ایڈ آنز سلیب ٹیکس کے اوپر بیٹھے ہیں، اس لیے ان کو ابھی جاننے میں مدد ملتی ہے۔</p>\n<p>سرچارج ایک اضافی چارج ہے جو صرف زیادہ آمدنیوں پر لاگو ہوتا ہے، جب کل ​​آمدنی 50 لاکھ روپے سے تجاوز کر جاتی ہے اور آمدنی میں مزید اضافے کے ساتھ درجات میں اضافہ ہوتا ہے۔ زیادہ تر ابتدائی تاجر اس تک کبھی نہیں پہنچ پاتے، لیکن یہ جاننا ضروری ہے کہ یہ موجود ہے لہذا ایک بڑا سال آپ کو حیران نہیں کرتا۔</p>\n<p>سیس سب پر لاگو ہوتا ہے۔ آپ کے ٹیکس کے بعد، اور اگر کوئی سرچارج ہے تو، سب سے اوپر 4% کا ہیلتھ اور ایجوکیشن سیس شامل کیا جاتا ہے۔ میرا کے کیس میں ان کے 1,20,000 روپے کے ٹیکس پر 4% سیس 4,800 روپے تھا، یہی وجہ ہے کہ اس کا حتمی بل 1,24,800 روپے آیا۔ سیس فی روپیہ چھوٹا ہے لیکن یہ ہمیشہ ساتھ چلتا ہے، لہذا جب آپ اپنے ٹیکس کا تخمینہ لگائیں تو اسے شامل کرنا کبھی نہ بھولیں۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>جب آپ اپنے ٹیکس کا تخمینہ لگائیں تو سیس کے ساتھ ختم کریں۔ سلیب ٹیکس پر کام کریں، سرچارج صرف اس صورت میں شامل کریں جب آپ کی آمدنی بہت زیادہ ہو، پھر کل پر 4% سیس شامل کریں۔ سیس کو چھوڑنا ایک عام وجہ ہے جس کا خود اندازہ حقیقی بل سے کم ہوتا ہے۔</p>\n</div></div>\n<h2 id=\"choosing-the-old-regime-with-form-10-iea\">فارم 10-IEAکے ساتھ پرانے نظام کا انتخاب</h2>\n<p>نئی حکومت پہلے سے طے شدہ ہے، لیکن آپ کو اسے پرانی حکومت کے لیے چھوڑنے کی اجازت ہے اگر پرانی آپ کے لیے بہتر ہو، مثال کے طور پر جب آپ کے پاس دعویٰ کرنے کے لیے بڑی کٹوتیاں ہوں۔ ایک تنخواہ دار شخص کے لیے جس کی کوئی کاروباری آمدنی نہیں ہے، یہ انتخاب ہر سال آزادانہ طور پر کیا جا سکتا ہے۔ کاروباری آمدنی والے شخص کے لیے، جس میں فیوچرز اور آپشنز اور انٹرا ڈے ٹریڈرز شامل ہیں، اصول سخت ہے۔</p>\n<p>اگر آپ کی کاروباری آمدنی ہے اور آپ نئے نظام سے پرانے نظام سے آپٹ آؤٹ کرنا چاہتے ہیں، تو آپ کو فارم 10-IEAفائل کرنا ہوگا، اور آپ کو سیکشن 139(1) کے تحت اپنا ریٹرن فائل کرنے کی مقررہ تاریخ کے اندر کرنا چاہیے۔ اس ونڈو کو یاد کریں اور آپ سال بھر نئی حکومت میں رہیں۔ یہ نظر انداز کرنے کا ایک آسان قدم ہے، اور اسے نظر انداز کرنا آپ کو ایک ایسے نظام میں بند کر سکتا ہے جو آپ نہیں چاہتے تھے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>اگر آپ فیوچر اور آپشنز یا انٹرا ڈے کی تجارت کرتے ہیں، تو آپ کی کاروباری آمدنی ہے، اور پرانے نظام کو منتخب کرنے کا مطلب ہے فارم 10-IEAکو وقت پر فائل کرنا۔ اسے بھول جاؤ اور تم سال بھر کے لیے نئی حکومت میں پھنس گئے ہو۔ جلد فیصلہ کریں، آخری دن نہیں۔</p>\n</div></div>\n<p>زیادہ تر تاجروں کے لیے نئی حکومت، اس کے وسیع سلیب اور 12 لاکھ روپے تک کی چھوٹ کے ساتھ، آسان اور اکثر سستا انتخاب ہے، یہی وجہ ہے کہ یہ ڈیفالٹ ہے۔ لیکن اگر آپ بھاری کٹوتیاں کرتے ہیں، تو یہ آخری تاریخ سے پہلے دونوں کا موازنہ کرنے کے قابل ہے، مثالی طور پر ایک پیشہ ور کے ساتھ جو نمبر دونوں طریقوں سے چلا رہے ہیں۔</p>\n<p>یہ باب صرف سیکھنے کے لیے ہے اور ٹیکس کا مشورہ نہیں ہے۔ سلیبس، ریبیٹس، اور سرچارج کی حدیں ہر سال تبدیل ہو سکتی ہیں، اس لیے براہ کرم فائل کرنے سے پہلے کسی قابل چارٹرڈ اکاؤنٹنٹ سے تازہ ترین پوزیشن کی تصدیق کریں۔</p>\n","toc":[{"level":2,"text":"نئی حکومت پہلے سے طے شدہ ہے۔","id":"the-new-regime-is-the-default"},{"level":2,"text":"چھوٹ جو 12 لاکھ روپے تک کے ٹیکس کو ختم کرتی ہے۔","id":"the-rebate-that-wipes-out-tax-up-to-rs-12-lakh"},{"level":2,"text":"تاجروں اور سرمایہ کاروں کے لیے ایک کیچ","id":"one-catch-for-traders-and-investors"},{"level":2,"text":"ریبیٹ لائن کے اوپر ٹیکس کی ایک کام کی مثال","id":"a-worked-tax-example-above-the-rebate-line"},{"level":2,"text":"سرچارج اور چار فیصد سیس","id":"surcharge-and-the-four-percent-cess"},{"level":2,"text":"فارم 10-IEAکے ساتھ پرانے نظام کا انتخاب","id":"choosing-the-old-regime-with-form-10-iea"}],"imgCount":1,"hasContent":true},"4":{"html":"<p>زیادہ تر لوگ ٹیکس کو ایک بڑی ادائیگی کے طور پر تصور کرتے ہیں، جو سال میں ایک بار، سال ختم ہونے کے بعد کی جاتی ہے۔ ایک تنخواہ دار شخص کے لیے جو تقریباً ویسا ہی محسوس ہوتا ہے، کیونکہ آجر خاموشی سے ہر ماہ ایک ٹکڑا کاٹ لیتا ہے۔ لیکن تاجر اور سرمایہ کار اکثر اپنے طور پر ہوتے ہیں، اور ٹیکس کا محکمہ درحقیقت جمع کرنے کے لیے سال ختم ہونے تک انتظار نہیں کرتا۔ یہ سال بھر میں اپنا حصہ چاہتا ہے، قسطوں میں، جیسا کہ آپ کماتے ہیں۔ اس نظام کو ایڈوانس ٹیکس کہا جاتا ہے، اور اس کا غائب ہونا ایک سب سے عام اور سب سے زیادہ قابل گریز طریقوں میں سے ایک ہے جس سے تاجر اضافی ادائیگی کرتے ہیں۔</p>\n<p>جب آپ اس کے بارے میں سوچتے ہیں تو ایڈوانس ٹیکس کے پیچھے خیال درست ہے۔ حکومت سارا سال چلتی ہے، اس لیے وہ آپ کو سال بھر ٹیکس ادا کرنے کے لیے کہتی ہے، تقریباً اس کے مطابق جب آپ آمدنی کماتے ہیں۔ اگر آپ انتظار کرتے ہیں اور آخر میں پوری رقم ڈمپ کرتے ہیں، تو آپ نے مؤثر طریقے سے رقم کو روک رکھا ہے جو پہلے واجب الادا تھا، اور قانون اس تاخیر پر سود وصول کرتا ہے۔ اس جال سے مکمل طور پر پاک رہنے کے لیے چار تاریخوں اور فائل کرنے کی ایک آخری تاریخ کو سمجھنا کافی ہے۔</p>\n<h2 id=\"when-advance-tax-applies-to-you\">جب آپ پر ایڈوانس ٹیکس لاگو ہوتا ہے۔</h2>\n<p>قاعدہ جو فیصلہ کرتا ہے کہ آیا آپ کو ایڈوانس ٹیکس سے بالکل بھی پریشان ہونے کی ضرورت ہے تازگی سے آسان ہے۔ اگر سال کے لیے آپ کا کل ٹیکس، پہلے سے منبع پر کاٹے گئے کسی بھی ٹیکس کو منہا کرنے کے بعد، 10,000 روپے سے زیادہ ہے، تو آپ سے توقع کی جاتی ہے کہ آپ اسے سال بھر میں پیشگی اقساط میں ادا کریں گے۔</p>\n<p>ایک خالص تنخواہ دار شخص کے لیے یہ شاذ و نادر ہی کاٹتا ہے، کیونکہ آجر پہلے ہی ہر ماہ ٹیکس کاٹتا ہے۔ لیکن تاجر کا منافع عام طور پر بغیر ٹیکس کے حاصل ہوتا ہے۔ فیوچرز اور آپشنز، انٹرا ڈے، یا کیپٹل گین میں ایک اچھا سال آپ کے ٹیکس کو آسانی سے 10,000 روپے سے آگے بڑھا سکتا ہے، اور جس لمحے ایسا ہوتا ہے، ایڈوانس ٹیکس آپ کی ذمہ داری بن جاتا ہے۔</p>\n<p>یہ پہلی بار آنے والے بہت سے تاجروں کو حیران کر دیتا ہے۔ وہ سال کے بند ہونے کے بعد، جولائی میں ٹیکس کو ایک ہی ایونٹ کے طور پر پیش کرتے ہیں، اور یہ جان کر حیران ہیں کہ قانون ان سے پچھلے سال جون، ستمبر اور دسمبر میں رقم واپس کرنے کی توقع رکھتا ہے۔ کوئی بھی آپ کو ایڈوانس ٹیکس کے لیے بل یا یاد دہانی نہیں بھیجتا ہے۔ تخمینہ لگانے اور ادائیگی کرنے کی ذمہ داری پوری طرح آپ کے ساتھ ہے۔ یہی وجہ ہے کہ چار تاریخیں یاد رکھنے کے قابل ہیں، کیونکہ کیلنڈر دیکھنے والے واحد شخص آپ ہیں۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ٹرگر 10,000 روپے ہے۔ اگر آپ کا سال بھر کا خالص ٹیکس، پہلے ہی ذریعہ سے کٹوائے گئے کسی بھی ٹیکس کے بعد، 10,000 روپے سے زیادہ ہونے کی توقع ہے، تو آپ کو اسے پورے سال کے آخر میں ایک ساتھ ادا کرنے کی بجائے پیشگی اقساط میں ادا کرنا ہوگا۔</p>\n</div></div>\n<h2 id=\"the-four-dates-and-how-much-by-each\">چار تاریخیں اور ہر ایک کے حساب سے کتنی</h2>\n<p>ایڈوانس ٹیکس ایک ادائیگی نہیں ہے۔ یہ مالی سال میں چار پوائنٹس پر پھیلا ہوا ہے، اور ہر تاریخ میں ایک ہدف ہوتا ہے۔ ہدف مجموعی ہے، یعنی یہ وہ کل ہے جو آپ کو اس وقت تک ادا کرنا چاہیے تھا، ہر بار اضافی رقم نہیں۔ مالی سال 2025-26 کے لیے، جو کہ سال 2026-27 ہے، تاریخیں اور آپ کے کل ٹیکس کا مجموعی حصہ درج ذیل ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>کی طرف سے ادا کریں</th>\n<th>مجموعی ایڈوانس ٹیکس واجب الادا ہے۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>15 جون 2025</td>\n<td>آپ کے کل ٹیکس کا 15%</td>\n</tr>\n<tr>\n<td>15 ستمبر 2025</td>\n<td>آپ کے کل ٹیکس کا 45%</td>\n</tr>\n<tr>\n<td>15 دسمبر 2025</td>\n<td>آپ کے کل ٹیکس کا 75%</td>\n</tr>\n<tr>\n<td>15 مارچ 2026</td>\n<td>آپ کے کل ٹیکس کا 100%</td>\n</tr>\n</tbody></table>\n<p>رننگ کل کے طور پر فیصد پڑھیں۔ 15 جون تک آپ کو 15% ادا کرنا چاہیے تھا۔ 15 ستمبر تک مجموعی تعداد 45% تک بڑھ جاتی ہے، لہذا دوسری قسط وہ ہے جو آپ کو 15% سے 45% تک لے جاتی ہے۔ 15 دسمبر تک آپ کو 75% ہونا چاہیے، اور 15 مارچ تک مکمل 100% ادا ہو جانا چاہیے۔ ہر قسط آسانی سے آپ کو نئے مجموعی نشان تک لے جاتی ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/taxation/images/diagram-advance-tax.png\" alt=\"ایڈوانس ٹیکس سال بھر میں چار مراحل میں ادا کیا جاتا ہے۔ 15 جون تک آپ کو اپنے کل ٹیکس کا 15%، 15 ستمبر تک 45%، 15 دسمبر تک 75%، اور 15 مارچ تک مکمل 100% تک پہنچ جانا چاہیے۔ ہر تاریخ ایک مجموعی ہدف ہے، علیحدہ اضافی ادائیگی نہیں۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>ایڈوانس ٹیکس سال بھر میں چار مراحل میں ادا کیا جاتا ہے۔ 15 جون تک آپ کو اپنے کل ٹیکس کا 15%، 15 ستمبر تک 45%، 15 دسمبر تک 75%، اور 15 مارچ تک مکمل 100% تک پہنچ جانا چاہیے۔ ہر تاریخ ایک مجموعی ہدف ہے، علیحدہ اضافی ادائیگی نہیں۔</figcaption></figure>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>فیصد مجموعی ہیں، چار مساوی سلائس نہیں۔ 15 ستمبر تک ہدف مجموعی طور پر 45% ہے، جس کا مطلب ہے کہ ستمبر کی قسط 45% مائنس ہے جو آپ نے پہلے ہی جون میں ادا کر دیے ہیں، جو کہ آپ کے کل ٹیکس کا 30% ہے۔</p>\n</div></div>\n<h2 id=\"a-worked-example-with-real-rupees\">اصلی روپوں کے ساتھ کام کی مثال</h2>\n<p>اعداد اسے الفاظ سے کہیں زیادہ واضح کرتے ہیں۔ میرا کو حکومت کے باب سے آگے بڑھائیں، جس کا ٹیکس سال کے لیے سیس سے پہلے 1,20,000 روپے تھا۔ اس کو صاف رکھنے کے لیے، ہم یہ کہتے ہیں کہ اس کا سال کا کل ٹیکس 1,20,000 روپے ہے اور اس میں سے کوئی بھی منبع پر نہیں کاٹا گیا، اس لیے پوری رقم اس کو پیشگی ادا کرنی ہے۔</p>\n<p>اس کے 1,20,000 روپے پر چار مجموعی اہداف کا اطلاق کریں۔</p>\n<table>\n<thead>\n<tr>\n<th>کی طرف سے ادا کریں</th>\n<th>مجموعی ہدف</th>\n<th>مجموعی رقم</th>\n<th>اس تاریخ کی قسط</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>15 جون 2025</td>\n<td>15%</td>\n<td>18,000 روپے</td>\n<td>18,000 روپے</td>\n</tr>\n<tr>\n<td>15 ستمبر 2025</td>\n<td>45%</td>\n<td>54,000 روپے</td>\n<td>36,000 روپے</td>\n</tr>\n<tr>\n<td>15 دسمبر 2025</td>\n<td>75%</td>\n<td>90,000 روپے</td>\n<td>36,000 روپے</td>\n</tr>\n<tr>\n<td>15 مارچ 2026</td>\n<td>100%</td>\n<td>1,20,000 روپے</td>\n<td>30,000 روپے</td>\n</tr>\n</tbody></table>\n<p>اس کے ذریعے چلنا۔ 15 جون تک وہ 1,20,000 کا 15% ادا کرتی ہے، جو کہ 18,000 روپے ہے۔ 15 ستمبر تک اس کا مجموعی ہدف 45% ہے، یعنی 54,000 روپے، اس لیے وہ 54,000 مائنس 18,000، جو کہ 36,000 روپے بنتی ہے۔ 15 دسمبر تک ہدف 75% ہے، یعنی 90,000 روپے، تو وہ 90,000 مائنس 54,000 کا اضافہ کرتی ہے، جو کہ مزید 36,000 روپے ہے۔ 15 مارچ تک اسے مکمل 1,20,000 روپے تک پہنچنا ہوگا، اس لیے وہ آخری 1,20,000 مائنس 90,000 ادا کرتی ہے، جو کہ 30,000 روپے ہے۔ ان تاریخوں پر ادائیگی کریں اور اس پر تاخیر پر کوئی سود نہیں ہے۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>میرا کا سال کے لیے کل ٹیکس 1,20,000 روپے ہے، کوئی بھی منبع پر نہیں کاٹا گیا۔ اس کی ایڈوانس ٹیکس کی قسطیں 15 جون تک 18,000 روپے، 15 ستمبر تک 36,000 روپے، 15 دسمبر تک 36,000 روپے، اور 15 مارچ تک 30,000 روپے ہیں، جو کہ 1,20,000 روپے تک پہنچ جاتی ہیں۔ ہر تاریخ کو وقت پر ادائیگی کرنے سے وہ دیر سے ادائیگی پر دلچسپی سے بالکل پاک رہتی ہے۔</p>\n</div></div>\n<p>تاجروں کے لیے ایماندارانہ مشکل یہ ہے کہ منافع غیر متوقع ہے۔ آپ جون میں نہیں جان سکتے کہ دسمبر کیا لے کر آئے گا۔ عملی جواب یہ ہے کہ آپ اپنے بروکر کے منافع اور نقصان کی رپورٹ کا استعمال کرتے ہوئے ہر سہ ماہی میں بہترین اندازہ لگا سکتے ہیں، اب تک کی آمدنی پر ایڈوانس ٹیکس ادا کریں، اور اگلی تاریخ میں ایڈجسٹ کریں۔ ایک معقول تخمینہ، ہر سہ ماہی میں نظر ثانی شدہ، تاریخوں کو مکمل طور پر نظر انداز کرنے سے کہیں بہتر ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>آپ کو کامل پیشن گوئی کی ضرورت نہیں ہے۔ ہر مقررہ تاریخ سے پہلے اپنے بروکر کے منافع اور نقصان کے اعداد و شمار کو کھینچیں، آپ نے اب تک جو کمایا ہے اس پر ٹیکس کا تخمینہ لگائیں، اور اسے ادا کریں۔ اگلی تاریخ پر اوپر یا نیچے ایڈجسٹ کریں۔ مناسب تخمینہ وقت پر ادا کرنا کچھ بھی نہیں ادا کرتا ہے اور بعد میں سود ادا کرتا ہے۔</p>\n</div></div>\n<h2 id=\"on-time-filing-protects-your-losses\">بروقت فائلنگ آپ کے نقصانات کی حفاظت کرتی ہے۔</h2>\n<p>ایڈوانس ٹیکس سال کے دوران واجب الادا رقم کو ہینڈل کرتا ہے۔ ایک دوسری آخری تاریخ، آپ کی واپسی فائل کرنے کی تاریخ، کسی قیمتی چیز کی حفاظت کرتی ہے، نقصانات کو آگے بڑھانے کے آپ کے حق کو۔</p>\n<p>پہلے کے ابواب سے یاد کریں کہ مستقبل اور اختیارات کا نقصان، ایک بار رپورٹ ہونے کے بعد، مستقبل کی کاروباری آمدنی کے مقابلہ میں آٹھ تشخیصی سالوں تک آگے بڑھایا جا سکتا ہے۔ ایک سخت شرط لگائی گئی ہے۔ اگر آپ اصل مقررہ تاریخ تک اپنا ریٹرن فائل کرتے ہیں تو آپ صرف اس کیری فارورڈ کو درست رکھتے ہیں۔ زیادہ تر غیر آڈٹ افراد کے لیے یہ مقررہ تاریخ مالی سال کے بعد 31 جولائی کو آتی ہے، اس لیے 31 جولائی 2026 تشخیصی سال 2026-27 کے لیے، اگرچہ تاریخوں میں توسیع کی جا سکتی ہے، لہذا ہر سال تازہ ترین تصدیق کریں۔</p>\n<p>یہاں تک کہ ایک دن تاخیر سے فائل کریں اور آپ پھر بھی نقصان کی اطلاع دے سکتے ہیں، لیکن آپ اسے آگے لے جانے کا حق کھو دیتے ہیں۔ نقصان تب ضائع ہو جاتا ہے۔ ایک سخت تجارتی سال کے بعد، وہ کیری فارورڈ اکثر چاندی کا واحد استر ہوتا ہے، اور تاریخ کو غائب کرکے اسے پھینک دینا شرم کی بات ہوگی۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>دیر سے واپسی آپ کو نقصانات کو آگے لے جانے سے روکتی ہے۔ آپ نقصان کی اطلاع دے سکتے ہیں، لیکن آپ اسے مستقبل کے منافع کے خلاف سیٹ آف کرنے کا حق کھو دیتے ہیں۔ کھوئے ہوئے سال کے بعد، مقررہ تاریخ تک فائل کرنا وہ فائدہ محفوظ رکھتا ہے جو نقصان آپ کو دے سکتا ہے۔</p>\n</div></div>\n<p>چنانچہ ایک تاجر کے سال میں دو گھڑیاں گزرتی ہیں۔ ایک ایڈوانس ٹیکس ہے، جو 15 جون، 15 ستمبر، 15 دسمبر اور 15 مارچ تک چار اقساط میں ادا کیا جاتا ہے، جو آپ کے سود کو روکتا ہے۔ دوسرا ریٹرن فائل کرنے کی آخری تاریخ ہے، جو آپ کے نقصان کی حفاظت کرتی ہے۔ دونوں کو مدنظر رکھیں اور ٹیکس کا مکینیکل پہلو دباؤ کے بجائے معمول بن جاتا ہے۔ ایڈوانس ٹیکس کی چار تاریخوں اور فائل کرنے کی تاریخ کے لیے کیلنڈر کی یاددہانی سیٹ کریں، اور آپ نے زیادہ تر جرمانے کو ہٹا دیا ہے جو تاجروں کو چوکس کر دیتے ہیں۔</p>\n<p>مختصراً، دو آخری تاریخیں تاجر کے ٹیکس سال کی وضاحت کرتی ہیں۔ ایڈوانس ٹیکس کی چار تاریخیں آپ کو سود سے بچاتی ہیں، اور ریٹرن فائل کرنے کی تاریخ آپ کے نقصان کی حفاظت کرتی ہے۔ آپ کے کیلنڈر میں بیٹھنے کے بعد دونوں سے ملنا آسان ہے، اور جب وہ نہیں ہیں تو یاد کرنا مہنگا ہے۔ ان کے ساتھ فکسڈ اپائنٹمنٹ کے طور پر سلوک کریں، جس طرح سے آپ قرض کی قسط ادا کریں گے، اور ٹیکس کے جرمانے کا پہلو پریشانی کا باعث بنتا ہے۔</p>\n<p>یہ باب صرف تعلیمی مقاصد کے لیے ہے اور ٹیکس کا مشورہ نہیں ہے۔ مقررہ تاریخیں اور حدیں سال بہ سال تبدیل ہو سکتی ہیں، لہٰذا فائل کرنے سے پہلے براہ کرم کسی قابل چارٹرڈ اکاؤنٹنٹ سے موجودہ تاریخوں اور اپنی پوزیشن کی تصدیق کریں۔</p>\n","toc":[{"level":2,"text":"جب آپ پر ایڈوانس ٹیکس لاگو ہوتا ہے۔","id":"when-advance-tax-applies-to-you"},{"level":2,"text":"چار تاریخیں اور ہر ایک کے حساب سے کتنی","id":"the-four-dates-and-how-much-by-each"},{"level":2,"text":"اصلی روپوں کے ساتھ کام کی مثال","id":"a-worked-example-with-real-rupees"},{"level":2,"text":"بروقت فائلنگ آپ کے نقصانات کی حفاظت کرتی ہے۔","id":"on-time-filing-protects-your-losses"}],"imgCount":1,"hasContent":true},"5":{"html":"<p>پریا نے تین سال قبل ایک معروف کمپنی کے 200 شیئرز خریدے تھے۔ پچھلے مہینے اس نے انہیں بیچ دیا، اور اس کے بینک اکاؤنٹ میں صاف منافع آیا۔ وہ خوش ہے، اور پھر ایک چھوٹی سی پریشانی اندر گھس جاتی ہے۔ کیا وہ اس منافع پر ٹیکس واجب الادا ہے؟ کتنا؟ اور کیا اس سے کوئی فرق نہیں پڑتا کہ اس نے دنوں کے بجائے سالوں تک حصص رکھے؟ یہ بالکل وہی سوالات ہیں جن کا یہ باب جواب دیتا ہے، اور اچھی خبر یہ ہے کہ حصص اور ایکویٹی میوچل فنڈز پر کیپیٹل گین قوانین کے ایک چھوٹے، واضح سیٹ پر عمل کرتے ہیں۔ ایک بار جب آپ جان لیں کہ لائنیں کہاں گرتی ہیں، تو آپ چند منٹوں میں اپنا ٹیکس خود نکال سکتے ہیں۔</p>\n<p>جب آپ کوئی شیئر یا میوچل فنڈ یونٹ خریدتے ہیں اور بعد میں اسے آپ کی ادائیگی سے زیادہ میں فروخت کرتے ہیں، تو وہ منافع ہوتا ہے۔ <strong>سرمایہ نفع</strong>. اثاثہ کی قیمت میں اضافہ ہوا جب آپ اس کے مالک تھے، اور حکومتی ٹیکس جو آپ کے بیچنے پر بڑھتے ہیں۔ اگر آپ اپنی ادائیگی سے کم قیمت پر فروخت کرتے ہیں، تو آپ کے پاس ایک ہے۔ <strong>سرمائے کا نقصان</strong>جو کہ ٹیکس کا بل نہیں ہے لیکن پھر بھی مفید ہو سکتا ہے، جیسا کہ آپ دیکھیں گے۔ پورا موضوع دو سوالوں پر موڑ دیتا ہے۔ آپ نے کتنی دیر تک اثاثہ رکھا، اور کتنا بڑا فائدہ ہے؟</p>\n<h2 id=\"short-term-or-long-term-the-twelve-month-line\">مختصر مدت یا طویل مدتی: بارہ ماہ کی لائن</h2>\n<p>درج شدہ حصص اور ایکویٹی میوچل فنڈز کے لیے جنہیں آپ تسلیم شدہ ایکسچینج پر خریدتے اور بیچتے ہیں (جہاں سیکیورٹیز ٹرانزیکشن ٹیکس، تجارت پر چھوٹا لیوی ادا کیا گیا ہے)، ایک حقیقت ہر چیز کا فیصلہ کرتی ہے۔ تقسیم کی لکیر بارہ مہینے ہے۔</p>\n<p>اگر آپ کے پاس اثاثہ ہے۔ <strong>بارہ ماہ یا اس سے کم</strong>، آپ کا فائدہ ہے۔ <strong>مختصر مدت</strong>. اگر آپ نے اس کے لئے منعقد کیا <strong>بارہ مہینے سے زیادہ</strong>، آپ کا فائدہ ہے۔ <strong>طویل مدتی</strong>. یہ واحد امتیاز ٹیکس کی شرح کو تبدیل کرتا ہے، اس لیے کچھ اور کرنے سے پہلے خریداری کی تاریخ اور فروخت کی تاریخ کو احتیاط سے چیک کرنا ضروری ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>انعقاد کی مدت</th>\n<th>نفع کی قسم</th>\n<th>سیکشن</th>\n<th>ٹیکس کی شرح</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>12 ماہ یا اس سے کم</td>\n<td>قلیل مدتی (STCG)</td>\n<td>111A</td>\n<td>20%</td>\n</tr>\n<tr>\n<td>12 ماہ سے زیادہ</td>\n<td>طویل مدتی (LTCG)</td>\n<td>112A</td>\n<td>ایک سال میں 1.25 لاکھ روپے سے زیادہ کے منافع پر 12.5%</td>\n</tr>\n</tbody></table>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>لسٹڈ حصص اور ایکویٹی میوچل فنڈز کے لیے، بارہ مہینے لائن ہے۔ بارہ ماہ یا اس سے کم کے لیے ہولڈ کریں اور فائدہ قلیل مدتی ہے، جس پر 20 فیصد ٹیکس ہے۔ بارہ مہینوں سے زیادہ ہولڈ کریں اور یہ طویل مدتی ہے، جس پر 12.5 فیصد ٹیکس لگایا گیا ہے، ہر سال طویل مدتی منافع کے پہلے 1.25 لاکھ روپے مکمل طور پر ٹیکس سے پاک ہیں۔</p>\n</div></div>\n<p>سیکشن نمبروں پر ایک مختصر نوٹ، کیونکہ وہ ان سے زیادہ خوفناک لگتے ہیں۔ <strong>دفعہ 111A</strong> صرف درج ایکویٹی پر قلیل مدتی فوائد کا اصول ہے۔ <strong>دفعہ 112A</strong> درج ایکویٹی پر طویل مدتی فوائد کا اصول ہے۔ آپ کو انہیں حفظ کرنے کی ضرورت نہیں ہے۔ آپ کا ٹیکس سافٹ ویئر اور آپ کا چارٹرڈ اکاؤنٹنٹ انہیں استعمال کرتے ہیں، اور اب آپ جانتے ہیں کہ ان کا کیا مطلب ہے۔</p>\n<h2 id=\"how-much-you-actually-pay\">آپ اصل میں کتنی ادائیگی کرتے ہیں۔</h2>\n<p>قلیل مدتی فوائد دونوں میں سے آسان ہیں۔ اپنا فائدہ اٹھائیں اور بیس فیصد لگائیں، پھر سرچارج شامل کریں (صرف اس صورت میں جب آپ کی کل آمدنی بہت زیادہ ہو) اور اوپر چار فیصد صحت اور تعلیم کا سیس۔</p>\n<p>فرض کریں کہ پریا نے ان 200 شیئرز کو صرف آٹھ ماہ کے بعد بیچ دیا تھا، جس سے 40,000 روپے کا قلیل مدتی فائدہ ہوا۔ 40,000 پر 20 فیصد ٹیکس 8,000 روپے کے برابر ہے اور اس ٹیکس پر چار فیصد سیس۔ مختصر اور آسان، لیکن آپ دیکھ سکتے ہیں کہ شرح نرم نہیں ہے، یہی ایک وجہ ہے کہ مریض سرمایہ کار طویل مدتی راستے کو ترجیح دیتے ہیں۔</p>\n<p>طویل مدتی فوائد ایک تحفہ کے ساتھ آتے ہیں۔ <strong>ایک مالی سال میں طویل مدتی کیپٹل گین کا پہلا 1.25 لاکھ روپے ٹیکس سے پاک ہے۔</strong>. آپ 12.5 فیصد کی شرح صرف اس حد سے اوپر کے طویل مدتی فائدہ پر ادا کرتے ہیں۔ یہ استثنیٰ ہر سال ری سیٹ ہوتا ہے، لہذا ایک سرمایہ کار جو ناپے ہوئے رقوم میں منافع بکتا ہے اسے بار بار استعمال کر سکتا ہے۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>راوی ایکویٹی میوچل فنڈ یونٹس فروخت کرتا ہے جو اس نے دو سال تک رکھا تھا اور 2,00,000 روپے کا طویل مدتی فائدہ بکتا ہے۔ پہلے 1.25 لاکھ روپے ٹیکس سے پاک ہیں۔ قابل ٹیکس حصہ 2,00,000 مائنس 1,25,000 ہے جو کہ 75,000 کے برابر ہے۔ 75,000 پر 12.5 فیصد ٹیکس 9,375 روپے کے علاوہ چار فیصد سیس کے برابر ہے۔ یہ دو لاکھ کے نفع پر ایک نمایاں طور پر ہلکا بل ہے، جو طویل مدت کے لیے رکھنے کا انعام ہے۔</p>\n</div></div>\n<p>اس 1.25 لاکھ روپے کی چھوٹ کے بارے میں ایک نکتہ آپ کے ذہن میں طے کرنے کے قابل ہے۔ یہ فی شخص، فی مالیاتی سال، آپ کے تمام ایکویٹی شیئرز اور ایکویٹی میوچل فنڈز کو ملا کر ہے۔ یہ فی اسٹاک نہیں ہے اور فی تجارت نہیں ہے۔ لہذا اگر آپ کے پاس کئی جیتنے والے ہولڈنگز ہیں، تو پورے سال کو مدنظر رکھتے ہوئے اپنی فروخت کی منصوبہ بندی کریں، کیونکہ واحد سالانہ الاؤنس ہر چیز میں بانٹ دیا جاتا ہے۔</p>\n<p>یہ دوستانہ علاج نہیں ملتا ہے پر ایک فوری لفظ. ڈیبٹ میوچل فنڈز پر آپ کے سلیب ریٹ پر ٹیکس لگایا جاتا ہے، ان ایکویٹی ریٹ پر نہیں۔ دیگر درج سیکیورٹیز جہاں کوئی STT ادا نہیں کیا گیا وہ 12.5 فیصد طویل مدتی اصول کی پیروی کرتی ہیں لیکن ایکویٹی قلیل مدتی رعایت کے بغیر۔ یہ باب عام کیس کے بارے میں ہے، جس میں حصص اور ایکویٹی میوچل فنڈز کی فہرست ہے جو ایکسچینج پر خریدے اور بیچے گئے ہیں۔</p>\n<h2 id=\"grandfathering-protecting-gains-you-made-long-ago\">دادا سازی: ان فوائد کی حفاظت کرنا جو آپ نے بہت پہلے حاصل کی ہیں۔</h2>\n<p>یہاں ایک سوال ہے جس نے بہت سے سرمایہ کاروں کو پریشان کیا۔ ایکویٹی پر 12.5 فیصد طویل مدتی ٹیکس نسبتاً حالیہ ہے۔ کسی ایسے شخص کے بارے میں کیا ہوگا جس نے بہت پہلے شیئرز خریدے تھے، جب ایسا کوئی ٹیکس نہیں تھا، اور انہیں بہت زیادہ بڑھتے ہوئے دیکھا؟ کیا حکومت کو اس پرانی ترقی پر اچانک ٹیکس لگا دینا چاہیے؟ قانون جو جواب دیتا ہے وہ منصفانہ ہے، اور اسے کہا جاتا ہے۔ <strong>دادا</strong>.</p>\n<p>گرانڈ فادرنگ کا اطلاق حصص اور ایکویٹی یونٹس پر ہوتا ہے۔ <strong>31 جنوری 2018 سے پہلے خریدا گیا۔</strong>. خیال یہ ہے کہ اس تاریخ تک حاصل ہونے والے فوائد کو محفوظ کیا جاتا ہے، اور صرف اس پر ٹیکس لگنے کے بعد ترقی ہوتی ہے۔ جب آپ اپنے منافع کا حساب لگاتے ہیں تو قانون آپ کو زیادہ لاگت کا اعداد و شمار استعمال کرنے کی اجازت دے کر ایسا کرتا ہے، اس لیے پرانی تعریف کم ہی جال میں پھنس جاتی ہے۔</p>\n<p>اصول فضول لگتا ہے، لیکن یہ صرف دو قدموں کا موازنہ ہے۔ اس تاریخ سے پہلے خریدی گئی ہولڈنگ کے حصول کی قیمت معلوم کرنے کے لیے:</p>\n<ol>\n<li>لے لو <strong>کم</strong> (31 جنوری 2018 کو منصفانہ مارکیٹ ویلیو) اور (آپ کی اصل فروخت کی قیمت)۔</li>\n<li>لے لو <strong>اعلی</strong> (پہلے مرحلے سے اعداد و شمار) اور (آپ کی اصل قیمت خرید)۔</li>\n</ol>\n<p>جو بھی مرحلہ دو سے نکلتا ہے وہ قیمت ہے جو آپ استعمال کرتے ہیں۔ آئیے اس کے ذریعے کلاسیکی مثال چلاتے ہیں۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>آپ نے بہت پہلے 15000 روپے میں شیئرز خریدے تھے۔ 31 جنوری 2018 کو ان کی منصفانہ مارکیٹ ویلیو 18,000 روپے تھی۔ آپ نے انہیں 20,000 روپے میں فروخت کیا۔\nپہلا مرحلہ: منصفانہ مارکیٹ ویلیو (18,000) سے کم اور فروخت کی قیمت (20,000) 18,000 ہے۔\nدوسرا مرحلہ: اس 18,000 سے زیادہ اور آپ کی اصل قیمت (15,000) 18,000 ہے۔\nتو جو قیمت لی گئی ہے وہ 18,000 روپے ہے، آپ کے اصل 15,000 روپے نہیں۔ آپ کا طویل مدتی فائدہ 20,000 مائنس 18,000 ہے جو کہ 2,000 روپے کے برابر ہے۔ دادا کے بغیر، فائدہ 20,000 منفی 15,000، 5,000 کے برابر ہوتا۔ اس اصول نے آپ کے پرانے منافع کے 3,000 روپے کو ٹیکس سے بچا لیا ہے۔</p>\n</div></div>\n\n<figure class=\"lesson-shot\">\n<img src=\"/taxation/images/diagram-capital-gains.png\" alt=\"بارہ ماہ کی لائن منافع کو قلیل مدتی اور طویل مدتی میں تقسیم کرتی ہے، ہر ایک کی اپنی شرح کے ساتھ، جبکہ دادا سازی 2018 سے پہلے کی ہولڈنگز کی لاگت کو اٹھا لیتی ہے تاکہ پرانی ترقی کو تحفظ حاصل ہو۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>بارہ ماہ کی لائن منافع کو قلیل مدتی اور طویل مدتی میں تقسیم کرتی ہے، ہر ایک کی اپنی شرح کے ساتھ، جبکہ دادا سازی 2018 سے پہلے کی ہولڈنگز کی لاگت کو اٹھا لیتی ہے تاکہ پرانی ترقی کو تحفظ حاصل ہو۔</figcaption></figure>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>31 جنوری 2018 سے پہلے خریدی گئی کسی بھی ہولڈنگ کے لیے، اس تاریخ کو منصفانہ مارکیٹ ویلیو دیکھیں (عام طور پر 31 جنوری 2018 کو سب سے زیادہ قیمت درج کی گئی ہے)۔ یہ قانونی طور پر آپ کی لاگت کو بڑھا سکتا ہے اور آپ کے قابل ٹیکس منافع کو کم کر سکتا ہے۔ آپ کا بروکر ٹیکس اسٹیٹمنٹ اکثر پہلے سے ہی گرانڈ فادرنگ کا اطلاق کرتا ہے، لیکن یہ سمجھنے کے قابل ہے تاکہ آپ اعداد و شمار کو چیک کر سکیں۔</p>\n</div></div>\n<h2 id=\"when-the-sale-is-a-loss\">جب فروخت میں نقصان ہوتا ہے۔</h2>\n<p>ہر فروخت منافع نہیں ہے، اور قواعد نقصانات کا احتیاط سے علاج کرتے ہیں۔ سرمائے کے نقصان کو صرف کیپیٹل گین کے خلاف ختم کیا جا سکتا ہے، آپ کی تنخواہ یا کاروباری آمدنی کے خلاف نہیں۔ اس کے اندر، اے <strong>طویل مدتی سرمائے کے نقصان کو صرف ایک طویل مدتی سرمائے کے نفع کے مقابلے میں بند کیا جاسکتا ہے۔</strong>. قلیل مدتی نقصان قدرے زیادہ لچکدار ہوتا ہے، کیونکہ اسے قلیل مدتی یا طویل مدتی فائدے کے مقابلے میں بند کیا جا سکتا ہے۔</p>\n<p>اگر آپ اس سال کے نقصان کو استعمال نہیں کر سکتے ہیں، تو آپ اسے نہیں کھوتے۔ سرمائے کا نقصان ہو سکتا ہے۔ <strong>آٹھ تشخیصی سالوں کے لیے آگے بڑھا</strong> اور مستقبل کے کیپیٹل گین کے خلاف استعمال کیا جاتا ہے، بشرطیکہ آپ نے وقت پر اپنا ریٹرن فائل کیا ہو۔ اس لیے نقصان کا سال بھی مناسب طریقے سے رپورٹ کرنے کے قابل ہے، کیونکہ نقصان مستقبل کے منافع کے مقابلے میں ایک ذخیرہ شدہ کریڈٹ بن جاتا ہے۔</p>\n<h2 id=\"a-full-year-start-to-finish\">ایک پورا سال، ختم کرنا شروع کریں۔</h2>\n<p>آئیے دھاگوں کو ایک مختصر کیس اسٹڈی کے ساتھ جوڑتے ہیں۔</p>\n<p>انجلی کا ایک فعال سال تھا۔ جون میں اس نے ایک اسٹاک فروخت کیا جو اس نے پانچ ماہ کے لیے رکھا تھا اور 30,000 روپے کا قلیل مدتی فائدہ بک کیا۔ دسمبر میں اس نے تین سال سے رکھے ہوئے ایکویٹی میوچل فنڈ یونٹس فروخت کیے اور 1,60,000 روپے کا طویل مدتی فائدہ بک کیا۔ اس نے 2018 سے پہلے خریدی گئی ایک پرانی فیملی ہولڈنگ بھی فروخت کی، جہاں دادا کی وجہ سے 2,000 روپے کا طویل مدتی فائدہ ہوا۔</p>\n<p>اس کے 30,000 روپے کے قلیل مدتی نفع پر 20 فیصد ٹیکس ہے، جو کہ 6,000 روپے بنتا ہے۔ اس کے طویل مدتی فوائد میں 1,60,000 پلس 2,000 کا اضافہ ہوتا ہے، جو کہ 1,62,000 کے برابر ہے۔ پہلا 1.25 لاکھ روپے ٹیکس سے پاک ہے، لہذا قابل ٹیکس طویل مدتی حصہ 1,62,000 مائنس 1,25,000 ہے، جو 37,000 کے برابر ہے۔ اس پر 12.5 فیصد ٹیکس 4,625 روپے ہے۔ سیس سے پہلے اس کا کل کیپٹل گین ٹیکس 6,000 جمع 4,625 ہے، جو 10,625 روپے کے برابر ہے، اس کے علاوہ اوپر چار فیصد سیس۔</p>\n<p>غور کریں کہ سال بھر کے نظارے نے اسے کیا خریدا۔ پچھلے بارہ مہینوں میں اپنے زیادہ تر فاتحوں کو اپنے پاس رکھ کر اور 1.25 لاکھ روپے کی چھوٹ پر انحصار کرتے ہوئے، انجلی نے جو بھاری بل ہو سکتا تھا اسے معمولی میں بدل دیا۔ یہ اس باب کا عملی دل ہے۔ ٹیکس ڈرنے کی چیز نہیں ہے، لیکن یہ بارہ ماہ کی لائن اور سالانہ چھوٹ کے ارد گرد انعامی منصوبہ بندی کرتا ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>تاریخ خرید اور فروخت کی تاریخ ہمیشہ کیلنڈر کی واضح تاریخیں نہیں ہوتیں۔ ایک ماہانہ پلان کے ذریعے خریدے گئے میوچل فنڈز کے لیے، ہر قسط کی اپنی خریداری کی تاریخ اور اس کی اپنی ہولڈنگ کی مدت ہوتی ہے۔ جب شک ہو تو، ڈیٹڈ کیپٹل گینز اسٹیٹمنٹ پر بھروسہ کریں اور چارٹرڈ اکاؤنٹنٹ سے تصدیق کریں کہ کون سی اکائیاں قلیل مدتی ہیں اور کون سی طویل مدتی ہیں۔</p>\n</div></div>\n<p>یہ صرف ایک تعلیمی گائیڈ ہے ٹیکس کا مشورہ نہیں۔ ہر بجٹ کے ساتھ قیمتیں اور قواعد بدلتے رہتے ہیں، اس لیے فائل کرنے سے پہلے کسی قابل چارٹرڈ اکاؤنٹنٹ سے موجودہ پوزیشن کی تصدیق کریں۔</p>\n","toc":[{"level":2,"text":"مختصر مدت یا طویل مدتی: بارہ ماہ کی لائن","id":"short-term-or-long-term-the-twelve-month-line"},{"level":2,"text":"آپ اصل میں کتنی ادائیگی کرتے ہیں۔","id":"how-much-you-actually-pay"},{"level":2,"text":"دادا سازی: ان فوائد کی حفاظت کرنا جو آپ نے بہت پہلے حاصل کی ہیں۔","id":"grandfathering-protecting-gains-you-made-long-ago"},{"level":2,"text":"جب فروخت میں نقصان ہوتا ہے۔","id":"when-the-sale-is-a-loss"},{"level":2,"text":"ایک پورا سال، ختم کرنا شروع کریں۔","id":"a-full-year-start-to-finish"}],"imgCount":1,"hasContent":true},"6":{"html":"<p>آپ کا بروکر تجارت کے بعد جو کنٹریکٹ نوٹ بھیجتا ہے اسے قریب سے دیکھیں اور آپ کو کچھ نظر آئے گا۔ حصص کے لیے آپ نے جو قیمت ادا کی وہ کہانی کا صرف ایک حصہ ہے۔ اس کے نیچے مٹھی بھر چھوٹے چارجز ہیں، اور ان میں سے ایک کا نام ہے جو تقریباً ہر ابتدائی کو الجھا دیتا ہے۔ اسے سیکیورٹیز ٹرانزیکشن ٹیکس، یا STT کہا جاتا ہے۔ یہ ایک ہی تجارت پر چھوٹا ہے، پھر بھی یہ خاموشی سے شکل دیتا ہے کہ فعال ٹریڈنگ کی واقعی کتنی لاگت آتی ہے، اور ایک سنجیدہ تاجر کے لیے اس کا ٹیکس کا ایک مفید پہلو بھی ہے۔ یہ باب وضاحت کرتا ہے کہ STT کیا ہے، آپ کو موجودہ شرحیں دکھاتا ہے، اور آپ کو چند حقیقی تجارتوں پر سادہ رقوم کی طرف لے جاتا ہے۔</p>\n<p>STT ایک ٹیکس ہے جو حکومت درج شدہ سیکیورٹیز میں تجارت کی قیمت پر وصول کرتی ہے۔ آپ اسے الگ سے ادا نہیں کرتے۔ یہ آپ کے بروکر کے ذریعے ایکسچینج کے ذریعہ خود بخود اس وقت جمع ہوجاتا ہے جب آپ تجارت کرتے ہیں، لہذا یہ پہلے سے کٹوائے گئے کنٹریکٹ نوٹ پر ظاہر ہوتا ہے۔ کیونکہ یہ قانون کے ذریعے طے شدہ ہے اور سب کے لیے یکساں ہے، اس لیے آپ اس سے گفت و شنید یا اس سے گریز نہیں کر سکتے۔ صرف ایک چیز جو آپ کے STT بل کو تبدیل کرتی ہے وہ ہے کہ آپ کیا تجارت کرتے ہیں اور کتنا۔</p>\n<h2 id=\"what-stt-is-and-why-it-exists\">STT کیا ہے اور یہ کیوں موجود ہے۔</h2>\n<p>حکومت نےSTTکو مارکیٹ کی سرگرمیوں پر ٹیکس لگانے کے صاف، مشکل سے چکنے والے طریقے کے طور پر متعارف کرایا ہے۔ ہر اہل تجارت ایک ڈیجیٹل نقش چھوڑتا ہے، اور STT اس قدم کے نشان پر سوار ہوتا ہے۔ یہ اس وجہ سے اہم ہے جو خود چارج سے باہر ہے۔ چونکہ STT آپ کے PAN کے خلاف رپورٹ کیا گیا ہے، ٹیکس کا محکمہ یہ دیکھ سکتا ہے کہ آپ نے ایک سال میں کتنی تجارت کی، یہاں تک کہ آپ کچھ بھی فائل کرنے سے پہلے۔ ہم کورس میں کہیں اور اس خیال پر واپس آتے ہیں، لیکن اسے ذہن میں رکھیں۔ STT چارج اور ٹریکر دونوں ہے۔</p>\n<p>بطور تاجر یا سرمایہ کار آپ کے لیے، دو عملی چیزیں پیروی کرتی ہیں۔ سب سے پہلے، آپ کو نرخوں کا علم ہونا چاہیے تاکہ آپ کے کنٹریکٹ نوٹ پر موجود نمبر آپ کو حیران نہ کریں۔ دوسرا، اگر آپ ایک کاروبار کے طور پر تجارت کرتے ہیں تو، STT ایک قیمت ہے جسے آپ کو کٹوتی کرنے کی اجازت ہے، جو اس کے ڈنک کو نرم کرتا ہے۔</p>\n<h2 id=\"the-stt-rate-table\">STT ریٹ ٹیبل</h2>\n<p>بجٹ میں نرخوں پر نظرثانی کی گئی تھی اور ذیل کے اعداد و شمار 1 اپریل 2026 سے لاگو ہوں گے۔ نوٹ کریں کہ زیادہ تر مصنوعات کے لیے STT پر پڑتا ہے۔ <strong>بیچنے والا</strong>، اور یہ کہ ڈیلیوری تجارت خرید اور فروخت دونوں طرف سے وصول کی جاتی ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>لین دین</th>\n<th>STT شرح</th>\n<th>کی طرف سے ادا کیا</th>\n<th>چارج ہو گیا۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>ایکویٹی ڈیلیوری خریدیں یا بیچیں۔</td>\n<td>0.1% ہر طرف</td>\n<td>خریدار اور بیچنے والا</td>\n<td>تجارتی قدر</td>\n</tr>\n<tr>\n<td>ایکویٹی انٹرا ڈے فروخت کریں۔</td>\n<td>0.025%</td>\n<td>بیچنے والا</td>\n<td>قیمت فروخت کریں۔</td>\n</tr>\n<tr>\n<td>ایکویٹی میوچل فنڈ یونٹس فروخت کریں۔</td>\n<td>0.001%</td>\n<td>بیچنے والا</td>\n<td>قیمت فروخت کریں۔</td>\n</tr>\n<tr>\n<td>مستقبل فروخت کریں۔</td>\n<td>0.05%</td>\n<td>بیچنے والا</td>\n<td>تجارتی قیمت</td>\n</tr>\n<tr>\n<td>اختیارات فروخت کریں۔</td>\n<td>0.15%</td>\n<td>بیچنے والا</td>\n<td>آپشن پریمیم</td>\n</tr>\n<tr>\n<td>اختیارات استعمال کیے گئے۔</td>\n<td>0.15%</td>\n<td>خریدار</td>\n<td>داخلی (تصفیہ) قدر</td>\n</tr>\n</tbody></table>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>زیادہ تر تجارتوں کے لیے، STT بیچنے والے کے ذریعے ادا کیا جاتا ہے۔ بڑی رعایت ایکویٹی ڈیلیوری ہے، جہاں خریدار اور بیچنے والا دونوں 0.1 فیصد ادا کرتے ہیں۔ اختیارات پریمیم پر وصول کیے جاتے ہیں، معاہدے کی بڑی تصوراتی قیمت پر نہیں، جو روپے کے اعداد و شمار کو چھوٹا رکھتا ہے۔</p>\n</div></div>\n<h2 id=\"the-budget-hike-on-futures-and-options\">مستقبل اور اختیارات پر بجٹ میں اضافہ</h2>\n<p>بجٹ نے مشتقات پر STT بڑھایا، اور استدلال کھلے عام بیان کیا گیا۔ بہت فعال تاجروں کی ایک لہر میں مستقبل اور اختیارات تیار ہو چکے تھے، اور حکومت ضرورت سے زیادہ قیاس آرائیوں کو روکنا چاہتی تھی۔ ہر تجارت کی لاگت کو بڑھانا اس کے لیے ایک لیور ہے۔</p>\n<p>نئے اخذ کردہ نرخ یہ ہیں۔ <strong>فیوچرز کی فروخت پر 0.05 فیصد</strong> اور <strong>اختیارات کی فروخت پر 0.15 فیصد</strong>، جہاں آپشن فگر پریمیم پر چارج کیا جاتا ہے۔ یہ راؤنڈنگ کی غلطیوں کی طرح نظر آسکتے ہیں، لیکن ایک دن میں درجنوں تجارت کرنے والے کے لیے وہ حقیقی ماہانہ لاگت میں اضافہ کرتے ہیں۔ ایک اعلی STT تیز رفتار تجارت کو زیادہ مہنگا بنا دیتا ہے، جو کہ قطعی طور پر مطلوبہ اثر ہے۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>STT اختیارات پر پریمیم پر چارج کیا جاتا ہے، مکمل معاہدے کی قیمت پر نہیں۔ اسی لیے ایسے آپشن کو بیچنا جو لاکھوں روپے کے اسٹاک کو کنٹرول کرتا ہے، STT میں صرف چند روپے لاگت آسکتے ہیں۔ جس بنیاد پر یہ لاگو ہوتا ہے ہمیشہ شرح کو پڑھیں۔</p>\n</div></div>\n<h2 id=\"working-out-stt-on-real-trades\">حقیقی تجارت پر STT کام کرنا</h2>\n<p>حساب ہر بار ایک جیسا ہوتا ہے۔ وہ قدر لیں جس پر شرح لاگو ہوتی ہے، پھر شرح سے ضرب کریں۔ یہاں تین کام کی رقمیں ہیں جو سب سے عام حالات کا احاطہ کرتی ہیں۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>ایک فیوچر لاٹ بیچنا۔ آپ 5,00,000 روپے کا فیوچر کنٹریکٹ بیچتے ہیں۔ فیوچرز کی فروخت پر STT 0.05 فیصد ہے۔ تو STT 5,00,000 کے 0.05 فیصد کے برابر ہے، جو کہ 250 روپے کے برابر ہے۔</p>\n<p>ترسیل کے لیے شیئرز خریدنا۔ آپ 100 روپے میں 500 شیئرز خریدتے ہیں، جس کی تجارتی قیمت 50,000 روپے ہے۔ ڈیلیوری STT ہر طرف 0.1 فیصد ہے۔ لہذا خرید پر STT 50,000 کے 0.1 فیصد کے برابر ہے، جو کہ 50 روپے کے برابر ہے۔</p>\n<p>ایک آپشن بیچنا۔ پریمیم 50 روپے ہے اور لاٹ سائز 65 ہے، لہذا پریمیم ویلیو 50 گنا 65 ہے، جو کہ 3,250 روپے کے برابر ہے۔ STT ایک آپشن کی فروخت پر 0.15 فیصد ہے۔ تو STT 3,250 کے 0.15 فیصد کے برابر ہے، جو کہ 4.88 روپے کے برابر ہے۔</p>\n</div></div>\n<p>ان تینوں کو ایک دوسرے کے ساتھ رکھیں اور پیٹرن واضح ہے۔ پانچ لاکھ کنٹریکٹ پر فیوچر سیل کی لاگت 250 روپے ہے۔ ڈیلیوری پرچیز کی لاگت 50 روپے ہے۔ پانچ روپے سے کم اسٹاک لاگت کے ہزاروں روپے کو کنٹرول کرنے والے کنٹریکٹ پر آپشن سیل، کیونکہ آپشنز صرف پریمیم پر وصول کیے جاتے ہیں۔ ان میں سے کوئی بھی اپنے طور پر بڑا نہیں ہے۔ جب آپ اکثر تجارت کرتے ہیں تو لاگت مجموعی طور پر ظاہر ہوتی ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>تجارت</th>\n<th>بنیادی قدر</th>\n<th>شرح</th>\n<th>STT</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1 فیوچر لاٹ فروخت کریں۔</td>\n<td>5,00,000 روپے</td>\n<td>0.05%</td>\n<td>250 روپے</td>\n</tr>\n<tr>\n<td>500 حصص کی ترسیل خریدیں۔</td>\n<td>50,000 روپے</td>\n<td>0.1%</td>\n<td>50 روپے</td>\n</tr>\n<tr>\n<td>1 آپشن لاٹ فروخت کریں۔</td>\n<td>3,250 روپے پریمیم</td>\n<td>0.15%</td>\n<td>4.88 روپے</td>\n</tr>\n</tbody></table>\n<h2 id=\"how-the-small-charge-adds-up-over-a-year\">ایک سال کے دوران چھوٹے چارج میں کیسے اضافہ ہوتا ہے۔</h2>\n<p>چند سو روپے کا ایک STT معمولی محسوس ہوتا ہے، اور ایک تجارت پر ایسا ہوتا ہے۔ جب آپ پورے سال کی سرگرمی گنتے ہیں تو تصویر بدل جاتی ہے۔ فرض کریں کہ ایک فیوچر ٹریڈر ماہانہ بیس کنٹریکٹس فروخت کرتا ہے، ہر ایک کی مالیت تقریباً 5,00,000 روپے ہے۔ STT فی فروخت کے 250 روپے پر، یہ بیس گنا 250 ہے، جو کہ ایک ماہ کے 5,000 روپے کے برابر ہے، اور بارہ مہینوں میں یہ سال کے لیے 60,000 روپے کے برابر ہے، صرف فیوچر کی فروخت پر۔ آپشن سیلز اور ڈیلیوری کی خریداری شامل کریں، اور ایک فعال تاجر کے لیے سالانہ STT ایک ایسے نمبر پر چڑھ جاتا ہے جو حقیقی طور پر اہمیت رکھتا ہے۔</p>\n<p>یہ بالکل وہی اثر ہے جو بجٹ میں اضافے کے لیے ڈیزائن کیا گیا تھا۔ ہر مشتق تجارت کو تھوڑا زیادہ مہنگا بنا کر، اعلیٰ STT تاجروں کو زیادہ احتیاط اور کم ترش کے ساتھ تجارت کرنے پر مجبور کرتا ہے۔ طویل مدتی سرمایہ کار کے لیے جو ڈیلیوری خریدتا ہے اور ہولڈ رکھتا ہے، STT بمشکل رجسٹر ہوتا ہے، کیونکہ یہ صرف اندر اور باہر جاتے وقت چارج کیا جاتا ہے اور ہولڈنگ درمیان میں کام کرتی ہے۔ تیز رفتار تاجر کے لیے، STT کاروبار کرنے کی ایک مستحکم لاگت ہے جو سراسر حجم سے زیادہ انتخاب کو انعام دیتا ہے۔</p>\n<p>اس سے یہ جاننے میں مدد ملتی ہے کہ پلمبنگ کیسے کام کرتی ہے۔ STT ایکسچینج کے ذریعہ ماخذ پر جمع کیا جاتا ہے اور حکومت کو بھیج دیا جاتا ہے، لہذا آپ کے لیے فائل کرنے کے لیے کوئی علیحدہ STT واپسی نہیں ہے۔ یہ سسٹم میں سب سے زیادہ لیک پروف ٹیکسوں میں سے ایک ہے، جس کا ایک حصہ یہ ہے کہ محکمہ سال بھر کے تاجر کے ٹرن اوور کا اندازہ لگانے کے لیے STT ٹریل کا استعمال کیوں کر سکتا ہے۔</p>\n<p>سمجھدار جواب STT سے ڈرنا نہیں ہے بلکہ اسے اس بات میں جوڑنا ہے کہ آپ تجارت کے بارے میں کیسے سوچتے ہیں۔ ایک ایسی حکمت عملی جس کو ایک چھوٹا کنارہ بنانے کے لیے سینکڑوں تجارتوں کی ضرورت ہوتی ہے اسے پہلے اپنی STT لاگت کو صاف کرنا پڑتا ہے۔ ایک پرسکون، زیادہ منتخب نقطہ نظر STT کو بہت کم ادائیگی کرتا ہے۔ چارج خاموشی سے صبر کی حمایت کرتا ہے، اور یہ بات یاد رکھنے کے قابل ہے جب آپ تجارتی طرز کا موازنہ کرتے ہیں۔</p>\n<h2 id=\"stt-is-a-deductible-business-expense\">STT ایک قابل کٹوتی کاروباری خرچ ہے۔</h2>\n<p>یہ وہ حصہ ہے جو خالص قیمت سے زیادہ قابل برداشت چیز میں بدلتا ہے۔ اگر آپ ایک کاروبار کے طور پر تجارت کرتے ہیں، جو سب سے زیادہ فعال مستقبل، اختیارات اور انٹرا ڈے ٹریڈرز کرتے ہیں، تو پھر <strong>STT ادا کیا جانے والا ایک کاروباری خرچ ہے جسے آپ کاٹ سکتے ہیں۔</strong> آپ کی تجارتی آمدنی سے۔ یہ اس منافع کو کم کرتا ہے جس پر آپ پر ٹیکس لگایا جاتا ہے۔</p>\n<p>یہ پرانے دنوں سے ایک معنی خیز فرق ہے، اور یہ ایک وجہ ہے کہ آپ کی سرگرمی کو صحیح طریقے سے درجہ بندی کرنا اہمیت رکھتا ہے۔ ایک سرمایہ کار جو کیپیٹل گینز کی اطلاع دیتا ہے چارجز کو کاروباری آمدنی کی اطلاع دینے والے تاجر سے مختلف طریقے سے لیتا ہے۔ تاجر کے لیے، ہر روپیہ STT، بروکریج اور دیگر اجازت شدہ چارجز ٹیکس پر کام کرنے سے پہلے سب سے اوپر آتا ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>ہاتھ سے STT شامل نہ کریں۔ آپ کا بروکر سالانہ ٹیکس منافع اور نقصان کا بیان فراہم کرتا ہے جو کہ آپ کے لیے کل STT اور دیگر چارجز ہیں۔ وہ بیان اپنے چارٹرڈ اکاؤنٹنٹ کو دیں تاکہ کٹوتی کی پوری رقم پکڑی جائے۔ اس سے محروم ہونے کا مطلب ہے کہ آپ کی ضرورت سے زیادہ ٹیکس ادا کرنا۔</p>\n</div></div>\n<p>آئیے اسے ایک مختصر کیس اسٹڈی میں دیکھتے ہیں۔</p>\n<p>وکرم فل ٹائم فیوچر اور آپشنز کی تجارت کرتا ہے۔ مالی سال کے دوران اس کی تجارت نے چارجز سے پہلے 6,00,000 روپے کا خالص منافع حاصل کیا۔ اس کے بروکر کے بیان میں 45,000 روپے کے 4STTکو دیگر قابل اجازت چارجز کے ساتھ دکھایا گیا ہے۔ چونکہ وہ اسے کاروباری آمدنی کے طور پر رپورٹ کرتا ہے، STT اور دیگر چارجز قابل کٹوتی ہیں۔ اس کا قابل ٹیکس تجارتی منافع اکیلے STT سے 6,00,000 سے 5,55,000 تک گر جاتا ہے، اور پھر باقی چارجز کو منہا کرنے کے بعد مزید۔ STT وہ کم از کم ٹیکس کے وقت اس کے لیے کام کرنے والی آمدنی کو کم کرکے ادا کرنے سے گریز نہیں کرسکتا تھا جس پر اس پر ٹیکس لگایا جاتا ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/taxation/images/diagram-stt-rates.png\" alt=\"سیکیورٹیز ٹرانزیکشن ٹیکس زیادہ تر بیچنے والے پر پڑتا ہے، مکمل معاہدے کے بجائے اختیارات کے لیے پریمیم پر چارج کیا جاتا ہے، اور تاجر کے لیے کٹوتی کے اخراجات کے طور پر شمار ہوتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>سیکیورٹیز ٹرانزیکشن ٹیکس زیادہ تر بیچنے والے پر پڑتا ہے، مکمل معاہدے کے بجائے اختیارات کے لیے پریمیم پر چارج کیا جاتا ہے، اور تاجر کے لیے کٹوتی کے اخراجات کے طور پر شمار ہوتا ہے۔</figcaption></figure>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>STT معاہدے کے نوٹ پر صرف ایک لائن ہے۔ بروکریج، ایکسچینج چارجز، ان چارجز پر گڈز اینڈ سروسز ٹیکس، اسٹامپ ڈیوٹی اور SEBI فیس بھی لاگو ہوتی ہے، اور ریگولیٹر چارجز طبقہ کے لحاظ سے مختلف ہو سکتے ہیں۔ بروکر ٹیکس اسٹیٹمنٹ کو سال کے لیے سچائی کا واحد ذریعہ سمجھیں، اور کسی پیشہ ور کو اس میں مصالحت کرنے دیں۔</p>\n</div></div>\n<p>ٹیک وے پرسکون اور عملی ہے۔ STT ایک چھوٹا، مقررہ ٹیکس ہے جس سے آپ بچ نہیں سکتے، زیادہ تر بیچنے والے پر چارج کیا جاتا ہے، حال ہی میں بھاری قیاس آرائیوں کو کم کرنے کے لیے مشتقات پر اٹھایا گیا ہے۔ نرخوں کو جانیں، ان کے خلاف اپنے معاہدے کے نوٹ چیک کریں، اور اگر آپ کاروبار کے طور پر تجارت کرتے ہیں، تو یقینی بنائیں کہ آپ کے STT کا دعویٰ کٹوتی کے قابل خرچ کے طور پر کیا گیا ہے۔</p>\n<p>یہ باب صرف تعلیمی ہے ٹیکس کا مشورہ نہیں۔ STT کی شرحوں میں وقتاً فوقتاً بجٹ میں نظر ثانی کی جاتی ہے، اس لیے فائل کرنے سے پہلے موجودہ اعداد و شمار اور اپنے علاج کی تصدیق کسی قابل چارٹرڈ اکاؤنٹنٹ سے کریں۔</p>\n","toc":[{"level":2,"text":"STT کیا ہے اور یہ کیوں موجود ہے۔","id":"what-stt-is-and-why-it-exists"},{"level":2,"text":"STT ریٹ ٹیبل","id":"the-stt-rate-table"},{"level":2,"text":"مستقبل اور اختیارات پر بجٹ میں اضافہ","id":"the-budget-hike-on-futures-and-options"},{"level":2,"text":"حقیقی تجارت پر STT کام کرنا","id":"working-out-stt-on-real-trades"},{"level":2,"text":"ایک سال کے دوران چھوٹے چارج میں کیسے اضافہ ہوتا ہے۔","id":"how-the-small-charge-adds-up-over-a-year"},{"level":2,"text":"STT ایک قابل کٹوتی کاروباری خرچ ہے۔","id":"stt-is-a-deductible-business-expense"}],"imgCount":1,"hasContent":true},"7":{"html":"<p>روہن صبح ساڑھے نو بجے تیزی سے چلنے والے اسٹاک کے 100 حصص خریدتا ہے، دوپہر کے کھانے کے دوران اسے چڑھتے دیکھتا ہے، اور دوپہر تین بجے سے پہلے لاٹ فروخت کرتا ہے۔ اس کے اکاؤنٹ میں کبھی کوئی شیئرز نہیں آتے۔ پوری پوزیشن اسی دن کھلی اور بند ہوئی۔ اس نے صاف ستھرے 4,000 روپے بنائے، اور وہ فرض کرتا ہے کہ ٹیکس اسی طرح کام کرے گا جس طرح اس کے چچا طویل مدتی حصص پر کیپیٹل گین ادا کرتے ہیں۔ وہ سرپرائز میں ہے۔ روہن نے جو کچھ کیا اس کا اپنا خاص ٹیکس لیبل ہے، اور اس لیبل کو سمجھنا صحیح فائل کرنے اور غلط فائل کرنے میں فرق ہے۔</p>\n<p>جب آپ ڈیلیوری لیے بغیر ایک ہی دن ایک ہی اسٹاک خریدتے اور بیچتے ہیں، یعنی <strong>انٹرا ڈے ٹریڈنگ</strong>. ٹیکس کا قانون اسے بالکل بھی سرمایہ کاری کے طور پر نہیں مانتا۔ یہ اسے ایک خاص قسم کے کاروبار کے طور پر دیکھتا ہے، اس کی اپنی شرح، اس کے اپنے نقصان کے اصول، اور اس کے اپنے لے جانے کی مدت کے ساتھ۔ یہ باب تینوں کو سادہ الفاظ میں کھولتا ہے۔</p>\n<h2 id=\"why-intraday-equity-is-called-speculative\">انٹرا ڈے ایکویٹی کو قیاس آرائی کیوں کہا جاتا ہے۔</h2>\n<p>پہلے کورس میں ہم نے ٹریڈنگ کو تین بالٹیوں میں ترتیب دیا تھا۔ ڈیلیوری شیئرز اور میوچل فنڈز کیپٹل گین ہیں۔ مستقبل اور اختیارات غیر قیاس آرائی پر مبنی کاروباری آمدنی ہیں۔ انٹرا ڈے ایکویٹی اپنے طور پر تیسری بالٹی میں بیٹھتی ہے، اور قانون اسے تھوڑا پرانا نام دیتا ہے۔ یہ ہے <strong>قیاس آرائی پر مبنی کاروباری آمدنی</strong>.</p>\n<p>ایک بار جب آپ اسے بلند آواز سے کہتے ہیں تو منطق سیدھی ہوتی ہے۔ ایک قیاس آرائی پر مبنی لین دین، قانون کے الفاظ میں، حصص کی حقیقی ترسیل کے بغیر طے شدہ لین دین ہے۔ جب آپ اسی دن انٹرا ڈے پوزیشن کو مربع کرتے ہیں، تو کوئی حصص ہاتھ نہیں بدلتا۔ آپ اپنی خرید قیمت اور اپنی فروخت کی قیمت کے درمیان فرق کو جیب میں ڈالتے ہیں یا ادا کرتے ہیں۔ کیونکہ کچھ بھی نہیں پہنچایا جاتا ہے، منافع قیاس آرائی ہے. یہ اب بھی کاروباری آمدنی ہے، لیکن ایک خاص قیاس آرائی کی قسم کی ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>انٹرا ڈے ایکویٹی ٹریڈنگ، جہاں آپ ایک ہی دن بغیر ڈیلیوری کے ایک ہی اسکرپ خریدتے اور بیچتے ہیں، قیاس آرائی پر مبنی کاروباری آمدنی ہے۔ یہ کیپیٹل گین نہیں ہے اور یہ فیوچر اور آپشنز جیسی بالٹی نہیں ہے۔ یہ واحد درجہ بندی باب میں باقی سب کچھ چلاتی ہے۔</p>\n</div></div>\n<table>\n<thead>\n<tr>\n<th>لین دین کی قسم</th>\n<th>کے طور پر درجہ بندی</th>\n<th>نقصان کا مقابلہ کیا جا سکتا ہے۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>ڈیلیوری ایکویٹی اور میوچل فنڈز</td>\n<td>سرمائے کا فائدہ</td>\n<td>صرف کیپٹل گین</td>\n</tr>\n<tr>\n<td>مستقبل اور اختیارات</td>\n<td>غیر قیاس آرائی پر مبنی کاروباری آمدنی</td>\n<td>تنخواہ کے علاوہ زیادہ تر آمدنی کے سربراہ</td>\n</tr>\n<tr>\n<td>انٹرا ڈے ایکویٹی</td>\n<td>قیاس آرائی پر مبنی کاروباری آمدنی</td>\n<td>صرف قیاس آرائی پر مبنی آمدنی</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/taxation/images/diagram-income-buckets.png\" alt=\"انٹرا ڈے ایکویٹی اپنی ہی بالٹی میں قیاس آرائی پر مبنی کاروباری آمدنی کے طور پر بیٹھتی ہے، ڈیلیوری کیپٹل گین سے الگ اور غیر قیاس آرائی پر مبنی مستقبل اور اختیارات سے الگ۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>انٹرا ڈے ایکویٹی اپنی ہی بالٹی میں قیاس آرائی پر مبنی کاروباری آمدنی کے طور پر بیٹھتی ہے، ڈیلیوری کیپٹل گین سے الگ اور غیر قیاس آرائی پر مبنی مستقبل اور اختیارات سے الگ۔</figcaption></figure>\n<h2 id=\"taxed-at-your-slab-rate\">آپ کے سلیب ریٹ پر ٹیکس لگایا گیا ہے۔</h2>\n<p>یہاں ان مبتدیوں کے لیے خوشخبری کا ایک ٹکڑا ہے جنہیں خوفناک خصوصی شرح کا خدشہ تھا۔ قیاس آرائی پر مبنی کاروبار کی آمدنی ہے۔ <strong>آپ کے عام سلیب کی شرح پر ٹیکس لگایا گیا ہے۔</strong>. یہ صرف سال کے لیے آپ کی کل آمدنی میں اضافہ کرتا ہے اور آپ جس سلیب میں آتے ہیں اس کے مطابق ہر چیز کے ساتھ ٹیکس لگایا جاتا ہے۔</p>\n<p>لہذا اگر روہن کی واحد آمدنی معمولی تنخواہ تھی جس نے اسے کم سلیب میں رکھا، تو اس کے انٹرا ڈے منافع پر اس کم سلیب کی شرح پر ٹیکس لگایا جائے گا۔ اگر وہ پہلے سے ہی سب سے اوپر سلیب میں زیادہ کمانے والا تھا، تو اسی منافع پر سب سے اوپر کی شرح پر ٹیکس لگایا جائے گا۔ انٹرا ڈے کے لیے کوئی الگ فلیٹ ریٹ نہیں ہے، کرپٹو کے برعکس۔ یہ آپ کے سلیب پر سوار ہے۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>مالی سال کے دوران، روہن کی انٹرا ڈے ٹریڈز 1,20,000 روپے کے خالص منافع میں اضافہ کرتی ہے۔ وہ ایک تنخواہ بھی کماتا ہے جو اس کی معمولی آمدنی کو 10 فیصد سلیب میں رکھتا ہے۔ اس کا انٹرا ڈے منافع اس کی کل آمدنی میں شامل کیا جاتا ہے اور اس سلیب پر ٹیکس لگایا جاتا ہے۔ 1,20,000 پر 10 فیصد ٹیکس 12,000 روپے کے علاوہ چار فیصد سیس ہے۔ اگر اس کے بجائے اس کی دوسری آمدنی اس کے مارجن کو 20 فیصد سلیب میں ڈال دیتی، تو وہی 1,20,000 روپے 24,000 حاصل کرے گا۔ شرح شخص کی پیروی کرتی ہے، تجارت کی نہیں۔</p>\n</div></div>\n<p>چونکہ یہ کاروباری آمدنی ہے، اس لیے معمول کی کاروباری منطق لاگو ہوتی ہے۔ بروکریج، انٹرا ڈے سیلز پر سیکیورٹیز ٹرانزیکشن ٹیکس، اور دیگر قابل اجازت تجارتی چارجز کو قابل ٹیکس منافع تک پہنچنے سے پہلے کاٹا جا سکتا ہے۔ آپ اسے کاروباری آمدنی کے طور پر رپورٹ کرتے ہیں، نہ کہ کیپیٹل گین کے طور پر، اور زیادہ تر فعال تاجر اس کے لیے ITR-3 استعمال کرتے ہیں۔</p>\n<h2 id=\"what-counts-as-intraday-and-what-does-not\">کیا انٹرا ڈے کے طور پر شمار ہوتا ہے، اور کیا نہیں</h2>\n<p>یہ واضح طور پر حد کو کھینچنے کے قابل ہے، کیونکہ قیاس آرائی کا لیبل صرف ایک چیز پر منحصر ہے۔ کیا پوزیشن ڈیلیوری کے بغیر طے کی گئی تھی؟ اگر آپ اسٹاک خریدتے ہیں اور اسے اسی دن بیچ دیتے ہیں تاکہ آپ کے اکاؤنٹ میں کبھی بھی کوئی شیئر نہ آئے، تو یہ انٹرا ڈے ہے اور یہ قیاس آرائی پر مبنی ہے۔ جس لمحے حصص درحقیقت آپ کے اکاؤنٹ میں ڈیلیور کیے جاتے ہیں، تجارت قیاس آرائی پر مبنی بالٹی کو چھوڑ دیتی ہے اور یا تو ڈیلیوری سرمایہ کاری یا ڈیلیوری پر مبنی تجارتی تجارت بن جاتی ہے، ان کے اپنے اصولوں کے ساتھ۔</p>\n<p>چند عام حالات مبتدیوں کو الجھا دیتے ہیں، اس لیے ان کا نام لینے میں مدد ملتی ہے۔ اگر آپ آج خریدتے ہیں اور حصص آپ کے اکاؤنٹ میں جمع ہوجاتے ہیں، تو کل فروخت کریں، یہ ڈیلیوری ٹریڈ ہے، انٹرا ڈے نہیں، کیونکہ ڈیلیوری ہوئی تھی۔ فیوچرز اور آپشنز، یہاں تک کہ جب اسی دن اسکوائر ہو جائیں، کبھی بھی قیاس آرائی پر مبنی ایکوئٹی نہیں ہوتے، کیونکہ قانون خاص طور پر ان کو غیر قیاس آرائی پر مبنی کاروبار کے طور پر دیکھتا ہے۔ اور آپ کے اکاؤنٹ میں پہلے سے موجود شیئرز کی فروخت ایک ڈیلیوری سیل ہے، نہ کہ انٹرا ڈے شارٹ، کیونکہ حقیقی شیئرز منتقل ہو گئے ہیں۔ قیاس آرائی پر مبنی علاج اسی دن کی ایکویٹی پوزیشنوں کے لیے مخصوص ہے جو بغیر کسی ڈیلیوری کے کھلتے اور بند ہوتے ہیں۔</p>\n<p>باؤنڈری پر ہنگامہ کیوں؟ کیونکہ بالٹی نقصان کے اصولوں کا فیصلہ کرتی ہے، اور وہ اصول ناقابل معافی ہیں، جیسا کہ ہم دیکھنے والے ہیں۔ ڈیلیوری ٹریڈ کو قیاس آرائی یا ریورس کے طور پر غلط لیبل کریں، اور آپ کے سیٹ آف اور کیری فارورڈ کو غلط طریقے سے شمار کیا جا سکتا ہے، یہ اس قسم کی غلطی ہے جو بعد میں آنے والے نوٹس کو ظاہر کر سکتی ہے۔</p>\n<h2 id=\"the-loss-rule-that-catches-people-out\">نقصان کا اصول جو لوگوں کو باہر نکالتا ہے۔</h2>\n<p>اب ہم اس اصول پر پہنچ گئے ہیں جو تقریباً سب کو حیران کر دیتا ہے، اور اس کے لیے سست ہونا قابل ہے۔ اے <strong>قیاس آرائی پر مبنی نقصان صرف قیاس آرائی پر مبنی آمدنی کے خلاف ہی بند کیا جا سکتا ہے۔</strong>. اور کچھ نہیں۔</p>\n<p>اس کا موازنہ دوسری بالٹیوں سے کریں۔ ایک غیر قیاس آرائی پر مبنی مستقبل اور اختیارات کے نقصان کو تنخواہ کے علاوہ زیادہ تر قسم کی آمدنی کے خلاف طے کیا جا سکتا ہے۔ کیپیٹل گین کے مقابلے میں کیپیٹل نقصان کو ختم کیا جاسکتا ہے۔ لیکن ایک قیاس آرائی پر مبنی انٹرا ڈے نقصان کو مضبوطی سے باندھ دیا گیا ہے۔ یہ آپ کی تنخواہ کو کم نہیں کر سکتا، یہ آپ کے ڈیلیوری کیپٹل گین کو کم نہیں کر سکتا، اور یہ آپ کے فیوچر اور آپشن کے منافع کو بھی کم نہیں کر سکتا۔ یہ صرف دوسری قیاس آرائی پر مبنی آمدنی کے مقابلے میں طے کیا جا سکتا ہے، جس کا عملی طور پر مطلب ہے دوسرے انٹرا ڈے ایکویٹی منافع۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>انٹرا ڈے نقصان کو آپ کی ڈیلیوری کی سرمایہ کاری کے فوائد، آپ کی تنخواہ، یا آپ کے مستقبل اور اختیارات کے منافع کے خلاف ختم نہیں کیا جا سکتا۔ یہ صرف دیگر قیاس آرائی پر مبنی آمدنی کے مقابلے میں مقرر کیا جا سکتا ہے. انٹرا ڈے نقصانات کو کسی بھی آمدنی کے مقابلے میں آزادانہ طور پر ایڈجسٹ کرنا ایک عام اور مہنگی غلطی ہے۔</p>\n</div></div>\n<p>اگر آپ اس سال قیاس آرائی کے نقصان کو استعمال نہیں کرسکتے ہیں، تو یہ ختم نہیں ہوتا ہے۔ یہ ہو سکتا ہے۔ <strong>چار سال تک آگے بڑھا</strong> اور مستقبل کے ان سالوں میں قیاس آرائی پر مبنی آمدنی کے خلاف نکلیں۔ نوٹ کریں کہ چار عام کاروباری نقصانات اور سرمائے کے نقصانات کے لیے اجازت دیے گئے آٹھ سال سے کم ہیں۔ قیاس آرائی کے نقصانات کو مختصر ترین پٹا ملتا ہے۔ ہر نقصان کیری فارورڈ کی طرح، آپ اسے لے جانے کا حق صرف اسی صورت میں رکھتے ہیں جب آپ اپنی واپسی وقت پر فائل کریں۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>لے جانے کے ادوار بالٹی کے لحاظ سے مختلف ہوتے ہیں۔ قیاس آرائی کے نقصانات چار سال آگے بڑھتے ہیں۔ غیر قیاس آرائی پر مبنی کاروباری نقصانات اور سرمائے کے نقصانات آٹھ سال آگے بڑھتے ہیں۔ ہر صورت میں، بروقت فائلنگ داخلہ کی قیمت ہے۔ فائل لیٹ ہو گئی اور نقصان کو آگے لے جانے کا حق ضائع ہو گیا۔</p>\n</div></div>\n<h2 id=\"a-case-study-that-ties-it-together\">ایک کیس اسٹڈی جو اسے آپس میں جوڑتی ہے۔</h2>\n<p>سنیتا سے ملیں، جن کا ایک ملا جلا سال رہا اور یہ ظاہر کرتی ہے کہ یہ اصول کیوں اہمیت رکھتے ہیں۔</p>\n<p>سنیتا نے سال کے دوران بازار میں تین مختلف چیزیں کیں۔ اس کی انٹرا ڈے ایکویٹی ٹریڈنگ ایک میں ختم ہوئی۔ <strong>50,000 روپے کا نقصان</strong>. اس کی ترسیل کی سرمایہ کاری نے ایک پیدا کیا۔ <strong>80,000 روپے کا قلیل مدتی سرمایہ فائدہ</strong>. اور اس نے تنخواہ بھی حاصل کی۔</p>\n<p>اس کی جبلت، روہن کی طرح، 50,000 روپے کے انٹرا ڈے نقصان کو اس کے 80,000 روپے کی ڈیلیوری گین سے گھٹانا اور صرف 30,000 روپے پر ٹیکس ادا کرنا تھا۔ اس کی اجازت نہیں ہے۔ انٹرا ڈے نقصان قیاس آرائی پر مبنی ہے، اور قیاس آرائی پر مبنی نقصان اس کے سرمائے کے منافع یا اس کی تنخواہ کو نہیں چھو سکتا۔ لہٰذا اس کے 80,000 روپے کے قلیل مدتی کیپٹل گین پر اس کی اپنی شرح سے مکمل ٹیکس لگایا جاتا ہے، اور اس کی تنخواہ پر اس کے سلیب پر ٹیکس لگایا جاتا ہے، جو تجارتی نقصان سے اچھوتا ہے۔</p>\n<p>پھر 50,000 روپے کے انٹرا ڈے نقصان کا کیا ہوتا ہے؟ اسے ضائع نہیں کیا جاتا بلکہ پارک کیا جاتا ہے۔ سنیتا اپنی واپسی وقت پر فائل کرتی ہے، قیاس آرائی پر مبنی نقصان کا اعلان کرتی ہے، اور اسے چار سال تک آگے لے جاتی ہے۔ اگر اگلے سال اس کی انٹرا ڈے ٹریڈنگ 30,000 روپے کے منافع میں بدل جاتی ہے، تو وہ اس کے مقابلے میں لے جانے والے نقصان کو مقرر کر سکتی ہے اور اس 30,000 روپے پر کوئی ٹیکس ادا نہیں کر سکتی، جس سے 20,000 روپے کا نقصان باقی ہے۔ نقصان صرف مستقبل کی قیاس آرائی پر مبنی آمدنی کے خلاف مفید ہے، لیکن وقت پر اس کی اطلاع دینا اس اختیار کو زندہ رکھتا ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>اگر آپ سرمایہ کاری کے ساتھ ساتھ انٹرا ڈے میں بھی ڈبکیاں لگاتے ہیں تو پہلے دن سے دونوں ریکارڈ صاف طور پر الگ رکھیں۔ ہر ایک ہی دن کے اسکوائر آف کو بطور قیاس آرائی اور ہر ڈیلیوری تجارت کو بطور سرمایہ کاری ٹیگ کریں۔ آپ کے بروکر کے ٹیکس منافع اور نقصان کا بیان عام طور پر آپ کے لیے ان کو تقسیم کرتا ہے، جو فائلنگ اور مستقبل کے کسی بھی سیٹ آف کو بہت آسان بنا دیتا ہے۔</p>\n</div></div>\n<p>پیچھے ہٹیں اور انٹرا ڈے ٹیکس کی شکل آپ کے ذہن میں رکھنا آسان ہے۔ اسی دن کی ایکویٹی تجارت قیاس آرائی پر مبنی کاروباری آمدنی ہے۔ منافع پر آپ کے عام سلیب ریٹ پر ٹیکس لگایا جاتا ہے اور آپ اس کے خلاف ٹریڈنگ چارجز کاٹ سکتے ہیں۔ نقصان کو کم کیا جاتا ہے، صرف دوسری قیاس آرائی پر مبنی آمدنی کے خلاف استعمال کے قابل، اور یہ صرف چار سال آگے بڑھتا ہے، اور صرف اس صورت میں جب آپ وقت پر فائل کریں۔ یہ جاننا آپ کو غلط شرح ادا کرنے اور انکم کے خلاف انٹرا ڈے نقصان کو غلط طریقے سے حاصل کرنے کے جڑواں جال سے بچاتا ہے جسے یہ کبھی نہیں چھو سکتا۔</p>\n<p>یہ باب صرف تعلیمی ہے ٹیکس کا مشورہ نہیں۔ قوانین اور نرخ ہر بجٹ کے ساتھ تبدیل ہو سکتے ہیں، اس لیے فائل کرنے سے پہلے کسی اہل چارٹرڈ اکاؤنٹنٹ سے اپنی صورتحال کی تصدیق کریں۔</p>\n","toc":[{"level":2,"text":"انٹرا ڈے ایکویٹی کو قیاس آرائی کیوں کہا جاتا ہے۔","id":"why-intraday-equity-is-called-speculative"},{"level":2,"text":"آپ کے سلیب ریٹ پر ٹیکس لگایا گیا ہے۔","id":"taxed-at-your-slab-rate"},{"level":2,"text":"کیا انٹرا ڈے کے طور پر شمار ہوتا ہے، اور کیا نہیں","id":"what-counts-as-intraday-and-what-does-not"},{"level":2,"text":"نقصان کا اصول جو لوگوں کو باہر نکالتا ہے۔","id":"the-loss-rule-that-catches-people-out"},{"level":2,"text":"ایک کیس اسٹڈی جو اسے آپس میں جوڑتی ہے۔","id":"a-case-study-that-ties-it-together"}],"imgCount":1,"hasContent":true},"8":{"html":"<p>مسٹر مہتا بوڑھے ہو رہے ہیں اور وہ اپنے حصہ کا پورٹ فولیو اپنے بچوں کو دینا شروع کرنا چاہتے ہیں جب کہ وہ ابھی بھی ان کی رہنمائی کے لیے موجود ہیں۔ اس کے پڑوسی نے اسے اندھیرے میں خبردار کیا ہے کہ حصص تحفے میں دینے سے بڑا ٹیکس ہوتا ہے۔ ایک ساتھی کا اصرار ہے کہ خاندان کو تحفے ہمیشہ ٹیکس سے پاک ہوتے ہیں۔ ایک کزن بہرحال اس کے پاس واپس آنے والی آمدنی کے بارے میں کچھ ذکر کرتا ہے۔ تین رائے، سب آدھا صحیح، اور مسٹر مہتا اس سے زیادہ الجھن میں ہیں کہ انہوں نے کب شروع کیا۔ حصص کا تحفہ دینا اور وراثت دینا ٹیکس کے ان گوشوں میں سے ایک ہے جہاں تھوڑا سا واضح علم بہت ساری پریشانیوں کو بچاتا ہے، لہذا آئیے اسے صحیح طریقے سے پیش کریں۔</p>\n<p>حصص کے تحفے کو انکم ٹیکس کے قانون کے تحت رقم یا جائیداد کے تحفے کی طرح سمجھا جاتا ہے۔ کوئی ٹیکس دیتا ہے یا نہیں، اور کون ادا کرتا ہے، یہ تین چیزوں پر منحصر ہے۔ دینے والا کون ہے، تحفے کی قیمت کتنی ہے، اور بعد میں شیئرز سے جو آمدنی ہوتی ہے اس کا کیا ہوتا ہے۔ ان تینوں کو سیدھا کریں اور پورا موضوع اپنی جگہ پر آجائے۔</p>\n<h2 id=\"gifts-from-relatives-are-fully-tax-free\">رشتہ داروں کے تحائف مکمل طور پر ٹیکس سے پاک ہیں۔</h2>\n<p>سب سے خوشگوار اصول کے ساتھ شروع کریں۔ ایک سے تحفہ ملا <strong>رشتہ دار</strong> ہے <strong>ٹیکس سے مکمل طور پر مستثنیٰ، بغیر کسی بالائی حد کے</strong>. آپ کے والد آپ کو دس روپے یا دس کروڑ روپے کے حصص گفٹ کر سکتے ہیں، اور کسی بھی طرح سے تحفہ وصول کرنے والے پر کوئی ٹیکس نہیں ہے۔</p>\n<p>قانون اس بات کی وضاحت کرتا ہے کہ کون رشتہ دار کے طور پر شمار ہوتا ہے، اور فہرست فراخ ہے۔ اس میں آپ کی شریک حیات، آپ کے والدین، آپ کے بچے، آپ کے بھائی اور بہنیں، آپ کے دادا دادی، اور آپ کی شریک حیات کے متعلقہ رشتہ دار، متعین کردہ فہرست میں شامل ہیں۔ ان لوگوں کے درمیان عام خاندانی منتقلی کے لیے، حصص تحفے میں دینا صاف اور غیر ٹیکس ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>متعین فہرست میں کسی رشتہ دار کی طرف سے حصص کا تحفہ، جیسے کہ والدین، بچے، شریک حیات، بہن بھائی یا دادا دادی، وصول کنندہ کے لیے مکمل طور پر ٹیکس سے پاک ہے، جس کی کوئی اوپری حد نہیں ہے۔ اس فہرست میں خاندانی منتقلی پر تحفہ ٹیکس نہیں لگتا۔</p>\n</div></div>\n<h2 id=\"gifts-from-non-relatives-the-rs-50-000-line\">غیر رشتہ داروں سے تحفہ: 50,000 روپے کی لائن</h2>\n<p>اب اس خاندانی فہرست سے باہر ہر ایک کے لیے اصول، جسے قانون کہتے ہیں۔ <strong>غیر رشتہ دار</strong>. یہاں ایک حد نمودار ہوتی ہے۔ اگر ایک مالی سال میں آپ کو غیر رشتہ داروں سے ملنے والے تحائف کی کل قیمت ہے۔ <strong>50,000 روپے سے زیادہ</strong>, the <strong>پوری رقم قابل ٹیکس بن جاتی ہے</strong> دوسرے ذرائع سے آمدنی کے طور پر آپ کے ہاتھ میں، آپ کے سلیب کی شرح پر ٹیکس۔</p>\n<p>اسے غور سے پڑھیں، کیونکہ پھندا الفاظ میں ہے۔ 50,000 روپے کوئی استثنیٰ نہیں ہے جو ہمیشہ مفت ہوتا ہے۔ ایک بار جب کل ​​رقم 50,000 روپے سے تجاوز کر جاتی ہے، تو پوری رقم پر ٹیکس لگایا جاتا ہے، نہ کہ صرف حد سے اوپر کا حصہ۔ یہ قانون کی دفعہ 56(2)(x) کے تحت ہے۔</p>\n<p>اسے ایک تیز شکل کے ساتھ تصویر بنائیں۔ ایک دوست، جو رشتہ دار نہیں ہے، آپ کو 60,000 روپے کے شیئرز تحفے میں دیتا ہے۔ چونکہ غیر رشتہ داروں کی کل رقم 50,000 روپے سے تجاوز کر گئی ہے، اس لیے پورے 60,000 روپے دوسرے ذرائع سے آپ کی آمدنی کے طور پر قابل ٹیکس ہیں، نہ کہ صرف 10,000 روپے سے اوپر۔ اگر تحفہ 50,000 روپے یا اس سے کم ہوتا، اور اس سال غیر رشتہ داروں کی طرف سے کوئی اور چیز نہ آتی، تو یہ مکمل طور پر ٹیکس سے پاک ہوتا۔ 1,000 روپے کی اضافی قیمت پوری رقم کو قابل ٹیکس کالم میں پلٹ سکتی ہے، یہی وجہ ہے کہ حد حقیقی دیکھ بھال کی مستحق ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>50,000 روپے کا فگر کلف ہے، مفت الاؤنس نہیں۔ اسے غیر رشتہ داروں کے تحائف کے ساتھ عبور کریں اور پہلے روپے سے پوری رقم پر ٹیکس لگایا جاتا ہے۔ حد سال میں تمام غیر متعلقہ تحائف کو بھی شامل کرتی ہے، لہذا کئی چھوٹے تحائف خاموشی سے ایک ساتھ اس کی خلاف ورزی کر سکتے ہیں۔</p>\n</div></div>\n<h2 id=\"the-donor-s-cost-and-holding-period-carry-over\">عطیہ دہندہ کی لاگت اور انعقاد کی مدت پوری ہوتی ہے۔</h2>\n<p>چنانچہ مسٹر مہتا اپنے بیٹے کو حصص تحفے میں دیتے ہیں، اور برسوں بعد بیٹا انہیں بیچ دیتا ہے۔ بیٹے کے سرمائے سے حاصل ہونے والا منافع کیسے ہوتا ہے؟ یہ وہ جگہ ہے جہاں ایک صاف اور بہت منصفانہ اصول لاگو ہوتا ہے۔ جب آپ حصص بطور تحفہ وصول کرتے ہیں، تو آپ <strong>آپ کی قیمت کے طور پر عطیہ دہندگان کی اصل قیمت خریدیں۔</strong>، اور آپ <strong>عطیہ دہندگان کے انعقاد کی مدت بھی وراثت میں حاصل کریں۔</strong>.</p>\n<p>صاف لفظوں میں گویا گھڑی اور قیمت دینے والے کی طرف سے جاری رہتی ہے۔ بیٹے کو تحفہ کے دن قیمت خرید کو مارکیٹ ویلیو پر دوبارہ سیٹ کرنے کی اجازت نہیں ملتی ہے۔ وہ وہی استعمال کرتا ہے جو اس کے والد نے اصل میں ادا کیا تھا، اور وہ ان سالوں کا شمار کرتا ہے جب اس کے والد نے خریدا تھا، نہ کہ اس دن سے جب اسے تحفہ ملا تھا۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>مسٹر مہتا نے 1,00,000 روپے میں شیئرز خریدے اور انہیں تین سال تک اپنے پاس رکھا۔ وہ اپنے بیٹے کو تحفہ دیتا ہے۔ اٹھارہ ماہ بعد بیٹا انہیں 1,80,000 روپے میں فروخت کرتا ہے۔</p>\n<p>بیٹے کی لاگت اس کے والد کی لاگت ہے، جو کہ 1,00,000 روپے ہے۔ اس کا فائدہ 1,80,000 مائنس 1,00,000 ہے جو کہ 80,000 روپے کے برابر ہے۔</p>\n<p>انعقاد کی مدت کے لیے، بیٹا اپنے باپ کے تین سال کو اپنے اٹھارہ مہینوں میں شامل کرتا ہے۔ مشترکہ ہولڈنگ آرام سے بارہ مہینوں سے زیادہ ہے، لہذا فائدہ طویل مدتی ہے، زیادہ مختصر مدت کی شرح کے بجائے نرم طویل مدتی شرح پر ٹیکس لگایا جاتا ہے۔ لاگت اور انعقاد کی مدت دونوں کے کیری اوور نے بیٹے کے حق میں کام کیا۔</p>\n</div></div>\n<p>یہ کیری اوور عام طور پر اچھی خبر ہوتی ہے، کیونکہ ڈونر کے انعقاد کی طویل مدت اکثر وصول کنندہ کی حتمی فروخت کو طویل مدتی بریکٹ میں دھکیل دیتی ہے۔ لیکن اس کا مطلب یہ بھی ہے کہ آپ صرف گفٹ کے ذریعے شیئرز کو روٹ کرکے پرانی کم قیمت سے نہیں بچ سکتے۔ اصل قیمت حصص کی پیروی کرتی ہے جہاں وہ خاندان میں جاتے ہیں۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/taxation/images/diagram-gifting-shares.png\" alt=\"رشتہ داروں کی طرف سے تحفے بغیر کسی حد کے ٹیکس سے پاک ہیں، غیر رشتہ داروں کے تحائف 50,000 روپے سے تجاوز کرنے کے بعد ان پر مکمل ٹیکس عائد کیا جاتا ہے، اور عطیہ دہندگان کی لاگت اور ہولڈنگ کی مدت وصول کنندہ تک پہنچ جاتی ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>رشتہ داروں کی طرف سے تحفے بغیر کسی حد کے ٹیکس سے پاک ہیں، غیر رشتہ داروں کے تحائف 50,000 روپے سے تجاوز کرنے کے بعد ان پر مکمل ٹیکس عائد کیا جاتا ہے، اور عطیہ دہندگان کی لاگت اور ہولڈنگ کی مدت وصول کنندہ تک پہنچ جاتی ہے۔</figcaption></figure>\n<h2 id=\"the-clubbing-trap-a-gift-can-come-back-to-bite-you\">کلبنگ ٹریپ: ایک تحفہ آپ کو کاٹنے کے لئے واپس آ سکتا ہے۔</h2>\n<p>یہاں وہ اصول ہے جو کزن آدھے کو یاد ہے، اور یہ وہی ہے جو لوگوں کو اچھی طرح سے پکڑتا ہے۔ اسے کہا جاتا ہے۔ <strong>کلب</strong>سیکشن 64 کے تحت۔ اگر آپ اپنی آمدنی پیدا کرنے والا اثاثہ تحفہ دیتے ہیں۔ <strong>شریک حیات یا نابالغ بچے کو</strong>، وہ آمدنی جو اثاثہ بعد میں کماتی ہے۔ <strong>آپ کی اپنی آمدنی میں واپس شامل کریں اور آپ کے ہاتھ میں ٹیکس لگائیں۔</strong>.</p>\n<p>حصص کا تحفہ خود اب بھی ٹیکس سے پاک ہے، کیونکہ میاں بیوی اور ایک بچہ رشتہ دار ہیں۔ لیکن ان حصص سے جو منافع اور سرمایہ حاصل ہوتا ہے وہ ٹیکس کے مقاصد کے لیے شریک حیات یا نابالغ بچے کے ساتھ نہیں رہتا۔ انہیں واپس اس شخص کی آمدنی میں شامل کیا جاتا ہے جس نے تحفہ دیا تھا۔ ٹیکس مین کم آمدنی والے خاندان کے ممبر کو آمدنی منتقل کرنے کے واضح راستے کو بند کرتا ہے۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>کلبنگ کا اطلاق آپ کے شریک حیات اور نابالغ بچے کو تحفے پر ہوتا ہے۔ اثاثہ کی منتقلی ٹیکس سے پاک ہے، لیکن اس کے بعد اس سے حاصل ہونے والی آمدنی، جیسے ڈیویڈنڈ اور کیپٹل گین، واپس دینے والے کے ہاتھ میں ٹیکس لگا دیا جاتا ہے۔ کسی بالغ بچے یا بہن بھائی کو تحفہ اس شریک حیات اور نابالغ کلب کے اصول کے تحت نہیں آتا، لہذا وہاں کی آمدنی حقیقی طور پر وصول کنندہ کی ہے۔</p>\n</div></div>\n<h2 id=\"inheritance-is-exempt-and-a-family-put-together\">وراثت سے مستثنیٰ ہے، اور خاندان کو اکٹھا کیا جاتا ہے۔</h2>\n<p>ایک اور تسلی بخش نکتہ۔ ایک کے تحت موصول ہونے والے حصص <strong>وصیت یا وراثت سے مستثنیٰ ہیں۔</strong>. جب اثاثے مالک کی موت پر گزر جاتے ہیں، تو وراثت میں آنے والے شخص پر کوئی تحفہ ٹیکس نہیں ہوتا ہے۔ زندگی بھر کے تحفے کی طرح، وارث اصل قیمت اور ہولڈنگ کی مدت میں قدم رکھتا ہے جب وہ آخرکار فروخت ہوتا ہے۔</p>\n<p>یہی وجہ ہے کہ پرانے ریکارڈ ایک خاندان میں بہت اہمیت رکھتے ہیں۔ اگر مسٹر مہتا کے دادا نے دہائیوں پہلے ایک ہولڈنگ خریدی تھی، اور یہ تحفے کے ذریعے اور پھر وراثت کے ذریعے منتقل ہو گئی، تو پہلی خریداری کی قیمت اور تاریخ اب بھی ان حصص کے ساتھ سفر کرتی ہے جو آخر میں انہیں فروخت کرتا ہے۔ ایک خاندان جو اصل کنٹریکٹ نوٹ کھو دیتا ہے وہ خود کو لاگت کو ثابت کرنے سے قاصر پا سکتا ہے، جس کا مطلب یہ ہو سکتا ہے کہ قانون کے اصل ارادے سے زیادہ ٹیکس قابل فائدہ۔ خریداری کے ریکارڈوں کا ایک سادہ فولڈر رکھنا، اور ہر منتقلی کو نوٹ کرنا، ایک چھوٹی سی عادت ہے جو ہر ایک کو نیچے سے محفوظ رکھتی ہے۔</p>\n<p>اب آئیے پورے خاندان کو ایک تصویر میں رکھیں، کیونکہ اس کے برعکس اصولوں کو قائم رکھتا ہے۔</p>\n<p>مسٹر مہتا ایک ہی سال میں تین ٹرانسفر کرتے ہیں۔ وہ اپنے کو 5,00,000 روپے کے حصص تحفے میں دیتا ہے۔ <strong>بالغ بیٹا</strong>. وہ اپنے کو 3,00,000 روپے کے حصص تحفے میں دیتا ہے۔ <strong>بیوی</strong>. اور ایک خاندانی دوست، ایک غیر رشتہ دار، مسٹر مہتا کو تحفہ دیتا ہے۔ <strong>بیٹی</strong> 70,000 روپے کے شیئرز۔</p>\n<p>بالغ بیٹے کے لیے تحفہ ٹیکس سے پاک ہے، کیونکہ بیٹا رشتہ دار ہے، اور بیٹا بالغ ہونے کی وجہ سے کوئی کلب نہیں ہے۔ مستقبل کا کوئی بھی منافع اور منافع بیٹے سے تعلق رکھتا ہے اور بیٹے کے ہاتھ میں ٹیکس لگایا جاتا ہے۔ بیوی کو تحفہ منتقلی کے طور پر بھی ٹیکس سے پاک ہے، لیکن کلبنگ کاٹتا ہے۔ ڈیویڈنڈ اور کیپیٹل گین کا ہر روپیہ جو ان شیئرز کے بعد حاصل ہوتا ہے مسٹر مہتا کی آمدنی میں واپس شامل کیا جاتا ہے اور ان کی شرح پر ٹیکس لگایا جاتا ہے۔ بیٹی کو غیر رشتہ دار سے ملنے والے 70,000 روپے 50,000 روپے سے تجاوز کر جاتے ہیں، لہذا تمام 70,000 روپے دیگر ذرائع سے حاصل ہونے والی آمدنی کے طور پر بیٹی کے ہاتھ میں قابل ٹیکس ہیں۔ ایک ہی خاندان، ایک ہی سال، ٹیکس کے تین مکمل طور پر مختلف نتائج، یہ سب اس بات سے ہیں کہ کس نے دیا، کتنا دیا، اور آیا کلبنگ لاگو ہوتی ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>شئیر گفٹ کرنے سے پہلے دو باتیں لکھ لیں۔ کیا وصول کنندہ متعین فہرست میں ایک رشتہ دار ہے، اور کلبنگ کا اطلاق ہوسکتا ہے کیونکہ وصول کنندہ آپ کا شریک حیات یا نابالغ بچہ ہے۔ عطیہ دہندہ کے اصل خریداری کے معاہدے کے نوٹ کو محفوظ طریقے سے رکھیں، کیونکہ وصول کنندہ کو اس قیمت اور اس تاریخ کی ضرورت ہوگی تاکہ مستقبل کی فروخت پر حاصل ہونے والے منافع کا حساب لگایا جاسکے۔ ایک چارٹرڈ اکاؤنٹنٹ مشکل معاملات میں رشتہ دار حیثیت اور کلب کی پوزیشن کی تصدیق کر سکتا ہے۔</p>\n</div></div>\n<p>یاد رکھنے کی شکل چھوٹی ہے۔ رشتہ داروں کی طرف سے تحفے بغیر کسی حد کے مفت ہیں۔ غیر رشتہ داروں سے ملنے والے تحائف ایک بار ایک سال میں 50,000 روپے سے تجاوز کر جانے کے بعد ان پر مکمل ٹیکس عائد ہوتا ہے۔ وصول کنندہ کو عطیہ دہندہ کی لاگت اور انعقاد کی مدت وراثت میں ملتی ہے۔ شریک حیات یا نابالغ بچے کو تحفے مستقبل کی آمدنی کو کلب کے ذریعے دینے والے کو واپس لاتے ہیں۔ اور وراثت مستثنیٰ ہے۔ ان پانچ نکات کو پکڑیں ​​​​اور آپ خوف کے بجائے اعتماد کے ساتھ خاندان کی منتقلی کی منصوبہ بندی کر سکتے ہیں۔</p>\n<p>یہ باب صرف تعلیمی ہے ٹیکس کا مشورہ نہیں۔ تعریفیں، حدیں اور کلبنگ کی دفعات تبدیل ہو سکتی ہیں، اس لیے کام کرنے سے پہلے اپنے مخصوص پلان کی تصدیق اہل چارٹرڈ اکاؤنٹنٹ سے کریں۔</p>\n","toc":[{"level":2,"text":"رشتہ داروں کے تحائف مکمل طور پر ٹیکس سے پاک ہیں۔","id":"gifts-from-relatives-are-fully-tax-free"},{"level":2,"text":"غیر رشتہ داروں سے تحفہ: 50,000 روپے کی لائن","id":"gifts-from-non-relatives-the-rs-50-000-line"},{"level":2,"text":"عطیہ دہندہ کی لاگت اور انعقاد کی مدت پوری ہوتی ہے۔","id":"the-donor-s-cost-and-holding-period-carry-over"},{"level":2,"text":"کلبنگ ٹریپ: ایک تحفہ آپ کو کاٹنے کے لئے واپس آ سکتا ہے۔","id":"the-clubbing-trap-a-gift-can-come-back-to-bite-you"},{"level":2,"text":"وراثت سے مستثنیٰ ہے، اور خاندان کو اکٹھا کیا جاتا ہے۔","id":"inheritance-is-exempt-and-a-family-put-together"}],"imgCount":1,"hasContent":true},"9":{"html":"<p>روہن اور میرا سے ملو۔ وہ دو میزوں کے علاوہ بیٹھتے ہیں، ایک ہی اسکرین پر نفٹی کے وہی اختیارات دیکھتے ہیں، اور دونوں نے اس سال فیوچرز اور آپشنز سے 3 لاکھ روپے کے صاف منافع کے ساتھ ختم کیا۔ کاغذ پر وہ جڑواں بچوں کی طرح نظر آتے ہیں۔ پھر بھی جب فائلنگ سیزن آتا ہے، ان کی ٹیکس کی کہانیاں الگ ہو جاتی ہیں، اور صرف ایک چیز جس نے انہیں الگ کیا وہ ایک پرسکون فیصلہ تھا: ان میں سے ہر ایک نے اس F&amp;O منافع کو کس خانے میں ڈالا۔</p>\n<p>روحان جلدی میں تھا۔ اس نے اپنے F&amp;O حاصلات کا علاج اسی طرح کیا جس طرح وہ حصص کی فروخت سے منافع کے ساتھ سلوک کرتا ہے اور رقم کو کیپٹل گین کے طور پر رپورٹ کرتا ہے۔ میرا نے پہلے تھوڑا پڑھا تھا، اس لیے اس نے کاروبار کی آمدنی کے طور پر وہی 3 لاکھ روپے بتائے۔ ان میں سے ایک نے صحیح فائل کی۔ دوسرے نے نوٹس کو مدعو کیا، کٹوتیوں کو پھینک دیا جس کا وہ مکمل حقدار تھا، اور ہو سکتا ہے کہ اسے اپنی پوری واپسی دوبارہ کرنی پڑے۔ یہ باب اس بارے میں ہے کہ کیوں روہن کا انتخاب نئے تاجروں کی سب سے عام غلطی ہے، اور آپ اس سے کیسے بچ سکتے ہیں۔</p>\n<h2 id=\"f-o-is-business-income-not-capital-gains\">F&amp;O کاروباری آمدنی ہے، نہ کہ کیپٹل گین</h2>\n<p>یہاں سادہ الفاظ میں قاعدہ ہے۔ مستقبل اور اختیارات سے منافع ہے <strong>غیر قیاس آرائی پر مبنی کاروباری آمدنی</strong>. ٹیکس قانون کی زبان میں یہ سر کے نیچے بیٹھتا ہے جسے \"کاروبار یا پیشے کے منافع اور فوائد\" کہا جاتا ہے، وہی سر جو ایک دکاندار، کنسلٹنٹ یا چھوٹا صنعت کار استعمال کرتا ہے۔ یہ NOT کیپیٹل گین ہے، حالانکہ آپ نے واضح طور پر کوئی چیز خریدی اور بیچی ہے۔</p>\n<p>یہ بالکل وہی جگہ ہے جہاں ابتدائی افراد پھسل جاتے ہیں۔ شیئرز خریدنا، انہیں ڈیلیوری کے لیے رکھنا، پھر بیچنا، حقیقی طور پر کیپٹل گین ہے۔ لہذا نئے تاجر کی وجہ یہ ہے کہ ایکسچینج پر خریدی اور بیچی گئی کوئی بھی چیز کیپٹل گین بھی ہونی چاہیے۔ یہ استدلال صرف F&amp;O کے لیے غلط ہے۔ ٹیکس کا قانون آپ کے فیوچر اور آپشنز کی سرگرمی کو دیکھتا ہے اور اس کاروبار کو دیکھتا ہے جسے آپ چلا رہے ہیں، چاہے آپ مہینے میں ایک تجارت کریں یا دن میں پچاس تجارت کریں۔</p>\n<p>جملہ \"غیر قیاس آرائی پر مبنی\" سست ہونے کے قابل ہے، کیونکہ یہ حقیقی کام کر رہا ہے۔ ٹیکس قانون تجارت کو تین بالٹیوں میں ترتیب دیتا ہے، اور F&amp;O کا اپنا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>لین دین کی قسم</th>\n<th>کے طور پر درجہ بندی</th>\n<th>نقصان کا مقابلہ کیا جا سکتا ہے۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>F&amp;O (ایکویٹی، کموڈٹی، کرنسی)</td>\n<td>غیر قیاس آرائی پر مبنی کاروباری آمدنی</td>\n<td>تنخواہ کے علاوہ زیادہ تر آمدنی کے سربراہ</td>\n</tr>\n<tr>\n<td>انٹرا ڈے ایکویٹی ٹریڈنگ</td>\n<td>قیاس آرائی پر مبنی کاروباری آمدنی</td>\n<td>صرف قیاس آرائی پر مبنی آمدنی</td>\n</tr>\n<tr>\n<td>ڈیلیوری ایکویٹی اور میوچل فنڈز</td>\n<td>کیپیٹل گینز (STCGیا LTCG)</td>\n<td>صرف کیپٹل گین</td>\n</tr>\n</tbody></table>\n<p>پیٹرن پر توجہ دیں۔ انٹرا ڈے ایکویٹی ٹریڈنگ بھی ایک کاروبار ہے، لیکن قیاس آرائی کی قسم۔ ڈیلیوری شیئرز اور میوچل فنڈز کیپٹل گین ہیں۔ F&amp;O درمیان میں غیر قیاس آرائی پر مبنی کاروباری آمدنی کے طور پر بیٹھتا ہے۔ یہ غیر قیاس آرائی پر مبنی لیبل درحقیقت اچھی خبر ہے، اور بعد کا ایک باب ظاہر کرتا ہے کہ یہ کس طرح آپ کے نقصانات کو انٹرا ڈے ٹریڈر کے مقابلے میں زیادہ دوستانہ سلوک فراہم کرتا ہے۔</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>F&amp;O منافع کو کیپیٹل گین کے طور پر رپورٹ کرنا ٹیکس کی پہلی غلطی ہے۔ فیوچر اور اختیارات غیر قیاس آرائی پر مبنی کاروباری آمدنی ہیں، جس پر \"کاروبار یا پیشے کے منافع اور فوائد\" کے تحت ٹیکس لگایا گیا ہے اور ITR-3 میں رپورٹ کیا گیا ہے۔ وہ STCG نہیں ہیں اور وہ LTCG نہیں ہیں۔</p>\n</div></div>\n\n<figure class=\"lesson-shot\">\n<img src=\"/taxation/images/diagram-fno-business-income.png\" alt=\"ایف اینڈ او منافع کیپٹل گین نہیں ہے۔ یہ غیر قیاس آرائی پر مبنی کاروباری آمدنی ہے، جس پر آپ کے سلیب ریٹ پر ٹیکس لگایا گیا ہے، جس کی رپورٹ ITR-3 میں دی گئی ہے، حقیقی کاروباری اخراجات کی اجازت ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>ایف اینڈ او منافع کیپٹل گین نہیں ہے۔ یہ غیر قیاس آرائی پر مبنی کاروباری آمدنی ہے، جس پر آپ کے سلیب ریٹ پر ٹیکس لگایا گیا ہے، جس کی اطلاع ITR-3 میں دی گئی ہے، حقیقی کاروباری اخراجات کی اجازت ہے۔</figcaption></figure>\n<h2 id=\"why-the-bucket-you-choose-changes-everything\">آپ جس بالٹی کا انتخاب کرتے ہیں وہ سب کچھ کیوں بدلتا ہے۔</h2>\n<p>غلط بالٹی میں F&amp;O ڈالنا بے ضرر لیبلنگ سلپ نہیں ہے۔ بالٹی تین بڑی چیزوں کا فیصلہ کرتی ہے: ٹیکس کی شرح، آیا آپ اخراجات کا دعویٰ کر سکتے ہیں، اور نقصان کے ساتھ آپ کیا کر سکتے ہیں۔</p>\n<p>سب سے پہلے، شرح. F&amp;O منافع آپ پر ٹیکس لگایا جاتا ہے۔ <strong>سلیب کی شرح</strong>، جس کا مطلب ہے کہ یہ آپ کی دوسری آمدنی کے اوپر صرف ڈھیر لگا دیتا ہے اور جس بھی بینڈ میں آتا ہے اس پر ٹیکس لگایا جاتا ہے۔ اس پر خصوصی فلیٹ کیپٹل گین ریٹ پر ٹیکس نہیں لگایا جاتا ہے۔ اس کے برعکس حصص پر قلیل مدتی سرمائے کے منافع پر سیکشن 111A کے تحت فلیٹ 20%، اور سیکشن 112A کے تحت 12.5% ​​پر طویل مدتی منافع ٹیکس لگایا جاتا ہے۔ اگر روہن اپنے F&amp;O منافع کو قلیل مدتی کیپیٹل گین کے طور پر فائل کرتا ہے، تو وہ اسے 20% فلیٹ پر مجبور کرتا ہے اور اس زمرے میں جو اس کا تعلق نہیں ہے، جو کہ غلط ہے اور اکثر اس کے اصلی سلیب سے زیادہ مہنگا ہوتا ہے۔</p>\n<p>دوسرا، اخراجات۔ چونکہ F&amp;O ایک کاروبار ہے، آپ کو ٹیکس لگانے سے پہلے اسے چلانے کے حقیقی اخراجات کو منہا کرنے کی اجازت ہے: آپ کا بروکریج، آپ کے ایکسچینج چارجز، آپ کا انٹرنیٹ بل، آپ کے ریسرچ ٹولز اور بہت کچھ۔ کیپٹل گین تقریباً اس میں سے کسی کی اجازت نہیں دیتا۔ غلط لیبل لگا کر، روہن خاموشی سے ان کٹوتیوں میں سے ہر ایک کو واپس کر دیتا ہے۔ اگلا باب ان اخراجات کے لیے وقف ہے۔</p>\n<p>تیسرا، نقصانات۔ ایک غیر قیاس آرائی پر مبنی F&amp;O نقصان زیادہ تر دیگر آمدنی کے مقابلے میں ختم کیا جا سکتا ہے، اور اگر آپ وقت پر فائل کرتے ہیں تو اسے 8 سال تک آگے بڑھایا جا سکتا ہے۔ سرمائے کا نقصان پھنسا ہوا ہے، کیونکہ اسے صرف سرمائے کے منافع کے مقابلے میں بند کیا جا سکتا ہے۔ اپنے F&amp;O نقصان کو غلط بالٹی میں رکھیں اور آپ اسے اپنی تنخواہ سے پاک دوسری آمدنی کے خلاف استعمال کرنے کا حق کھو دیں گے۔</p>\n<table>\n<thead>\n<tr>\n<th>سوال</th>\n<th>F&amp;O بطور کاروباری آمدنی (درست)</th>\n<th>F&amp;O غلط طریقے سے کیپٹل گین کے طور پر</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>ٹیکس کی شرح</td>\n<td>آپ کی سلیب کی شرح</td>\n<td>20% فلیٹ پر زبردستی (STCG)</td>\n</tr>\n<tr>\n<td>بروکریج، انٹرنیٹ، ٹولز کا دعوی کریں؟</td>\n<td>جی ہاں</td>\n<td>نہیں</td>\n</tr>\n<tr>\n<td>سب سے زیادہ آمدنی کے خلاف نقصان کو مقرر کریں؟</td>\n<td>ہاں (تنخواہ کے علاوہ)</td>\n<td>نہیں، صرف کیپٹل گین</td>\n</tr>\n<tr>\n<td>درست ITR فارم</td>\n<td>ITR-3</td>\n<td>واپسی کو عیب دار سمجھا جا سکتا ہے۔</td>\n</tr>\n</tbody></table>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>کیپٹل گین کے تحت ایف اینڈ او فائل کرنا آپ کی واپسی کو \"عیب دار\" بنا سکتا ہے۔ محکمہ عیب دار واپسی کا نوٹس جاری کر سکتا ہے، اور آپ کو درست سر کے تحت دوبارہ فائل کرنا پڑ سکتا ہے۔ غلط باکس ایک چھوٹی پرچی نہیں ہے؛ یہ پوری واپسی کو کھول سکتا ہے۔</p>\n</div></div>\n<h2 id=\"two-traders-one-profit-two-very-different-outcomes\">دو تاجر، ایک منافع، دو بہت مختلف نتائج</h2>\n<p>آئیے روحان اور میرا پر اصلی روپیہ ڈال دیں۔ دونوں تنخواہ دار ہیں، دونوں تنخواہ میں 12 لاکھ روپے کماتے ہیں، اور دونوں نے 3 لاکھ روپے کا تجارتی F&amp;O بنایا ہے۔ اس لیے ان کی کل آمدنی 15 لاکھ روپے ہے۔ ہم 2026-27 کے لیے نئے رجیم سلیبس کا استعمال کریں گے، جو پہلے سے طے شدہ نظام ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>قابل ٹیکس آمدنی</th>\n<th>ٹیکس کی شرح</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>4 لاکھ روپے تک</td>\n<td>صفر</td>\n</tr>\n<tr>\n<td>4 لاکھ سے 8 لاکھ روپے</td>\n<td>5%</td>\n</tr>\n<tr>\n<td>8 لاکھ سے 12 لاکھ روپے</td>\n<td>10%</td>\n</tr>\n<tr>\n<td>12 لاکھ سے 16 لاکھ روپے</td>\n<td>15%</td>\n</tr>\n<tr>\n<td>16 لاکھ سے 20 لاکھ روپے</td>\n<td>20%</td>\n</tr>\n<tr>\n<td>20 لاکھ سے 24 لاکھ روپے</td>\n<td>25%</td>\n</tr>\n<tr>\n<td>24 لاکھ روپے سے زیادہ</td>\n<td>30%</td>\n</tr>\n</tbody></table>\n<p>میرا فائل درست ہے۔ اس کا 3 لاکھ روپے کا F&amp;O منافع کاروباری آمدنی ہے اور اس کی تنخواہ کے اوپر ڈھیر ہے۔ 12 لاکھ سے 15 لاکھ روپے تک کا ٹکڑا 12 لاکھ سے 16 لاکھ روپے کے بینڈ میں بیٹھتا ہے، جس پر 15 فیصد ٹیکس لگایا جاتا ہے۔ اس سے پہلے، اس نے حقیقی تجارتی اخراجات میں سے 20,000 روپے کو منہا کیا، اس لیے اس پر واقعی 2,80,000 روپے کے منافع پر ٹیکس لگایا جاتا ہے۔ 2,80,000 کا پندرہ فیصد 42,000 روپے کے علاوہ 4 فیصد سیس ہے۔ وہ مستقبل کے کسی بھی F&amp;O نقصان کو آگے بڑھانے کا حق بھی رکھتی ہے۔</p>\n<p>روہن وہی 3 لاکھ روپے شارٹ ٹرم کیپٹل گین کے طور پر فائل کرتا ہے۔ سیکشن 111A ٹیکس لگاتا ہے جو کہ فلیٹ 20%، جو کہ 60,000 روپے کے علاوہ سیس ہے۔ اس نے کوئی اخراجات کا دعویٰ نہیں کیا، کیونکہ سرمائے سے حاصل ہونے والا فائدہ اس کے انٹرنیٹ بل یا ریسرچ ٹولز کی اجازت نہیں دیتا۔ اور اس نے غلط سر کے تحت فائل کر دی ہے، اس لیے اب اسے زیادہ ادائیگی کرنے پر ایک ناقص ریٹرن نوٹس کا خطرہ ہے۔ ایک ہی منافع، بدتر نتیجہ، اور اسے ختم کرنے کے لیے تعمیل کا مسئلہ۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>میرا: 3,00,000 روپے کا منافع مائنس 20,000 روپے کے اخراجات 2,80,000 روپے کے برابر ہیں، اس کے 15% سلیب پر ٹیکس لگایا گیا ہے، تقریباً 42,000 روپے کے علاوہ سیس۔ روہن: 3,00,000 روپے غلط طریقے سے 20% پر قلیل مدتی کیپٹل گین کے طور پر ٹیکس، 60,000 روپے جمع سیس، کوئی اخراجات کی اجازت نہیں، اور عیب دار واپسی کا خطرہ۔ ان کے درمیان فرق صرف یہ تھا کہ ہر ایک نے منتخب کیا تھا۔</p>\n</div></div>\n<h2 id=\"filing-it-right-itr-3-slab-rates-and-form-10-iea\">اسے درست کرنا: ITR-3، سلیب کی شرحیں اور فارم 10-IEA</h2>\n<p>ایک بار جب آپ یہ قبول کر لیتے ہیں کہ F&amp;O ایک کاروبار ہے، تو عملی اقدامات صاف ستھرا ہو جاتے ہیں۔</p>\n<p>آپ F&amp;O میں رپورٹ کرتے ہیں۔ <strong>ITR-3</strong>کاروبار اور پیشہ ورانہ آمدنی کے لیے بنایا گیا واپسی فارم۔ سادہ تنخواہ اور سرمایہ کار فارم میں اس کے لیے کوئی جگہ نہیں ہے۔ زیادہ تر فعال تاجر بالکل اسی وجہ سے ITR-3 پر ختم ہوتے ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>آپ کون ہیں۔</th>\n<th>فارم</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>تنخواہ اور سادہ سرمایہ کار، چھوٹی آمدنی</td>\n<td>ITR-1 (سہج)، لیکن کاروبار یا F&amp;O کے لیے نہیں۔</td>\n</tr>\n<tr>\n<td>کیپٹل گین کے ساتھ سرمایہ کار، غیر ملکی اثاثے، کرپٹو بطور کیپٹل گین</td>\n<td>ITR-2</td>\n</tr>\n<tr>\n<td>F&amp;O، انٹرا ڈے، یا بطور کاروبار تجارت</td>\n<td>ITR-3 (زیادہ تر تاجر)</td>\n</tr>\n</tbody></table>\n<p>آپ کے F&amp;O منافع پر سلیب کی شرحوں پر ٹیکس لگایا جاتا ہے، جس سے آپ کی کل آمدنی میں اضافہ ہوتا ہے جیسا کہ اوپر دکھایا گیا ہے۔ نیا نظام 2026-27 AY کے لیے پہلے سے طے شدہ ہے، اور اس کے تحت سیکشن 87A 60,000 روپے تک کی چھوٹ کا مطلب ہے کہ 12 لاکھ روپے تک قابل ٹیکس آمدنی مؤثر طریقے سے کوئی ٹیکس ادا نہیں کرتی ہے۔ اگر ایک معمولی F&amp;O منافع آپ کی کل آمدنی کو 12 لاکھ روپے سے کم رکھتا ہے، تو چھوٹ ٹیکس کو مکمل طور پر ختم کر سکتی ہے، لیکن آپ کو پھر بھی اس کی اطلاع دینی ہوگی۔</p>\n<p>ایک ٹریپ ایک جھنڈے کا مستحق ہے۔ اگر آپ کی کاروباری آمدنی ہے، جیسا کہ F&amp;O، اور آپ پہلے سے طے شدہ نئی کی بجائے OLD نظام کا انتخاب کرنا چاہتے ہیں، تو آپ کو فائل کرنا ہوگی۔ <strong>فارم 10-IEA</strong> سیکشن 139(1) کے تحت مقررہ تاریخ تک۔ اس فارم سے محروم ہو جائیں اور آپ سال کے لیے نئی حکومت میں بند ہو جائیں۔ ایک چارٹرڈ اکاؤنٹنٹ آپ کو بتا سکتا ہے کہ اصل میں آپ کے لیے کون سا نظام مناسب ہے، لیکن آپٹ آؤٹ کرنے کی آخری تاریخ بھول جانا آسان ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>جس لمحے آپ اپنی پہلی F&amp;O تجارت کرتے ہیں، ذہنی طور پر اپنے آپ کو \"بزنس\" کے تحت فائل کریں۔ ITR-3 استعمال کرنے کا منصوبہ بنائیں، اپنے اخراجات کے ثبوت محفوظ کرنا شروع کریں، اور اپنی حکومت کا جلد فیصلہ کریں۔ پہلے دن سے F&amp;O کو چھوٹے کاروبار کے طور پر پیش کرنا اس باب میں تقریباً ہر غلطی کو روکتا ہے۔</p>\n</div></div>\n<p>روہن کی غلطی سمجھ میں آتی تھی، لیکن یہ پھر بھی ایک غلطی تھی، اور اس کی وجہ سے اسے پیسے اور ذہنی سکون کا نقصان اٹھانا پڑا۔ میرا کا راستہ مشکل نہیں تھا۔ یہ صرف مطلع کیا گیا تھا. ایف اینڈ او ٹیکس قانون کی نظر میں ایک کاروبار ہے۔ ITR-3 میں اس کی اطلاع دیں، اس پر اپنے سلیب پر ٹیکس لگائیں، اپنے حقیقی اخراجات کا دعوی کریں، اور اپنے نقصانات کی حفاظت کریں، اور نمبر ایک ابتدائی غلطی اب آپ کے لیے دستیاب نہیں ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>F&amp;O غیر قیاس آرائی پر مبنی کاروباری آمدنی ہے۔ سلیب ریٹ، فلیٹ کیپٹل گین ریٹ نہیں۔ ITR-3، سادہ سرمایہ کار فارم نہیں۔ اخراجات کی اجازت ہے۔ تنخواہ کے علاوہ زیادہ تر آمدنی کے مقابلے میں نقصانات طے پاتے ہیں۔ بالٹی کو درست کریں اور باقی سب کچھ اس کی پیروی کریں۔</p>\n</div></div>\n<p>یہ باب صرف سیکھنے کے لیے ہے اور ٹیکس کا مشورہ نہیں ہے۔ ٹیکس کے قوانین اور شرحیں ہر سال تبدیل ہوتی ہیں، اس لیے فائل کرنے سے پہلے براہ کرم ایک قابل چارٹرڈ اکاؤنٹنٹ سے اپنی صورتحال کی تصدیق کریں۔</p>\n","toc":[{"level":2,"text":"F&O کاروباری آمدنی ہے، نہ کہ کیپٹل گین","id":"f-o-is-business-income-not-capital-gains"},{"level":2,"text":"آپ جس بالٹی کا انتخاب کرتے ہیں وہ سب کچھ کیوں بدلتا ہے۔","id":"why-the-bucket-you-choose-changes-everything"},{"level":2,"text":"دو تاجر، ایک منافع، دو بہت مختلف نتائج","id":"two-traders-one-profit-two-very-different-outcomes"},{"level":2,"text":"اسے درست کرنا: ITR-3، سلیب کی شرحیں اور فارم 10-IEA","id":"filing-it-right-itr-3-slab-rates-and-form-10-iea"}],"imgCount":1,"hasContent":true},"10":{"html":"<p>انیتا نے اپنی بروکر ٹیکس رپورٹ کھولی، نیچے تک سکرول کی، اور اپنے پیٹ میں کمی محسوس کی۔ \"ٹوٹل کنٹریکٹ ویلیو ٹریڈڈ\" لائن 3.2 کروڑ روپے تھی۔ اس نے سارا سال نفٹی اور بینک نفٹی آپشنز کی تجارت کی تھی، ایک وقت میں چند لاٹ، اور کسی نہ کسی طرح یہ تعداد بڑھ کر ایک ایسی تعداد تک پہنچ گئی تھی کہ ایسا لگتا تھا کہ وہ ایک چھوٹی سلطنت چلا رہی ہے۔ \"اگر میرا ٹرن اوور تین کروڑ سے زیادہ ہے،\" اس نے سوچا، \"مجھے ٹیکس آڈٹ کی ضرورت ہے، شاید قسمت کا قرض بھی ہو۔\" اس نے لیپ ٹاپ بند کر دیا اور ایک ایسے نمبر پر رات کی نیند کھو دی جس کا کوئی مطلب نہیں تھا۔</p>\n<p>انیتا نے ٹرن اوور کی سب سے عام غلطی کی۔ اس نے اپنے ٹیکس ٹرن اوور کے ساتھ ان معاہدوں کی قدر کو الجھا دیا۔ وہ بالکل مختلف چیزیں ہیں، اور ان کے درمیان فاصلہ بہت زیادہ ہے۔ یہ باب آپ کو دکھاتا ہے کہ F&amp;O ٹرن اوور واقعی کیا ہے، چند منٹوں میں اس کی گنتی کیسے کی جائے، اور آپ کو ٹیکس لگانے سے پہلے کن اخراجات کو کم کرنے کی اجازت ہے۔</p>\n<h2 id=\"turnover-is-not-the-contract-value\">ٹرن اوور معاہدہ کی قیمت نہیں ہے۔</h2>\n<p>جب آپ ایک نفٹی لاٹ ٹریڈ کرتے ہیں تو معاہدہ کئی لاکھ روپے کا ہو سکتا ہے۔ ایک سال میں چند سو بار اندر اور باہر تجارت ہوتی ہے اور ان معاہدے کی قیمتیں کروڑوں تک پہنچ جاتی ہیں۔ لیکن وہ ڈھیر ٹیکس کے مقاصد کے لیے آپ کا کاروبار نہیں ہے۔ یہ کبھی نہیں تھا۔</p>\n<p>ٹیکس آڈٹ کی حد کو پورا کرنے کے لیے، اکاؤنٹنسی باڈی کی رہنمائی واضح ہے۔ <strong>ٹرن اوور معاہدہ کی قیمت نہیں ہے۔</strong> یہ ہے <strong>آپ کے موافق اور ناموافق اختلافات کا مجموعی</strong>. صاف الفاظ میں، آپ ہر نفع اور ہر نقصان کی مطلق قدر کو شامل کرتے ہیں۔ نقصان یہاں مثبت نمبر کے طور پر شمار ہوتا ہے، منفی نہیں۔ آپ پیمائش کر رہے ہیں کہ آپ نے کتنی تجارت کی، یہ نہیں کہ آپ جیت گئے یا ہار گئے۔</p>\n<p>یہ واحد آئیڈیا انیتا کے خوفناک 3.2 کروڑ روپے کو کم کر کے بہت چھوٹی اور کہیں زیادہ ایماندار چیز تک لے جاتا ہے۔ اس کے کنٹریکٹ کی مالیت کروڑوں تھی۔ اس کا اصل ٹرن اوور، ایک بار جب ہم صرف منافع اور نقصانات کو شامل کرتے ہیں، تو اس کا ایک چھوٹا سا حصہ نکلتا ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>F&amp;O کے لیے ٹرن اوور ہر منافع اور ہر نقصان کی مطلق قدروں کا مجموعہ ہے، نہ کہ ان معاہدوں کی قدر جن کی آپ تجارت کرتے ہیں۔ 12,000 روپے کا منافع اور 8,000 روپے کا نقصان مل کر آپ کے ٹرن اوور میں 20,000 روپے کا اضافہ کرتا ہے، کئی لاکھ نہیں۔</p>\n</div></div>\n<h2 id=\"the-absolute-difference-method-worked-step-by-step\">مطلق فرق کا طریقہ، قدم بہ قدم کام کیا۔</h2>\n<p>یہ سیکھنے کا سب سے صاف طریقہ تین تجارتوں کے ساتھ ہے۔ فرض کریں کہ سال بھر میں آپ بالکل تین F&amp;O تجارت کرتے ہیں اور وہ اس طرح طے پاتے ہیں:</p>\n<table>\n<thead>\n<tr>\n<th>تجارت</th>\n<th>نتیجہ</th>\n<th>مطلق قدر (ٹرن اوور کے لیے)</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>سب سے پہلے</td>\n<td>12,000 روپے کا منافع</td>\n<td>12,000</td>\n</tr>\n<tr>\n<td>دوسرا</td>\n<td>8000 روپے کا نقصان</td>\n<td>8,000</td>\n</tr>\n<tr>\n<td>تیسرا</td>\n<td>5000 روپے کا منافع</td>\n<td>5,000</td>\n</tr>\n</tbody></table>\n<p>اپنا ٹرن اوور حاصل کرنے کے لیے، آپ پلس اور مائنس علامات کو نظر انداز کرتے ہیں اور تینوں مطلق قدروں کو ایک ساتھ شامل کرتے ہیں۔ لہذا کاروبار 12,000 جمع 8,000 جمع 5,000 کے برابر ہے، جو <strong>25,000 روپے</strong>.</p>\n<p>اب اس کا اپنے اصل منافع سے موازنہ کریں، جس پر آپ پر ٹیکس لگایا جاتا ہے۔ وہاں آپ علامات کا احترام کرتے ہیں: 12,000 مائنس 8,000 جمع 5,000 برابر a <strong>9,000 روپے کا خالص منافع</strong>. ایک ہی تین تجارت سے دو مختلف نمبر، دو مختلف کام کر رہے ہیں۔ 25,000 روپے کا ٹرن اوور صرف یہ چیک کرنے کے لیے استعمال ہوتا ہے کہ آیا آپ آڈٹ کی حد کو عبور کرتے ہیں۔ 9,000 روپے کا خالص منافع وہی ہے جس پر اصل میں ٹیکس لگایا جاتا ہے۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>تین تجارت: منافع 12,000، نقصان 8,000، منافع 5,000۔ ٹرن اوور 12,000 جمع 8,000 جمع 5,000 برابر 25,000 روپے ہے۔ خالص منافع 12,000 مائنس 8,000 جمع 5,000 برابر ہے 9,000 روپے۔ ٹرن اوور سرگرمی کی پیمائش کرتا ہے؛ خالص منافع اس رقم کی پیمائش کرتا ہے جو آپ رکھتے ہیں اور ٹیکس ادا کرتے ہیں۔</p>\n</div></div>\n<p>یہ طریقہ انیتا کے پاس لے جائیں۔ اس کے معاہدے کی قیمت 3.2 کروڑ روپے تھی، لیکن جب اس نے سال بھر میں ہر جیتنے اور ہارنے والی تجارت کی مطلق قیمت کو جوڑ دیا، تو اس کا کاروبار تقریباً 6 لاکھ روپے ہو گیا۔ یہ وہ نمبر ہے جو آڈٹ کے سوال کے لیے اہمیت رکھتا ہے، اور یہ کروڑوں کے قریب کہیں نہیں ہے جس نے اسے خوفزدہ کیا۔ معاہدے کی قیمت ایک سرخ ہیرنگ تھی۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/taxation/images/diagram-fno-turnover.png\" alt=\"F&amp;O ٹرن اوور ہر منافع اور ہر نقصان کی مطلق قدروں کا مجموعہ ہے، معاہدے کی قیمت نہیں۔ 12,000 کا منافع، 8,000 کا نقصان اور 5,000 کا منافع 25,000 کا ٹرن اوور اور 9,000 کا خالص منافع بناتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>F&amp;O ٹرن اوور ہر منافع اور ہر نقصان کی مطلق قدروں کا مجموعہ ہے، معاہدے کی قیمت نہیں۔ 12,000 کا منافع، 8,000 کا نقصان اور 5,000 کا منافع 25,000 کا ٹرن اوور اور 9,000 کا خالص منافع بناتا ہے۔</figcaption></figure>\n<h2 id=\"options-add-the-premium-received-on-sale\">اختیارات فروخت پر موصول ہونے والے پریمیم کو شامل کرتے ہیں۔</h2>\n<p>اختیارات میں ایک اضافی موڑ ہے، اور یہ درست ہونے کے قابل ہے۔ اختیارات کے لیے، آپ شامل کریں۔ <strong>اختیارات کی فروخت پر موصول ہونے والا پریمیم</strong> ٹرن اوور کے اعداد و شمار کے ساتھ ساتھ، سازگار اور ناموافق فرق کے اوپر۔</p>\n<p>وجہ یہ ہے کہ جب آپ کوئی آپشن بیچتے یا لکھتے ہیں تو آپ کو جو پریمیم ملتا ہے وہ خود آپ کے کاروبار کا ایک پیمانہ ہوتا ہے۔ تو یہ ٹرن اوور کی گنتی میں شامل ہو جاتا ہے۔ دوہری گنتی کے خلاف ایک سمجھدار محافظ ہے۔ اگر وہ سیل پریمیم پہلے سے ہی آپ کے خالص منافع کے اعداد و شمار کے اندر بیٹھا ہوا ہے، تو آپ اسے دوسری بار شامل نہیں کرتے ہیں۔ مقصد یہ ہے کہ سرگرمی کے ہر روپے کو ایک بار شمار کیا جائے، دو بار نہیں۔</p>\n<p>عملی طور پر آپ کو یہ ریاضی ہاتھ سے بالکل نہیں کرنا چاہیے۔ آپ کا بروکر ٹیکس منافع اور نقصان کا بیان فراہم کرتا ہے، جس پر اکثر \"ٹرن اوور رپورٹ\" کا لیبل لگایا جاتا ہے، جو آپ کے لیے پہلے سے ہی ان اصولوں کا اطلاق کرتا ہے۔ یہ آپ کے حاصل شدہ منافع، آپ کے محسوس شدہ نقصانات، اور آپشن پریمیم جز کی فہرست بناتا ہے، اور یہ ٹرن اوور کو جس طرح رہنمائی کی ضرورت ہوتی ہے، کو جمع کرتا ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>اپنے معاہدے کے نوٹوں سے ہاتھ سے F&amp;O ٹرن اوور کی گنتی نہ کریں۔ اپنے بروکر کی ٹیکس منافع اور نقصان یا ٹرن اوور رپورٹ ڈاؤن لوڈ کریں، جو پہلے سے ہی مکمل منافع، مطلق نقصانات، اور آپشن سیل پریمیم کو صحیح طریقے سے شامل کرتی ہے۔ پھر اس پر بھروسہ کرنے سے پہلے چارٹرڈ اکاؤنٹنٹ سے اعداد و شمار کا جائزہ لیں۔</p>\n</div></div>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>اپنے ٹرن اوور کے طور پر کبھی بھی معاہدے کی قیمت یا کل تجارت شدہ قیمت کا استعمال نہ کریں۔ یہ حقیقی اعداد و شمار سے کئی گنا بڑا ہے اور آپ کو یقین دلائے گا کہ آپ نے اس حد کو عبور کر لیا ہے کہ آپ کہیں بھی قریب نہیں ہیں۔ آڈٹ سوال کا فیصلہ کنٹریکٹ ویلیو پر نہیں، مطلق فرق کے ٹرن اوور پر کیا جاتا ہے۔</p>\n</div></div>\n<h2 id=\"the-expenses-you-are-allowed-to-claim\">وہ اخراجات جن کا آپ کو دعویٰ کرنے کی اجازت ہے۔</h2>\n<p>یہاں F&amp;O کے کاروبار ہونے کا پرسکون فائدہ ہے۔ کسی کاروبار پر اخراجات کے بعد اس کے منافع پر ٹیکس لگایا جاتا ہے، نہ کہ اس کی مجموعی آمدنی پر۔ لہذا اس سے پہلے کہ آپ کے F&amp;O منافع پر ٹیکس لگایا جائے، آپ اسے کمانے کے حقیقی اخراجات کو منہا کر سکتے ہیں۔ یہ حقیقی کٹوتیاں ہیں جو آپ کے ٹیکس کو کم کرتی ہیں، اور زیادہ تر ابتدائی ان کا دعوی کرنا بھول جاتے ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>خرچہ</th>\n<th>یہ کیا احاطہ کرتا ہے</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>دلالی</td>\n<td>وہ فیس جو آپ کا بروکر ہر تجارت پر لیتا ہے۔</td>\n</tr>\n<tr>\n<td>سیکیورٹیز ٹرانزیکشن ٹیکس (STT)</td>\n<td>ایک تاجر کے لیے، تجارت پر ادا کردہ STT ایک کاروباری خرچ ہے۔</td>\n</tr>\n<tr>\n<td>ایکسچینج اور ٹرانزیکشن چارجز</td>\n<td>آپ کی تجارت پر تبادلہ، کلیئرنگ اور ریگولیٹری فیس</td>\n</tr>\n<tr>\n<td>انٹرنیٹ اور فون</td>\n<td>کنکشن جس پر آپ تجارت کرتے ہیں اور تحقیق کرتے ہیں۔</td>\n</tr>\n<tr>\n<td>چارٹنگ، ڈیٹا اور ریسرچ ٹولز</td>\n<td>چارٹنگ پلیٹ فارمز، ڈیٹا فیڈز، تحقیق کی سبسکرپشنز</td>\n</tr>\n<tr>\n<td>چارٹرڈ اکاؤنٹنٹ فیس</td>\n<td>ریٹرن تیار کرنے اور فائل کرنے کے لیے آپ اپنے CA کو کیا ادا کرتے ہیں۔</td>\n</tr>\n<tr>\n<td>لیپ ٹاپ یا کمپیوٹر کی قدر میں کمی</td>\n<td>تجارت کے لیے استعمال ہونے والے سامان کی قیمت کا سالانہ حصہ</td>\n</tr>\n</tbody></table>\n<p>ان میں سے چند ایک لفظ کے مستحق ہیں۔ STT، جو ٹیکس خود تجارت پر لگایا جاتا ہے، اسے تاجر کے لیے قابل کٹوتی کاروباری اخراجات کے طور پر سمجھا جاتا ہے، ایک سرمایہ کار کے برعکس۔ ایک لیپ ٹاپ جیسے آلات کو ایک ساتھ نہیں نکالا جاتا۔ اس کے بجائے آپ دعوی کرتے ہیں <strong>فرسودگی</strong>، جس کا سیدھا مطلب ہے کہ ہر سال اس کی لاگت کا ایک حصہ اس کی مفید زندگی پر لکھنا۔ آپ کا CA درست شرح کا اطلاق کرے گا۔</p>\n<p>ایک ساتھ رکھو، یہ اخراجات معنی خیز ہوسکتے ہیں۔ 1,50,000 روپے خالص F&amp;O منافع کے ساتھ ایک تاجر کا تصور کریں جس نے بروکریج میں 18,000 روپے اور STT، انٹرنیٹ اور چارٹنگ سبسکرپشن کے لیے 12,000 روپے، اور ایک CA کے لیے 8,000 روپے، مزید 7,000 روپے لیپ ٹاپ ڈیپریشن کے ساتھ۔ یعنی جائز اخراجات کے 45,000 روپے۔ اس کے بعد تاجر پر 1,50,000 روپے مائنس 45,000 ٹیکس لگایا جاتا ہے، جو کہ <strong>1,05,000 روپے</strong>پورے 1,50,000 روپے نہیں۔ 15% سلیب پر اس ایک قدم سے ٹیکس میں تقریباً 6,750 روپے کی بچت ہوتی ہے، یہ سب بالکل قانونی ہے۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>خرچ حقیقی ہونا چاہیے اور آپ کی ٹریڈنگ سے منسلک ہونا چاہیے۔ ذاتی چھٹی کوئی خرچ نہیں ہے۔ ایک ڈیٹا سبسکرپشن جو آپ اصل میں تجارت کے لیے استعمال کرتے ہیں۔ اگر لاگت کا کچھ حصہ ملایا جاتا ہے، جیسا کہ گھریلو انٹرنیٹ بل ٹریڈنگ اور ذاتی براؤزنگ دونوں کے لیے استعمال ہوتا ہے، تو صرف معقول ٹریڈنگ شیئر کا دعوی کریں اور اپنے CA کو تقسیم کی رہنمائی کریں۔</p>\n</div></div>\n<h2 id=\"keep-your-proofs-or-the-deduction-may-not-hold\">اپنے ثبوت رکھیں، ورنہ کٹوتی نہیں ہو سکتی</h2>\n<p>ایک کٹوتی جو آپ ثابت نہیں کر سکتے ہیں وہ کٹوتی ہے اگر آپ سے کبھی پوچھا جائے تو آپ کھو سکتے ہیں۔ ٹھیک کرنا آسان ہے اور یہ ایک عادت ہے، پروجیکٹ نہیں۔ سال کے ساتھ ساتھ کاغذی کارروائی جاری رکھیں۔</p>\n<p>اپنے بروکر کے معاہدے کے نوٹ اور سالانہ ٹیکس منافع اور نقصان کی رپورٹ کو محفوظ کریں۔ کسی بھی ٹولز، سبسکرپشنز اور اپنی CA فیس کے لیے رسیدیں رکھیں۔ بینک اور کارڈ اسٹیٹمنٹس کو پکڑے رکھیں جو آپ کے اکاؤنٹ سے ادائیگیوں کو ظاہر کرتے ہیں۔ انہیں ایک فولڈر، ڈیجیٹل یا کاغذ میں فائل کریں، تاکہ فائلنگ کے وقت سب کچھ ایک جگہ پر ہو اور میموری سے کچھ بھی دوبارہ نہ بنایا جائے۔</p>\n<p>یہ ٹرن اوور نمبر کے لیے بھی اہم ہے۔ وہی بروکر رپورٹ جو آپ کے اخراجات کو ثابت کرتی ہے یہ بھی دستاویز کرتی ہے کہ آپ کے ٹرن اوور کی گنتی کیسے کی گئی۔ اگر کبھی کوئی سوال پیدا ہوتا ہے کہ آیا آپ نے آڈٹ کی حد کو عبور کیا ہے، تو وہ رپورٹ آپ کے اس بات کا ثبوت ہے کہ اعداد و شمار کو درست طریقے سے بنایا گیا تھا۔</p>\n<p>انیتا کی گھبراہٹ اس لمحے ختم ہوگئی جب وہ فرق سمجھ گئی۔ اس کا حقیقی کاروبار معمولی تھا، اس کا خالص منافع ایک واضح تعداد تھا جس کے بارے میں وہ منصوبہ بندی کر سکتی تھی، اور اس کے بروکریج، ڈیٹا اور CA فیسوں کے سال کی کٹوتیوں کی وجہ سے اس کا ٹیکس کم ہوا۔ اس کی تجارت کے بارے میں کچھ نہیں بدلا۔ صرف اس کی سمجھ نے کیا، اور عام طور پر بس اتنا ہی ہوتا ہے۔</p>\n<p>یہ باب صرف سیکھنے کے لیے ہے اور ٹیکس کا مشورہ نہیں ہے۔ ٹیکس کے قوانین اور ٹرن اوور کی رہنمائی تبدیل ہو سکتی ہے، اس لیے براہ کرم فائل کرنے سے پہلے کسی قابل چارٹرڈ اکاؤنٹنٹ سے اپنے ٹرن اوور اور اخراجات کی تصدیق کریں۔</p>\n","toc":[{"level":2,"text":"ٹرن اوور معاہدہ کی قیمت نہیں ہے۔","id":"turnover-is-not-the-contract-value"},{"level":2,"text":"مطلق فرق کا طریقہ، قدم بہ قدم کام کیا۔","id":"the-absolute-difference-method-worked-step-by-step"},{"level":2,"text":"اختیارات فروخت پر موصول ہونے والے پریمیم کو شامل کرتے ہیں۔","id":"options-add-the-premium-received-on-sale"},{"level":2,"text":"وہ اخراجات جن کا آپ کو دعویٰ کرنے کی اجازت ہے۔","id":"the-expenses-you-are-allowed-to-claim"},{"level":2,"text":"اپنے ثبوت رکھیں، ورنہ کٹوتی نہیں ہو سکتی","id":"keep-your-proofs-or-the-deduction-may-not-hold"}],"imgCount":1,"hasContent":true},"11":{"html":"<p>وکرم کا ایک مشکل سال تھا۔ اس کی F&amp;O تجارتوں میں تقریباً 2 لاکھ روپے کا نقصان ہوا، اور گویا رقم کھو دینا کافی نہیں تھا، جم میں موجود ایک دوست نے اسے کچھ بتایا جس سے یہ اور بھی خراب ہوگیا۔ \"اگر آپ نے F&amp;O میں نقصان کیا ہے، تو آپ کو خود بخود ٹیکس آڈٹ کی ضرورت ہے۔ اس کا مطلب ہے کہ ایک CA، فیٹ فیس، اور آپ کے پورے اکاؤنٹ میں رینگنے والا محکمہ۔\" وکرم اس بات پر یقین کر کے گھر چلا گیا کہ وہ مشکل میں ہے، اور اس نے بالکل بھی فائل نہ کرنے کا فیصلہ کیا، صرف پوشیدہ رہنے کے لیے۔</p>\n<p>اس کا دوست اعتماد سے، بالکل غلط تھا۔ نقصان خود آڈٹ کو متحرک نہیں کرتا ہے۔ پھر بھی یہ افسانہ اتنا وسیع ہے کہ یہ ایماندار تاجروں کو یا تو مہنگی گھبراہٹ میں ڈالتا ہے یا اس سے بھی بدتر، فائلنگ نہیں کرتا۔ یہ باب آپ کو یہ معلوم کرنے کے لیے ایک پرسکون، تین قدمی چیک فراہم کرتا ہے کہ آیا آپ کو واقعی ٹیکس آڈٹ کی ضرورت ہے، اور یہ \"نقصان کے برابر آڈٹ\" کے افسانے کو اچھے کے لیے آرام دیتا ہے۔</p>\n<h2 id=\"the-three-step-check\">تین قدمی چیک</h2>\n<p>آیا ایک F&amp;O تاجر کو سیکشن 44AB کے تحت ٹیکس آڈٹ کی ضرورت ہے، ترتیب میں پوچھے گئے تین سوالات ہیں۔ آپ خوفناک نتیجے پر نہیں جائیں گے۔ تم قدم چلو۔</p>\n<table>\n<thead>\n<tr>\n<th>قدم</th>\n<th>سوال</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>مرحلہ 1</td>\n<td>میرا F&amp;O ٹرن اوور کیا ہے؟</td>\n</tr>\n<tr>\n<td>مرحلہ 2</td>\n<td>آڈٹ کی کون سی حد مجھ پر لاگو ہوتی ہے، اور کیا میں نے اسے عبور کیا ہے؟</td>\n</tr>\n<tr>\n<td>مرحلہ 3</td>\n<td>اگر میں حد سے نیچے ہوں، تو کیا کوئی خاص اصول اب بھی مجھے اپنی طرف کھینچتے ہیں؟</td>\n</tr>\n</tbody></table>\n<p>زیادہ تر تاجروں کو مرحلہ 2 تک واضح جواب مل جاتا ہے اور وہ کبھی بھی پریشان کن جگہ پر نہیں پہنچتے۔ آئیے ہر قدم آہستہ آہستہ چلتے ہیں۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/taxation/images/diagram-fno-audit-steps.png\" alt=\"تین قدمی آڈٹ چیک: پہلے اپنے ٹرن اوور کو تلاش کریں، پھر اسے صحیح حد کے خلاف جانچیں، پھر کچھ بھی نتیجہ اخذ کرنے سے پہلے ٹیکس کے خصوصی اصولوں کو چیک کریں۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>تین قدمی آڈٹ چیک: پہلے اپنے ٹرن اوور کو تلاش کریں، پھر اسے صحیح حد کے خلاف جانچیں، پھر کچھ بھی نتیجہ اخذ کرنے سے پہلے ٹیکس کے خصوصی اصولوں کو چیک کریں۔</figcaption></figure>\n<h2 id=\"step-1-find-your-turnover\">مرحلہ 1، اپنا کاروبار تلاش کریں۔</h2>\n<p>آپ اس وقت تک کسی حد کی جانچ نہیں کر سکتے جب تک آپ کو معلوم نہ ہو کہ ٹیسٹ کیا جا رہا ہے۔ لہذا پہلا قدم ہمیشہ پچھلے باب کے طریقہ کار کو استعمال کرتے ہوئے اپنے F&amp;O ٹرن اوور کی گنتی کرنا ہے۔</p>\n<p>یاد رکھیں کہ ٹرن اوور آپ کے معاہدے کی قیمت نہیں ہے۔ یہ ہے <strong>آپ کے موافق اور ناموافق اختلافات کا مجموعی</strong>، جس کا مطلب ہے کہ آپ ہر منافع اور ہر نقصان کی مطلق قیمت کا اضافہ کرتے ہیں، اور اختیارات کے لیے آپ فروخت پر موصول ہونے والا پریمیم بھی شامل کرتے ہیں۔ آپ کے بروکر کی ٹیکس منافع اور نقصان کی رپورٹ آپ کے لیے ایسا کرتی ہے۔</p>\n<p>یہاں توجہ دینے والی سب سے اہم بات یہ ہے کہ ٹرن اوور کے حساب سے اس بات کی کوئی پرواہ نہیں ہوتی کہ آپ مجموعی طور پر جیت گئے یا ہار گئے۔ خسارے میں جانے والا سال اب بھی ٹرن اوور کا اعداد و شمار پیش کرتا ہے، جو اکثر بالکل عام ہوتا ہے۔ وکرم کو 2 لاکھ روپے کا نقصان ہوا، لیکن جب اس نے اپنے تمام جیتنے اور ہارنے والے تجارت کی مطلق قیمت کو جوڑ دیا، تو اس کا کاروبار تقریباً 40 لاکھ روپے تک پہنچ گیا۔ یہ 40 لاکھ روپے کا نمبر ہے مرحلہ 2 ٹیسٹ کرے گا، اس کا 2 لاکھ روپے کا نقصان نہیں۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>آڈٹ ٹیسٹ آپ کے ٹرن اوور پر چلتا ہے، آپ کے نفع یا نقصان پر نہیں۔ خسارے میں چلنے والے تاجر کے پاس اب بھی ٹرن اوور کا اعداد و شمار ہوتا ہے، اور یہی اعداد و شمار آڈٹ کے سوال کا فیصلہ کرتے ہیں۔ چاہے آپ نے پیسہ کمایا یا کھو دیا یہ مرحلہ 2 میں داخل نہیں ہوتا ہے۔</p>\n</div></div>\n<h2 id=\"step-2-which-threshold-applies\">مرحلہ 2، جس کی حد لاگو ہوتی ہے۔</h2>\n<p>اب آپ اپنے ٹرن اوور کا آڈٹ کی حد سے موازنہ کریں۔ کیچ یہ ہے کہ دو حدیں ہیں، اور آپ کو صحیح استعمال کرنا چاہیے۔</p>\n<table>\n<thead>\n<tr>\n<th>آپ کا حال</th>\n<th>ٹرن اوور کے لیے آڈٹ کی حد</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>نقد رسیدیں AND نقد ادائیگیاں کل کا 5% یا اس سے کم ہیں۔</td>\n<td>10 کروڑ روپے</td>\n</tr>\n<tr>\n<td>کچھ اور (زیادہ نقد شامل)</td>\n<td>1 کروڑ روپے</td>\n</tr>\n</tbody></table>\n<p>10 کروڑ روپے سے زیادہ کی حد صرف اس وقت لاگو ہوتی ہے جب آپ کی نقد رسیدیں اور آپ کی نقد ادائیگیاں آپ کے کل کا 5% یا اس سے کم ہوں۔ ایک تاجر جو بینکنگ سسٹم کے ذریعے پیسہ منتقل کرتا ہے، جو کہ تقریباً ہر ایک ہے، یہ شرط آرام سے پوری ہوتی ہے۔ فنڈز آپ کے ٹریڈنگ اکاؤنٹ میں الیکٹرانک طریقے سے آتے اور جاتے ہیں، اس لیے نقد بنیادی طور پر صفر ہے، اور آپ 10 کروڑ روپے کی فراخ حد کے لیے اہل ہیں۔ اگر آپ کسی طرح کاروبار کے ذریعے بڑی مقدار میں فزیکل کیش چلاتے ہیں، تو آپ اس کی بجائے 1 کروڑ روپے کی عام حد تک گر جائیں گے۔</p>\n<p>اسے وکرم کے پاس واپس لاؤ۔ اس کا کاروبار تقریباً 40 لاکھ روپے تھا، اور ہر روپیہ ڈیجیٹل طور پر منتقل ہوتا ہے، اس لیے اس کی حد 10 کروڑ روپے ہے۔ 40 لاکھ روپے 10 کروڑ کے قریب کہیں نہیں ہے۔ صرف ٹرن اوور ٹیسٹ پر، وکرم کو آڈٹ کی ضرورت نہیں ہے۔ اس کا 2 لاکھ روپے کا نقصان کبھی بھی موازنہ میں داخل نہیں ہوا۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>وکرم کا ٹرن اوور 40 لاکھ روپے ہے اور اس کی تمام رقم ڈیجیٹل طور پر منتقل ہوتی ہے، اس لیے اس کی نقد رقم 5% سے کم ہے اور اس کی حد 10 کروڑ روپے ہے۔ 40 لاکھ روپے 10 کروڑ روپے سے بہت کم ہے، اس لیے ٹرن اوور کی بنیاد پر اسے 2 لاکھ روپے کے نقصان کے باوجود کسی آڈٹ کی ضرورت نہیں ہے۔ نقصان صرف اس امتحان کا حصہ نہیں تھا۔</p>\n</div></div>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>5% نقد اصول وہ ہے جو 10 کروڑ روپے کی اونچی حد کو کھولتا ہے، اور ڈیجیٹل ٹریڈنگ تقریباً خود بخود اس پر پورا اترتی ہے۔ یہی وجہ ہے کہ عام خوردہ F&amp;O تاجروں کی بڑی اکثریت اس لائن سے بہت نیچے بیٹھتی ہے جس کے لیے صرف ٹرن اوور پر آڈٹ کی ضرورت ہوتی ہے۔</p>\n</div></div>\n<h2 id=\"step-3-below-the-threshold-but-not-yet-finished\">مرحلہ 3، حد سے نیچے لیکن ابھی تک ختم نہیں ہوا۔</h2>\n<p>فرض کریں کہ آپ کا کاروبار حد سے نیچے ہے، جیسا کہ وکرم کا ہے۔ آپ شاید واضح ہیں، لیکن آپ کو نتیجہ اخذ کرنے سے پہلے چیک کرنے کے لیے ایک اور خانہ موجود ہے، اور یہ وہ جگہ ہے جہاں حقیقی اہمیت رہتی ہے۔</p>\n<p>دو باتیں سچی اور واضح طور پر کہنے کے لائق ہیں۔ <strong>اکیلے نقصان کا مطلب آڈٹ نہیں ہے۔</strong> اور <strong>صرف بنیادی چھوٹ کی حد سے زیادہ آمدنی کا مطلب آڈٹ نہیں ہے۔</strong> یا تو ان حقائق میں سے کوئی بھی، خود آپ کو دفعہ 44AB میں مجبور نہیں کرتا ہے۔ یہ افسانہ کا دل ہے جس نے وکرم کو ڈرایا تھا۔</p>\n<p>جو کچھ اب بھی لاگو ہو سکتا ہے، مخصوص معاملات میں، اس کے تحت فرضی ٹیکس کا اصول ہے۔ <strong>دفعہ 44AD</strong>. فرضی اسکیم ایک آسان راستہ ہے جو اہل چھوٹے کاروباروں کو کم سے کم منافع کا اعلان کرنے اور تفصیلی بک کیپنگ کو چھوڑنے دیتا ہے۔ پیچیدگی اس اسکیم سے جڑے خاص حالات میں پیدا ہوتی ہے، مثال کے طور پر جہاں ایک تاجر جس نے پہلے فرضی اسکیم کا انتخاب کیا تھا، بعد میں سمجھے گئے اعداد و شمار سے کم منافع، یا نقصان کا اعلان کرتا ہے، جب کہ اس کی کل آمدنی بنیادی چھوٹ کی حد سے زیادہ ہے۔ اس مخصوص امتزاج میں، ایک آڈٹ ضروری ہو سکتا ہے۔</p>\n<p>یہ جان بوجھ کر اس قسم کا کیس ہے کہ آپ خود فیصلہ کرنے کے بجائے چارٹرڈ اکاؤنٹنٹ کے سامنے رکھیں، کیونکہ یہ آپ کی فائلنگ کی تاریخ اور آپ کے صحیح نمبروں پر منحصر ہے۔ فی الحال نقطہ نظر استدلال کی ترتیب ہے۔ آپ \"میرا نقصان تھا، لہذا مجھے ایک آڈٹ کی ضرورت ہے\" سے شروع نہیں کرتے۔ آپ ٹرن اوور اور حد کو صاف کرنے کے بعد ہی فرضی ٹیکس کی جانچ ختم کرتے ہیں، اور پھر بھی اکثر جواب نفی میں ہوتا ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>\"نقصان کے برابر آڈٹ\" کا افسانہ آپ کو فائل نہ کرنے پر مجبور نہ ہونے دیں۔ نقصان کی واپسی فائل کرنا بالکل وہی ہے جو آپ کی حفاظت کرتا ہے۔ یہ نقصان کو ریکارڈ کرتا ہے، آپ کو اسے آگے لے جانے دیتا ہے، اور آپ کے ریکارڈ کو صاف رکھتا ہے۔ پوشیدہ نظر آنے کے لیے واپسی کو چھوڑنا حقیقی طور پر خطرناک اقدام ہے، خود نقصان نہیں۔</p>\n</div></div>\n<h2 id=\"busting-the-myth-for-good\">پران کی پردہ پوشی، اچھے کے لیے</h2>\n<p>آئیے وکرم کو ٹھوس زمین پر لوٹائیں۔ اس کے تین قدم چلو۔ مرحلہ 1، اس کا کاروبار تقریباً 40 لاکھ روپے ہے۔ مرحلہ 2، اس کی تمام رقم ڈیجیٹل ہے، اس لیے اس کی حد 10 کروڑ روپے ہے، اور 40 لاکھ روپے اس سے بہت نیچے ہیں۔ مرحلہ 3، وہ ایک CA کے ساتھ مفروضہ ٹیکس کے اصولوں کو چیک کرتا ہے، اسے کوئی ایسی چیز نہیں ملتی جو اسے کھینچتی ہے، اور یہ نتیجہ اخذ کرتا ہے کہ اسے کسی آڈٹ کی ضرورت نہیں ہے۔ اس کے 2 لاکھ روپے کے نقصان کا اس کے دوست نے کبھی تصور بھی نہیں کیا تھا۔</p>\n<p>تو وکرم کو اصل میں کیا کرنا چاہئے؟ اسے وقت پر اپنا ریٹرن فائل کرنا چاہیے اور 2 لاکھ روپے کے نقصان کی ایمانداری سے رپورٹ کرنی چاہیے۔ نقصان کو درج کرنا ناکامی کا اعتراف نہیں ہے۔ یہ ایک فائدہ ہے. غیر قیاس آرائی پر مبنی F&amp;O نقصان کو آگے بڑھایا جا سکتا ہے اور مستقبل کی آمدنی کے خلاف طے کیا جا سکتا ہے، لیکن صرف اس صورت میں جب مقررہ تاریخ تک واپسی جمع کرائی جائے۔ جس چیز سے اس کے دوست نے اسے ڈرنے کو کہا وہی چیز اس کی حفاظت کرتی ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>افسانہ</th>\n<th>حقیقت</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>نقصان کا مطلب ہے خودکار آڈٹ</td>\n<td>اکیلا نقصان کبھی بھی آڈٹ کو متحرک نہیں کرتا ہے۔</td>\n</tr>\n<tr>\n<td>استثنیٰ پر آمدنی کا مطلب آڈٹ ہے۔</td>\n<td>یہ اکیلے بھی آڈٹ کو متحرک نہیں کرتا ہے۔</td>\n</tr>\n<tr>\n<td>توجہ سے بچنے کے لیے فائل کرنا چھوڑ دیں۔</td>\n<td>نقصان کو درج کرنے سے آپ کی حفاظت ہوتی ہے اور کیری فارورڈ کی بچت ہوتی ہے۔</td>\n</tr>\n<tr>\n<td>آڈٹ کا فیصلہ نفع یا نقصان سے ہوتا ہے۔</td>\n<td>آڈٹ کا فیصلہ صحیح حد کے خلاف ٹرن اوور کے ذریعے کیا جاتا ہے۔</td>\n</tr>\n</tbody></table>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>تین مراحل کو ہر سال ترتیب سے چلائیں: اپنا ٹرن اوور تلاش کریں، اسے صحیح حد سے مماثل کریں، پھر اپنے CA کے ساتھ مفروضہ ٹیکس کے اصولوں کو چیک کریں۔ اگر آپ کا ٹرن اوور آپ کی حد سے بہت نیچے ہے اور کوئی خاص چیز لاگو نہیں ہوتی ہے، تو آپ آڈٹ کے علاقے میں نہیں ہیں، جیتیں یا ہاریں۔</p>\n</div></div>\n<p>وکرم ایک افسانے پر بری طرح سو گیا۔ تین قدمی چیک کے ساتھ چند منٹ اس کی پریشانی سے بچ جاتے اور سب سے اہم بات یہ کہ اسے میز پر موجود ایک حقیقی غلطی سے بچایا جاتا، جو بالکل فائل نہیں کر رہی تھی۔ اپنے ٹرن اوور کو جانیں، اپنی حد کو جانیں، خاص اصولوں کو چیک کریں، اور حقائق کو جانے دیں، نہ کہ جم لاکر افواہوں کو، فیصلہ کریں کہ آیا آپ کو آڈٹ کی ضرورت ہے۔</p>\n<p>یہ باب صرف سیکھنے کے لیے ہے اور ٹیکس کا مشورہ نہیں ہے۔ آڈٹ کی حد اور فرضی ٹیکس کے اصول تبدیل ہو سکتے ہیں اور آپ کی صحیح صورت حال پر منحصر ہو سکتے ہیں، لہذا فیصلہ کرنے اور فائل کرنے سے پہلے براہ کرم کسی قابل چارٹرڈ اکاؤنٹنٹ سے تصدیق کر لیں۔</p>\n","toc":[{"level":2,"text":"تین قدمی چیک","id":"the-three-step-check"},{"level":2,"text":"مرحلہ 1، اپنا کاروبار تلاش کریں۔","id":"step-1-find-your-turnover"},{"level":2,"text":"مرحلہ 2، جس کی حد لاگو ہوتی ہے۔","id":"step-2-which-threshold-applies"},{"level":2,"text":"مرحلہ 3، حد سے نیچے لیکن ابھی تک ختم نہیں ہوا۔","id":"step-3-below-the-threshold-but-not-yet-finished"},{"level":2,"text":"پران کی پردہ پوشی، اچھے کے لیے","id":"busting-the-myth-for-good"}],"imgCount":1,"hasContent":true},"12":{"html":"<p>روی کے لیے فیوچر اور آپشنز مارکیٹ میں ایک مشکل سال رہا۔ پراعتماد آغاز کے بعد، تجارت کا ایک سلسلہ غلط طریقے سے چلا گیا اور اس نے سال کو تقریباً 5,00,000 روپے تک بند کردیا۔ اس کی پہلی جبلت تقریباً ہر تاجر کے پاس تھی۔ اسے بھول جائیں، سال گزر گیا، ٹیکس ریٹرن میں نقصان لکھ کر کچھ حاصل نہیں ہوتا۔ وہ جبلت بالکل پیچھے کی طرف ہے۔ ہندوستانی ٹیکس قانون میں تجارتی نقصان صرف ایک افسوسناک نمبر نہیں ہے جسے آپ دوبارہ نہیں دیکھیں گے۔ یہ ایک اثاثہ کے قریب کچھ ہے. صحیح طریقے سے ہینڈل کیا گیا، یہ اسی سال آپ کی دوسری آمدنی پر ٹیکس کم کر سکتا ہے، اور کوئی بھی بچا ہوا آپ کے لیے آنے والے سالوں تک کام کرتا رہ سکتا ہے۔ یہ باب آپ کو دکھاتا ہے کہ یہ کیسے کام کرتا ہے، سادہ مراحل میں اور روپے کے حقیقی اعداد و شمار کے ساتھ۔</p>\n<h2 id=\"what-set-off-actually-means\">\"سیٹ آف\" کا اصل مطلب کیا ہے۔</h2>\n<p>سیٹ آف ایک سادہ خیال ہے جسے رسمی لفظ میں لپیٹا جاتا ہے۔ اس کا مطلب ہے کہ ایک ذریعہ سے ہونے والے نقصان کو استعمال کرتے ہوئے دوسرے سے آمدنی کو منسوخ کرنا، تاکہ آپ صرف اس پر ٹیکس ادا کریں جو بچا ہے۔ اگر آپ نے ایک سرگرمی سے 2,00,000 روپے کمائے اور دوسری میں 80,000 روپے کھوئے، تو سیٹ آف آپ کو پورے 2,00,000 روپے کے بجائے 1,20,000 روپے کے خالص اعداد و شمار پر ٹیکس لگانے دیتا ہے۔</p>\n<p>آپ کی آمدنی کو ٹیکس قانون کے مطابق الگ الگ \"سروں\" میں ترتیب دیا گیا ہے۔ اہم ہیں تنخواہ، گھر کی جائیداد (آپ کے کرایے کی آمدنی)، کاروبار یا پیشہ، سرمائے سے حاصل ہونے والی آمدنی، اور دوسرے ذرائع سے حاصل ہونے والی آمدنی (جیسے بینک کا سود اور منافع)۔ F&amp;O ٹریڈنگ کاروبار یا پیشے کے تحت بیٹھتی ہے، کیونکہ F&amp;O کو غیر قیاس آرائی پر مبنی کاروباری آمدنی سمجھا جاتا ہے، نہ کہ کیپٹل گین کے طور پر۔ یہ درجہ بندی وہی ہے جو سیٹ آف قواعد کو فراخ بناتی ہے۔</p>\n<p>جیسا کہ چیزیں 2026-27AYکے لیے ہیں، موجودہ سال کے F&amp;O نقصان کو تقریباً ہر دوسرے سر کے تحت آمدنی کے مقابلے میں ختم کیا جا سکتا ہے۔ ایک اہم استثناء ہے، اور یہ یاد رکھنے کے قابل ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>موجودہ سال کا F&amp;O نقصان آپ کی زیادہ تر آمدنی کے خلاف ختم کیا جا سکتا ہے، ایک بڑی رعایت کے ساتھ: یہ کبھی بھی آپ کی تنخواہ کے خلاف نہیں ہو سکتا۔ کرایہ کی آمدنی، سود، منافع، سرمائے کے منافع اور دیگر کاروباری منافع سب منصفانہ کھیل ہیں۔</p>\n</div></div>\n\n<figure class=\"lesson-shot\">\n<img src=\"/taxation/images/diagram-fno-business-income.png\" alt=\"F&amp;O غیر قیاس آرائی پر مبنی کاروباری آمدنی ہے، یہی وجہ ہے کہ موجودہ سال کا F&amp;O نقصان زیادہ تر دیگر آمدنی کے سربراہوں تک پہنچ سکتا ہے اور آپ کے ٹیکس کو کم کر سکتا ہے، جبکہ تنخواہ خود ہی بند رہتی ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>F&amp;O غیر قیاس آرائی پر مبنی کاروباری آمدنی ہے، یہی وجہ ہے کہ موجودہ سال کا F&amp;O نقصان زیادہ تر دیگر آمدنی کے سربراہوں تک پہنچ سکتا ہے اور آپ کے ٹیکس کو کم کر سکتا ہے، جبکہ تنخواہ خود ہی بند رہتی ہے۔</figcaption></figure>\n<h2 id=\"the-one-income-a-loss-cannot-touch-salary\">ایک آمدنی جسے نقصان چھو نہیں سکتا: تنخواہ</h2>\n<p>یہاں آپ کے سر میں رکھنے کے لئے میز ہے. یہ ظاہر کرتا ہے کہ موجودہ سال کا غیر قیاس آرائی پر مبنی F&amp;O نقصان کہاں جا سکتا ہے اور کہاں نہیں جا سکتا۔</p>\n<table>\n<thead>\n<tr>\n<th>آمدنی کا سربراہ</th>\n<th>کیا موجودہ سال کا F&amp;O نقصان اس کے خلاف ہو سکتا ہے؟</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>تنخواہ</td>\n<td>نہیں</td>\n</tr>\n<tr>\n<td>گھر کی جائیداد (آپ کا کرایہ وصول ہوا)</td>\n<td>جی ہاں</td>\n</tr>\n<tr>\n<td>دوسرا کاروبار یا پیشہ</td>\n<td>جی ہاں</td>\n</tr>\n<tr>\n<td>سرمایہ نفع (قلیل مدتی یا طویل مدتی)</td>\n<td>جی ہاں</td>\n</tr>\n<tr>\n<td>دیگر ذرائع (سود، منافع)</td>\n<td>جی ہاں</td>\n</tr>\n</tbody></table>\n<p>تنخواہ کیوں بند ہے؟ قانون جان بوجھ کر تنخواہ کو الگ رکھتا ہے تاکہ کوئی بھی شخص تنخواہ پر ٹیکس ختم کرنے کے لیے خالصتاً مصنوعی تجارتی نقصان نہ بنا سکے۔ ایک تنخواہ دار شخص جو F&amp;O کی تجارت بھی کرتا ہے اس لیے اپنی تنخواہ سے پہلے سے کاٹے گئے ٹیکس کو کم کرنے کے لیے خراب تجارتی سال کا استعمال نہیں کر سکتا۔ تنخواہ اپنے طور پر کھڑی ہے اور اس پر مکمل ٹیکس لگایا جاتا ہے۔ اوپر کی فہرست میں باقی سب کچھ، اگرچہ، سیٹ آف کے لیے کھلا ہے۔</p>\n<p>یہ زیادہ تر تاجروں کے لیے حقیقی طور پر اچھی خبر ہے۔ اگر آپ کرایہ بھی کماتے ہیں، یا آپ کے پاس فکسڈ ڈپازٹ ہے جو سود ادا کرتا ہے، یا آپ نے اس سال حصص پر کچھ کیپٹل گین بک کیا ہے، تو موجودہ سال کا F&amp;O نقصان خاموشی سے ان سب پر ٹیکس کو کم کر سکتا ہے۔</p>\n<h2 id=\"a-worked-set-off-example\">ایک کام شدہ سیٹ آف مثال</h2>\n<p>آئیے راوی کا پورا سال میز پر رکھیں۔ اپنے F&amp;O کے 5,00,000 روپے کے نقصان کے ساتھ، اس نے تنخواہ بھی حاصل کی، ایک چھوٹے سے فلیٹ سے کرایہ جمع کیا، اور اپنے فکسڈ ڈپازٹ پر سود حاصل کیا۔</p>\n<table>\n<thead>\n<tr>\n<th>روی نے اس سال کیا کمایا یا کھویا</th>\n<th>رقم</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>تنخواہ</td>\n<td>8,00,000 روپے</td>\n</tr>\n<tr>\n<td>کرایہ کی آمدنی (گھر کی جائیداد)</td>\n<td>2,00,000 روپے</td>\n</tr>\n<tr>\n<td>فکسڈ ڈپازٹ سود (دیگر ذرائع)</td>\n<td>1,00,000 روپے</td>\n</tr>\n<tr>\n<td>F&amp;O نقصان (کاروبار)</td>\n<td>مائنس 5,00,000 روپے</td>\n</tr>\n</tbody></table>\n<p>اب اصول لاگو کریں۔ راوی کا F&amp;O کا 5,00,000 روپے کا نقصان اس کی 8,00,000 روپے کی تنخواہ کو نہیں چھو سکتا، لہذا یہ مکمل طور پر قابل ٹیکس رہے گا۔ لیکن نقصان اس کے کرایہ اور اس کی دلچسپی کے خلاف ہو سکتا ہے۔ 2,00,000 روپے کا کرایہ اور 1,00,000 روپے کا سود 3,00,000 روپے کی آمدنی پر آتا ہے جسے نقصان کو منسوخ کرنے کی اجازت ہے۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>راوی کا F&amp;O نقصان 5,00,000 روپے ہے۔ وہ کرایہ کے بدلے 2,00,000 روپے اور سود کے مد میں 1,00,000 روپے مقرر کرتا ہے، جو کہ نقصان کے 3,00,000 روپے استعمال کرتا ہے۔ سال کے لیے اس کا کرایہ اور سود کی آمدنی اب صفر ہو گئی ہے۔ جو نقصان باقی ہے وہ 5,00,000 روپے مائنس 3,00,000 روپے ہے جو کہ 2,00,000 روپے کے برابر ہے۔ اس کی 8,00,000 روپے کی تنخواہ مکمل طور پر قابل ٹیکس رہتی ہے، جو نقصان سے اچھوت نہیں ہے۔</p>\n</div></div>\n<p>چنانچہ ایک ہی جھٹکے میں، راوی نے کرایہ اور سود کے 3,00,000 روپے پر ٹیکس ختم کر دیا۔ یہ اس سال کی حقیقی رقم ہے۔ اور اس کی جیب میں اب بھی غیر استعمال شدہ نقصان کے 2,00,000 روپے پڑے ہیں۔ اگلا حصہ اس بارے میں ہے کہ اس بچ جانے والے کا کیا ہوتا ہے، اور یہ وہ جگہ ہے جہاں ایک چھوٹی سی غلطی پورے فائدے کو دور کر سکتی ہے۔</p>\n<h2 id=\"carry-forward-eight-years-but-only-if-you-file-on-time\">آگے بڑھائیں: آٹھ سال، لیکن صرف اس صورت میں جب آپ وقت پر فائل کریں۔</h2>\n<p>جب کوئی نقصان اس آمدنی سے بڑا ہو جسے آپ اس سال کے مقابلے میں ختم کر سکتے ہیں، تو غیر استعمال شدہ حصہ ضائع نہیں ہوتا ہے۔ اسے مستقبل کے سالوں تک لے جایا جاتا ہے۔ ایک غیر قیاس آرائی پر مبنی کاروباری نقصان، جو کہ F&amp;O ہے، کو آٹھ تشخیصی سالوں تک آگے بڑھایا جا سکتا ہے۔ لہٰذا راوی کا بچا ہوا 2,00,000 روپے آگے کا سفر کر سکتا ہے اور آئندہ سال میں اپنے ٹیکس کو کم کر سکتا ہے جب اس کی تجارت دوبارہ منافع بخش ہو گی۔</p>\n<p>لیکن ایک ایسی حالت ہے جو ہر سال لوگوں کو پکڑتی ہے، اور یہ ناقابل معافی ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>اگر آپ سیکشن 139(1) کے تحت اصل مقررہ تاریخ تک وقت پر اپنا انکم ٹیکس ریٹرن فائل کرتے ہیں تو آپ کو نقصان کو آگے بڑھانا ہوگا۔ فائل ایک دن بھی لیٹ ہو گئی اور کیری فارورڈ ختم ہو گیا۔ نقصان صرف مستقبل کے استعمال کے لیے غائب ہو جاتا ہے۔ وقت پر فائل کرنا واحد سب سے سستا انشورنس ہے جو تاجر خرید سکتا ہے۔</p>\n</div></div>\n<p>غور کریں کہ یہ ریاضی کو کیسے بدلتا ہے۔ اگر روی وقت پر فائل کرتا ہے، تو اس کا 2,00,000 روپے کا نقصان آٹھ سال تک صبر سے انتظار کرتا ہے اور بعد میں اسے ٹیکس بچا سکتا ہے۔ اگر روی دیر سے فائل کرتا ہے تو وہی 2,00,000 روپے ہمیشہ کے لیے ضبط ہو جاتے ہیں۔ ایک ہی تاجر، ایک ہی نقصان، دو مکمل طور پر مختلف نتائج، فائلنگ کی تاریخ کے علاوہ کچھ بھی نہیں۔ اس کے کرایہ اور سود کے خلاف موجودہ سال کے سیٹ آف کو دیر سے واپسی کے باوجود بھی اجازت ہے، لیکن آئندہ سال کا فائدہ وہ حصہ ہے جو آپ دیر سے فائل کرنے سے کھو دیتے ہیں۔</p>\n<h2 id=\"what-a-carried-forward-loss-can-do-next-year\">آگے بڑھنے والا نقصان اگلے سال کیا کر سکتا ہے۔</h2>\n<p>ایک اور موڑ ہے، اور یہ لوگوں کو حیران کر دیتا ہے۔ موجودہ سال کا اصول سخاوت مند ہے: اس سال، F&amp;O کا نقصان کرایہ، سود، کیپٹل گین اور دیگر کاروباری آمدنی تک پہنچ سکتا ہے۔ لیکن ایک بار جب کسی کاروباری نقصان کو بعد کے سال میں آگے بڑھایا جاتا ہے، تو یہ کم ہو جاتا ہے۔ آگے بڑھنے والے کاروباری نقصان کو صرف ان مستقبل کے سالوں میں کاروباری آمدنی کے مقابلے میں ختم کیا جا سکتا ہے۔</p>\n<p>اس لیے اگلے سال، راوی کے کیری فارورڈ 2,00,000 روپے اس کے کرایہ یا اس کے مفاد کے خلاف استعمال نہیں کیے جا سکتے۔ یہ صرف کسی کاروبار سے منافع کو کم کر سکتا ہے، قدرتی طور پر اس کا F&amp;O ٹریڈنگ خود ہی اگر اس کے پاس اچھا سال ہو۔ یہاں ایک جگہ تضاد ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>جب نقصان استعمال ہوتا ہے۔</th>\n<th>اس کے خلاف کیا کیا جا سکتا ہے</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>موجودہ سال میں (نقصان کا سال)</td>\n<td>زیادہ تر سر، بشمول کرایہ، سود، منافع اور کیپٹل گین، لیکن کبھی تنخواہ نہیں۔</td>\n</tr>\n<tr>\n<td>آئندہ سال میں (آگے لے جایا گیا)</td>\n<td>صرف کاروباری آمدنی، جیسے مستقبل کا F&amp;O یا دیگر کاروباری منافع</td>\n</tr>\n</tbody></table>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>منطق سمجھنے کے قابل ہے۔ جس سال آپ نقصان کرتے ہیں، قانون اسے وسیع پیمانے پر پھیلانے دیتا ہے۔ ایک بار جب اسے آگے بڑھایا جاتا ہے، تو اسے صرف کاروباری آمدنی کے لیے \"مختص\" کیا جاتا ہے۔ اس لیے کیری فارورڈ F&amp;O نقصان کے لیے بہترین گھر مستقبل کا منافع بخش تجارتی سال ہے۔</p>\n</div></div>\n<p>فرض کریں کہ اگلے سال راوی چیزوں کو بدل دیتا ہے اور 3,00,000 روپے کا F&amp;O منافع کماتا ہے۔ وہ سب سے پہلے اس کے مقابلے میں 2,00,000 روپے کے اپنے کیری فارورڈ نقصان کا تعین کرتا ہے۔ منافع کے صرف بقیہ 1,00,000 روپے پر ٹیکس ہے۔ یہ ہے آگے بڑھنے والا اسے واپس ادا کر رہا ہے، اس تکلیف دہ نقصان کے دو سال بعد جس نے اسے پیدا کیا۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>دو عادتیں اس فائدے کی مکمل حفاظت کرتی ہیں۔ سب سے پہلے، ہر سال مقررہ تاریخ تک اپنی ریٹرن فائل کریں، یہاں تک کہ نقصان کے سال میں بھی، کیونکہ یہی چیز کیری فارورڈ کو زندہ رکھتی ہے۔ دوسرا، اپنے بروکر کے ٹیکس منافع اور نقصان کا بیان اور اپنی ٹرن اوور رپورٹ کو محفوظ رکھیں، کیونکہ یہ اس نقصان کا ثبوت ہے جسے آپ آگے لے جا رہے ہیں۔</p>\n</div></div>\n<h2 id=\"the-takeaway-for-a-bad-year\">ایک برے سال کے لیے ٹیک وے</h2>\n<p>ایک ہارا ہوا F&amp;O سال خالص درد کی طرح محسوس ہوتا ہے، لیکن ٹیکس کا نظام خاموشی سے آپ کو دو تسلی دیتا ہے۔ اس سال، نقصان آپ کی زیادہ تر دیگر آمدنی پر ٹیکس کو کم کر سکتا ہے، تنخواہ کے ساتھ وہ واحد چیز جو اسے چھو نہیں سکتی۔ اور جو کچھ بھی بچا ہے اسے آٹھ سال تک آگے بڑھایا جا سکتا ہے تاکہ مستقبل کے منافع بخش سال کو آگے بڑھایا جا سکے، جب تک کہ آپ وقت پر فائل کریں۔ راوی کے 5,00,000 روپے کے نقصان نے حقیقی کام کیا: اس نے اب کرایہ اور سود کے 3,00,000 روپے پر ٹیکس مٹا دیا، اور ایک بہتر سال کو نرم کرنے کے لیے 2,00,000 روپے رکھے۔ اس سب کو رکھنے کے لیے اسے ایک کام کرنا تھا جو سب سے بنیادی چیز تھی، وہ تھی اپنی ریٹرن فائل کرنا، اور وقت پر فائل کرنا۔</p>\n<p>یہ باب صرف سیکھنے کے لیے ہے اور ذاتی ٹیکس مشورہ نہیں ہے۔ ٹیکس کے قوانین اور شرحیں سال بہ سال بدلتی رہتی ہیں، اس لیے فائل کرنے سے پہلے براہ کرم ایک اہل چارٹرڈ اکاؤنٹنٹ سے اپنی سیٹ آف اور کیری فارورڈ پوزیشن کی تصدیق کریں۔</p>\n","toc":[{"level":2,"text":"\"سیٹ آف\" کا اصل مطلب کیا ہے۔","id":"what-set-off-actually-means"},{"level":2,"text":"ایک آمدنی جسے نقصان چھو نہیں سکتا: تنخواہ","id":"the-one-income-a-loss-cannot-touch-salary"},{"level":2,"text":"ایک کام شدہ سیٹ آف مثال","id":"a-worked-set-off-example"},{"level":2,"text":"آگے بڑھائیں: آٹھ سال، لیکن صرف اس صورت میں جب آپ وقت پر فائل کریں۔","id":"carry-forward-eight-years-but-only-if-you-file-on-time"},{"level":2,"text":"آگے بڑھنے والا نقصان اگلے سال کیا کر سکتا ہے۔","id":"what-a-carried-forward-loss-can-do-next-year"},{"level":2,"text":"ایک برے سال کے لیے ٹیک وے","id":"the-takeaway-for-a-bad-year"}],"imgCount":1,"hasContent":true},"13":{"html":"<p>ایک ایسی کہانی ہے جسے ہندوستان میں ہر F&amp;O تاجر کو ایک بار آہستہ آہستہ سننا چاہیے، کیونکہ یہ ٹیکس ریٹرن کے بارے میں آپ کے سوچنے کے انداز کو ہمیشہ کے لیے بدل دیتا ہے۔ اس میں کرناٹک کا ایک کسان شامل ہے، ایک ایسا نقصان جس کا اسے یقین تھا کہ کوئی فرق نہیں پڑے گا، اور ٹیکس کی مانگ اتنی زیادہ ہے کہ یہ ٹائپنگ کی غلطی کی طرح پڑھتا ہے۔ کسان نے کچھ بھی ڈرامائی نہیں کیا۔ اس نے صرف یہ فرض کیا کہ چونکہ اس نے پیسے کی کوئی تجارت نہیں کی تھی، اس لیے رپورٹ کرنے کے لیے کچھ نہیں تھا۔ یہ ایک خاموش مفروضہ اس پورے کورس میں سب سے مہنگی غلطی ہے۔ آئیے اس پر چلتے ہیں کہ کیا ہوا، ٹیکس ڈیپارٹمنٹ نے اس کی تجارت کیوں دیکھی حالانکہ وہ خاموش تھا، اور اس سے کہیں زیادہ چھوٹے، پرسکون قدم جو اسے مکمل طور پر محفوظ رکھتے تھے۔</p>\n<h2 id=\"the-karnataka-farmer-a-loss-that-became-a-demand\">کرناٹک کا کسان: ایک ایسا نقصان جو مطالبہ بن گیا۔</h2>\n<p>2014 کے آس پاس، کرناٹک میں ایک کسان نے مستقبل اور اختیارات کی تجارت شروع کی۔ بہت سے ابتدائیوں کی طرح، یہ ٹھیک نہیں ہوا۔ آخر تک وہ تقریباً 26 لاکھ روپے کم تھا۔ اس نے اس نقصان کو دیکھا، فیصلہ کیا کہ کوئی منافع نہیں ہے اور اس لیے ٹیکس ڈیپارٹمنٹ کو بتانے کے لیے کچھ نہیں، اور اس کے لیے ریٹرن فائل نہیں کیا۔ اس کے نزدیک یہ سادہ سی عقل کی طرح محسوس ہوا۔ آپ آمدنی کی اطلاع دیتے ہیں، اور اس کے پاس کوئی نہیں تھا، لہذا معاملہ بند کر دیا گیا تھا.</p>\n<p>اسے بند نہیں کیا گیا تھا۔ 2021 میں، اس کے آگے بڑھنے کے برسوں بعد، محکمہ انکم ٹیکس نے اس کا کیس دوبارہ کھولا۔ جب انہوں نے اس کے PAN سے منسلک تجارتی سرگرمی کو کھینچا، تو اعداد و شمار حیران کن تھے۔ اس کا F&amp;O کاروبار، ان تمام تجارتوں میں مجموعی طور پر تقریباً 69 کروڑ روپے تک پہنچ گیا۔ ٹرن اوور کے باب سے یاد رکھیں کہ F&amp;O ٹرن اوور ہر ٹریڈ پر فرق کا مجموعہ ہے، کنٹریکٹ ویلیوز کا نہیں، لیکن فعال ٹریڈنگ کے ساتھ ایک کھونے والا اکاؤنٹ بھی ٹرن اوور کا بہت بڑا ڈیٹا حاصل کر سکتا ہے۔</p>\n<p>یہ وہ جگہ ہے جہاں خاموشی تباہی میں بدل گئی۔ ایک نوٹس جاری کیا گیا، اور یہ چھوٹ گیا۔ چونکہ کسان نے یہ وضاحت کرنے کے لیے کبھی جواب نہیں دیا کہ یہ ٹرن اوور خسارے میں جانے والی تجارتی کتاب ہے، اس لیے محکمہ اس کے حق میں تھا کہ وہ پورے کاروبار کو اس طرح سمجھے جیسے یہ آمدنی ہو۔ اس کا نتیجہ ٹیکس، جرمانے اور سود پر مشتمل تقریباً 68 کروڑ روپے کا مطالبہ تھا جو کہ پہلے نمبر پر کبھی حقیقی منافع نہیں تھا۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>کسان کا اصل نقصان تقریباً 26 لاکھ روپے تھا۔ ان کے خلاف 68 کروڑ روپے کا مطالبہ کیا گیا تھا۔ ان دو نمبروں کے درمیان فرق اس باب کا پورا سبق ہے۔ اس کی تجارت کے بارے میں کچھ بھی اس فرق کی وجہ سے نہیں تھا۔ اس کی خاموشی نے کام کیا۔</p>\n</div></div>\n\n<figure class=\"lesson-shot\">\n<img src=\"/taxation/images/diagram-not-reporting.png\" alt=\"کرناٹک کے کسان نے 26 لاکھ روپے کے نقصان کو نظر انداز کر دیا، 2021 میں 69 کروڑ روپے کا کاروبار سامنے آیا، ایک نوٹس کا جواب نہیں دیا گیا، اور غیر رپورٹ شدہ کاروبار کو آمدنی کے طور پر سمجھا گیا، جس سے تقریباً 68 کروڑ روپے کی مانگ پیدا ہوئی۔ نقصان کی اطلاع دینے سے پہلے قدم پر سلسلہ رک جاتا۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>کرناٹک کے کسان نے 26 لاکھ روپے کے نقصان کو نظر انداز کر دیا، 2021 میں 69 کروڑ روپے کا کاروبار سامنے آیا، ایک نوٹس کا جواب نہیں دیا گیا، اور غیر رپورٹ شدہ کاروبار کو آمدنی کے طور پر سمجھا گیا، جس سے تقریباً 68 کروڑ روپے کی مانگ پیدا ہوئی۔ نقصان کی اطلاع دینے سے پہلے قدم پر سلسلہ رک جاتا۔</figcaption></figure>\n<h2 id=\"how-the-department-already-sees-your-trades\">محکمہ آپ کی تجارت کو کیسے دیکھتا ہے۔</h2>\n<p>فطری سوال یہ ہے کہ انہیں کیسے پتہ چلا؟ کسان نے انہیں کبھی کچھ نہیں بتایا۔ جواب یہ ہے کہ آپ کو انہیں بتانے کی ضرورت نہیں ہے۔ جب تک آپ ایک ہی F&amp;O تجارت کرتے ہیں، دو سسٹم پہلے ہی اسے آپ کے PAN کے خلاف ریکارڈ کر چکے ہیں۔</p>\n<p>پہلا ہے STT، سیکیورٹیز ٹرانزیکشن ٹیکس۔ ہر فیوچر سیل اور ہر آپشن سیل میں STT ہوتا ہے، جو آپ کے بروکر اور ایکسچینج کے ذریعے خود بخود جمع ہوتا ہے اور آپ کی شناخت سے منسلک ہوتا ہے۔ حکومت دیکھ سکتی ہے، تجارت بہ تجارت، وہ سرگرمی آپ کے نام پر ہو رہی ہے۔</p>\n<p>دوسرا سالانہ معلوماتی بیان، AIS ہے۔ یہ ایک سالانہ خلاصہ ہے جو محکمہ ہر ٹیکس دہندہ کے لیے مرتب کرتا ہے، جس میں آپ کی تجارت، سود، منافع، بڑے لین دین اور بہت کچھ شامل ہوتا ہے، یہ سب کچھ آپ کے PAN پر ہوتا ہے۔ جب آپ فائل میں لاگ ان ہوتے ہیں، تو آپ کی مالی زندگی کا زیادہ تر حصہ پہلے ہی AIS میں محکمہ کے سامنے رکھا جاتا ہے۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>STT اور AIS کو ایک خاموش لیجر کے طور پر سوچیں جو محکمہ آپ پر رکھتا ہے۔ جب آپ اپنا ریٹرن فائل کرتے ہیں، تو سسٹم صرف یہ چیک کرتا ہے کہ آیا آپ نے جو اطلاع دی ہے اس سے میل کھاتا ہے جو اسے پہلے سے معلوم ہے۔ ایک تاجر جو کچھ بھی رپورٹ نہیں کرتا، جبکہ AIS بھاری F&amp;O ٹرن اوور دکھاتا ہے، ایک واضح مماثلت پیدا کرتا ہے۔</p>\n</div></div>\n<p>یہ مماثلت ہی پریشانی کو جنم دیتی ہے۔ ایسی واپسی جو AIS سے مماثل نہیں ہے، نوٹس کو متوجہ کر سکتی ہے، بشمول سیکشن 139(9) کے تحت ایک عیب دار واپسی کا نوٹس۔ کسان کا معاملہ اسی مکینک کا انتہائی ورژن تھا۔ ڈیٹا ہمیشہ موجود تھا۔ واحد متغیر یہ تھا کہ آیا وہ اس کے ساتھ مشغول ہے۔</p>\n<h2 id=\"the-penalty-list-in-plain-numbers\">جرمانے کی فہرست، سادہ نمبروں میں</h2>\n<p>جب آپ F&amp;O کو درست طریقے سے رپورٹ نہیں کرتے ہیں، تو اخراجات مبہم نہیں ہوتے ہیں۔ وہ مخصوص مقدار کے ساتھ قانون کے مخصوص حصے ہیں۔ یہاں وہ ایک جگہ، سادہ زبان میں ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>کیا غلط ہوا</th>\n<th>جرمانہ</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>انڈر رپورٹنگ یا آمدنی چھپانا (سیکشن 270A)</td>\n<td>کم اطلاع شدہ رقم پر 50% سے 200% ٹیکس</td>\n</tr>\n<tr>\n<td>اکاؤنٹس کی کتابوں کو برقرار نہ رکھنا (سیکشن 271 اے)</td>\n<td>25,000 روپے</td>\n</tr>\n<tr>\n<td>مطلوبہ ٹیکس آڈٹ نہ کروانا (سیکشن 271B)</td>\n<td>1,50,000 روپے سے کم یا ٹرن اوور کا 0.5%</td>\n</tr>\n<tr>\n<td>ریٹرن دیر سے فائل کرنا (سیکشن 234 ایف)</td>\n<td>5,000 روپے، اگر کل آمدنی 5 لاکھ روپے تک ہے تو اسے کم کر کے 1,000 روپے کر دیا گیا</td>\n</tr>\n<tr>\n<td>تاخیر سے فائل کرنا، الگ لاگت</td>\n<td>آپ اپنے نقصانات کے کیری فارورڈ کو ضائع کر دیتے ہیں۔</td>\n</tr>\n</tbody></table>\n<p>اس پہلی قطار کو دوبارہ پڑھیں، کیونکہ کرناٹک میں اسی نے نقصان پہنچایا ہے۔ انڈر رپورٹنگ کا جرمانہ نصف ٹیکس سے لے کر ٹیکس کے دو گنا تک ہوسکتا ہے۔ جب محکمہ پورے 69 کروڑ روپے کے ٹرن اوور کو آمدنی کے طور پر دیکھتا ہے، تو اس خیالی آمدنی پر ٹیکس پہلے ہی بہت زیادہ ہے، اور پھر سب سے اوپر دوگنا تک کا جرمانہ، اور درمیان میں ہر سال سود جمع ہوتا ہے۔ اس طرح 26 لاکھ روپے کا نقصان ریاضیاتی طور پر 68 کروڑ روپے کی مانگ میں بدل جاتا ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>صرف جرمانے ہی نقصان نہیں ہیں۔ سیکشن 234F تاخیر سے فائل کرنے کی فیس لیتا ہے، لیکن دیر سے فائل کرنے کی کم لاگت آپ کے F&amp;O نقصان کو آٹھ سال تک آگے لے جانے کا حق کھو رہی ہے۔ ڈیڈ لائن سے محروم رہیں اور حقیقی طور پر مفید 5,00,000 روپے کا نقصان آپ کے مستقبل کے ریٹرن سے غائب ہو جائے گا۔</p>\n</div></div>\n<h2 id=\"a-worked-example-the-cost-of-staying-quiet\">ایک کام کی مثال: خاموش رہنے کی قیمت</h2>\n<p>آئیے ہم کسان کی تباہی کو عام پیمانے پر کم کر دیں تاکہ ریاضی واضح ہو۔ انجلی سے ملو، ایک تنخواہ دار پیشہ ور جس نے F&amp;O کی طرف تجارت کی اور سال کا اختتام 3,00,000 روپے کے نقصان کے ساتھ کیا۔ کسان کی طرح، اس نے فیصلہ کیا کہ نقصان کی اطلاع دینے کا کوئی مطلب نہیں ہے۔</p>\n<p>اس کے AIS نے، تاہم، سال کے لیے 40,00,000 روپے کا F&amp;O ٹرن اوور دکھایا۔ اس کی خاموش واپسی اور اس ٹرن اوور کے درمیان مماثلت نے ایک نوٹس کھینچ لیا۔ اب اس کے سامنے والے دونوں راستوں کا موازنہ کریں۔</p>\n<table>\n<thead>\n<tr>\n<th>اگر انجلی نے سادگی سے اطلاع دی تھی۔</th>\n<th>اگر انجلی خاموش رہی</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>فائلز ITR-3 3,00,000 روپے کا نقصان دکھا رہی ہیں۔</td>\n<td>AIS کی مماثلت پر نوٹس موصول ہوتا ہے۔</td>\n</tr>\n<tr>\n<td>ٹریڈنگ پر ٹیکس: صفر، یہ ایک نقصان تھا۔</td>\n<td>خطرہ کہ ٹرن اوور کو آمدنی سمجھا جاتا ہے۔</td>\n</tr>\n<tr>\n<td>3,00,000 روپے کا کیری فارورڈ 8 سال کے لیے محفوظ ہے۔</td>\n<td>کیری فارورڈ کھو گیا نقصان ہمیشہ کے لیے چلا گیا</td>\n</tr>\n<tr>\n<td>234F کے تحت لیٹ فیس: کوئی نہیں۔</td>\n<td>ممکنہ 234F فیس کے علاوہ 270A جرمانہ 50% سے 200% ٹیکس کے علاوہ سود</td>\n</tr>\n</tbody></table>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>فرض کریں، خاموش راستے پر، محکمہ انجلی کے ٹرن اوور کے صرف 5,00,000 روپے کو غیر واضح آمدنی سمجھتا ہے۔ 20 فیصد سلیب پر ٹیکس 1,00,000 روپے ہوگا۔ 50% کے نچلے سرے پر سیکشن 270A جرمانہ مزید 50,000 روپے کا اضافہ کرتا ہے، لہذا 1,00,000 روپے جمع 50,000 روپے کسی بھی سود سے پہلے 1,50,000 روپے کے برابر ہیں۔ رپورٹنگ پاتھ پر، اسی ٹریڈنگ پر اس کا ٹیکس صفر تھا، کیونکہ یہ نقصان تھا، اور اس نے بونس کے طور پر 3,00,000 روپے کیری فارورڈ رکھے تھے۔ وہی تاجر، وہی نقصان، لاکھوں کا فرق۔</p>\n</div></div>\n<h2 id=\"how-to-stay-completely-safe\">مکمل طور پر محفوظ رہنے کا طریقہ</h2>\n<p>یقین دہانی کرنے والا حصہ یہ ہے کہ ٹھیک کرنا تقریباً توہین آمیز حد تک آسان ہے۔ کوئی ہوشیار ڈھانچہ نہیں ہے، کوئی جارحانہ منصوبہ بندی نہیں ہے، کوئی مہنگی چال نہیں ہے۔ آپ صرف رپورٹ کریں۔</p>\n<p>ہر سال اپنے F&amp;O کی رپورٹ کریں، چاہے یہ منافع ہو یا نقصان۔ ITR-3، ٹریڈرز کے لیے فارم کا استعمال کریں، اور اپنے بروکر کے ٹیکس منافع اور نقصان اور ٹرن اوور رپورٹ کے اعداد و شمار درج کریں۔ اگر یہ منافع بخش سال تھا، تو آپ واجب الادا ٹیکس ادا کرتے ہیں۔ اگر یہ نقصان تھا، تو آپ نقصان کی اطلاع دیتے ہیں، جس سے آپ کو ٹیکس کی مد میں کوئی قیمت نہیں لگتی اور آپ کو فعال طور پر مدد ملتی ہے، کیونکہ نقصان کی اطلاع دینا بالکل وہی ہے جو آپ کو اسے آگے بڑھانے اور اسے مستقبل کی آمدنی کے مقابلے میں ختم کرنے دیتا ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>نقصان کی اطلاع دینا ٹیکس ڈیپارٹمنٹ کی ناکامی کا اعتراف نہیں ہے۔ یہ وہ چیز ہے جو آپ کی حفاظت کرتی ہے۔ کسان کا نقصان، صحیح طریقے سے درج کیا جاتا، 26 لاکھ روپے کا اثاثہ ہوتا، نہ کہ 68 کروڑ روپے کی ذمہ داری۔ وقت پر فائل کرنا ایک خراب سال کو مستقبل کے نوٹس کی بجائے مستقبل کی ٹیکس شیلڈ میں بدل دیتا ہے۔</p>\n</div></div>\n<p>تو پورا دفاع ایک مختصر روٹین پر اتر آتا ہے۔ اپنی بروکر رپورٹس کو کھینچیں، انہیں اپنے AIS کے خلاف جوڑیں تاکہ کوئی مماثلت نہ ہو، مقررہ تاریخ تک ITR-3 فائل کریں، اور بغیر کسی استثناء کے ہر سال رپورٹ کریں، خاص طور پر کھونے والے۔ ایسا کریں، اور کرناٹک کے کسان کی خوفناک کہانی وہی رہتی ہے جو آپ کے لیے ہونی چاہیے، ایک ایسی کہانی جس سے آپ نے جینے کے بجائے سیکھا ہے۔</p>\n<p>یہ باب صرف تعلیم کے لیے ہے اور پیشہ ورانہ مشورے کا متبادل نہیں ہے۔ ٹیکس کے قوانین، جرمانے کی رقم اور سیکشن نمبرز تبدیل ہو سکتے ہیں، لہٰذا اپنا ریٹرن جمع کرانے سے پہلے اپنی فائلنگ پوزیشن کی تصدیق کرنے کے لیے کسی قابل چارٹرڈ اکاؤنٹنٹ کے ساتھ بیٹھیں۔</p>\n","toc":[{"level":2,"text":"کرناٹک کا کسان: ایک ایسا نقصان جو مطالبہ بن گیا۔","id":"the-karnataka-farmer-a-loss-that-became-a-demand"},{"level":2,"text":"محکمہ آپ کی تجارت کو کیسے دیکھتا ہے۔","id":"how-the-department-already-sees-your-trades"},{"level":2,"text":"جرمانے کی فہرست، سادہ نمبروں میں","id":"the-penalty-list-in-plain-numbers"},{"level":2,"text":"ایک کام کی مثال: خاموش رہنے کی قیمت","id":"a-worked-example-the-cost-of-staying-quiet"},{"level":2,"text":"مکمل طور پر محفوظ رہنے کا طریقہ","id":"how-to-stay-completely-safe"}],"imgCount":1,"hasContent":true},"14":{"html":"<p>کہیں پچھلے کچھ سالوں میں، ایک امریکی کمپنی کا ایک ٹکڑا خریدنا غیر ملکی محسوس کرنا بند کر دیا. بنگلورو یا پونے میں اپنے فون سے آپ دوپہر کے کھانے سے پہلے US ٹیکنالوجی کے بڑے حصص کے مالک بن سکتے ہیں۔ سرمایہ کاری کا حصہ حیرت انگیز طور پر آسان ہو گیا ہے۔ ٹیکس کا حصہ وہ ہے جہاں لوگ جم جاتے ہیں، کیونکہ اب دو ممالک شامل ہیں اور لفظ \"ڈبل ٹیکسیشن\" خوفناک لگنے لگتا ہے۔ یہ پرسکون سچائی سامنے ہے۔ ہندوستان اور امریکہ کے درمیان خاص طور پر ایک معاہدہ ہے تاکہ آپ پر ایک ہی رقم پر دو بار ٹیکس نہ لگے۔ ایک بار جب آپ اس باب میں مٹھی بھر قواعد کو سمجھ لیں، تو آپ کے US پورٹ فولیو پر ٹیکس لگانا معمول بن جاتا ہے۔ آئیے ہم اسے ٹکڑے ٹکڑے کر لیں، روپے کے اعداد و شمار کے ساتھ۔</p>\n<h2 id=\"capital-gains-the-24-month-line\">کیپٹل گین: 24 ماہ کی لائن</h2>\n<p>جب آپ US اسٹاک کو اپنی ادائیگی سے زیادہ میں فروخت کرتے ہیں، تو منافع ایک کیپیٹل گین ہوتا ہے، اور اس پر کس طرح ٹیکس لگایا جاتا ہے اس کا انحصار اس بات پر ہوتا ہے کہ آپ نے اسے کتنی دیر تک رکھا ہے۔ غیر ملکی حصص کے لیے تقسیم کی لکیر 24 ماہ ہے، جو کہ 12 ماہ کی لائن سے لمبی ہے جسے آپ ہندوستانی درج کردہ حصص کے لیے جانتے ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>آپ نے کتنی دیر تک US اسٹاک رکھا</th>\n<th>نفع کی قسم</th>\n<th>ہندوستان میں اس پر کس طرح ٹیکس لگایا جاتا ہے۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>24 ماہ سے زیادہ</td>\n<td>طویل مدتی</td>\n<td>12.5%، علاوہ سیس</td>\n</tr>\n<tr>\n<td>24 ماہ یا اس سے کم</td>\n<td>قلیل مدتی</td>\n<td>آپ کے سلیب ریٹ پر</td>\n</tr>\n</tbody></table>\n<p>تو صبر کا اجر ملتا ہے۔ US اسٹاک کو دو سال سے زیادہ کے لیے رکھیں اور آپ کے نفع پر فلیٹ 12.5% ​​ٹیکس لگایا جاتا ہے۔ دو سال کے اندر بیچیں اور فائدہ آپ کی کل آمدنی میں اضافہ کرتا ہے اور آپ جس بھی سلیب میں آتے ہیں اس پر ٹیکس لگایا جاتا ہے، جو بہت سے سرمایہ کاروں کے لیے 12.5% ​​سے زیادہ ہے۔</p>\n<p>یقین دہانی کرنے والا حصہ وہ ہے جہاں یہ ٹیکس ادا کیا جاتا ہے۔ ہندوستان-امریکہ ٹیکس معاہدے کے تحت، جسے DTAA کے نام سے جانا جاتا ہے، US حصص پر کیپیٹل گین پر صرف ہندوستان میں ایک رہائشی ہندوستانی سرمایہ کار کے لیے ٹیکس لگایا جاتا ہے۔ ریاست ہائے متحدہ امریکہ یہاں آپ کے کیپیٹل گین پر ٹیکس نہیں لگاتا، اس لیے جب آپ فروخت کرتے ہیں تو منافع پر کوئی دوہرا ٹیکس نہیں ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ایک رہائشی ہندوستانی کے لیے، US حصص پر کیپیٹل گین پر صرف ہندوستان میں DTAA کے تحت ٹیکس لگایا جاتا ہے۔ 24 مہینوں سے زیادہ کے لیے منعقد کیا گیا، فائدہ طویل مدتی ہے اور اس پر 12.5% ​​ٹیکس لگایا گیا ہے۔ 24 ماہ یا اس سے کم کے لیے منعقد کیا جاتا ہے، یہ قلیل مدتی ہے اور آپ کے سلیب کی شرح پر ٹیکس لگایا جاتا ہے۔</p>\n</div></div>\n\n<figure class=\"lesson-shot\">\n<img src=\"/taxation/images/diagram-us-stocks.png\" alt=\"ایک ہندوستانی باشندے کے لیے US حصص پر ٹیکس لگانے کا نقشہ: صرف ہندوستان میں ٹیکس عائد کیپیٹل گین (24 ماہ سے زیادہ 12.5% طویل مدتی، سلیب اگر چھوٹا ہو)، 25% US ودہولڈنگ کے ساتھ ڈیویڈنڈس فارن ٹیکس کریڈٹ کے ذریعے وصول کیا گیا، شیڈول FA ہمیشہ LRSTCS7 لاکھ روپے سے اوپر۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>ایک ہندوستانی رہائشی کے لیے US حصص پر ٹیکس لگانے کا نقشہ: صرف ہندوستان میں ٹیکس عائد کیپٹل گین (24 ماہ سے زیادہ 12.5% طویل مدتی، سلیب اگر چھوٹا ہو)، غیر ملکی ٹیکس کریڈٹ کے ذریعے برآمد ہونے والے 25% US ودہولڈنگ کے ساتھ منافع، شیڈول FA ہمیشہ LRSTCS7 لاکھ روپے سے اوپر۔</figcaption></figure>\n<h2 id=\"a-worked-long-term-example\">ایک طویل مدتی کام کی مثال</h2>\n<p>نمبر اس کو ٹھوس بناتے ہیں۔ فرض کریں کہ آپ 8,00,000 روپے کے 8USحصص خریدتے ہیں اور انہیں صبر سے تھامے رکھتے ہیں۔ تیس مہینے بعد، آرام سے 24 ماہ کی لائن سے گزرتے ہوئے، آپ انہیں 11,00,000 روپے میں فروخت کرتے ہیں۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>خریداری کی قیمت: 8,00,000 روپے۔ 30 ماہ کے بعد فروخت کی قیمت: 11,00,000 روپے۔ آپ کا طویل مدتی سرمایہ نفع 11,00,000 روپے مائنس 8,00,000 روپے ہے، جو کہ 3,00,000 روپے کے برابر ہے۔ چونکہ آپ نے 24 ماہ سے زائد عرصے تک اپنے پاس رکھا، ٹیکس 3,00,000 روپے کا 12.5% ​​ہے، جو کہ 37,500 روپے کے برابر ہے، اس کے علاوہ اس ٹیکس پر 4% صحت اور تعلیم کا سیس ہے۔ امریکہ اس نفع پر ٹیکس نہیں لگاتا، لہٰذا 37,500 روپے جمع سیس پوری کہانی ہے۔</p>\n</div></div>\n<p>دیکھیں کہ یہ کتنا صاف ہے۔ ایک ہولڈنگ پیریڈ چیک، ایک ریٹ، ایک ملک۔ US کی سرمایہ کاری سے لوگ جن پیچیدگیوں سے ڈرتے ہیں وہ کیپیٹل گین میں نہیں بلکہ ڈیویڈنڈ میں رہتے ہیں، جہاں دو ٹیکس سسٹم حقیقی طور پر ملتے ہیں۔ یہ اگلا حصہ ہے۔</p>\n<h2 id=\"dividends-the-25-the-us-keeps-and-how-you-get-it-back\">منافع: 25% US رکھتا ہے، اور آپ اسے کیسے واپس حاصل کرتے ہیں</h2>\n<p>جب کوئی US کمپنی آپ کو ڈیویڈنڈ ادا کرتی ہے، تو رقم آپ تک پہنچنے سے پہلے ہی ریاستہائے متحدہ اپنی کٹوتی کر لیتا ہے۔ ایک ہندوستانی انفرادی سرمایہ کار کے لیے US منبع پر ڈیویڈنڈ کا 25% روک لیتا ہے، DTAA کے تحت دستیاب ایک کم شرح۔ لہٰذا آپ کے اکاؤنٹ میں 100 روپے کا ڈیویڈنڈ 75 روپے کے طور پر آتا ہے، جس میں 25 روپے پہلے ہی US ٹیکس حکام کو جا چکے ہیں۔</p>\n<p>پھر ہندوستان بھی اسی ڈیویڈنڈ پر ٹیکس لگاتا ہے۔ ہندوستان میں، آپ کی آمدنی میں ڈیویڈنڈ شامل کیا جاتا ہے اور آپ کے سلیب کی شرح پر ٹیکس لگایا جاتا ہے۔ پہلی نظر میں یہ بالکل دوہرے ٹیکس کی طرح لگتا ہے جس سے ہر کوئی خوفزدہ ہے۔ امریکہ اور ہندوستان میں ایک ہی 100 روپے ٹیکس لگایا جا رہا ہے۔</p>\n<p>یہ وہ جگہ ہے جہاں غیر ملکی ٹیکس کریڈٹ آپ کو بچاتا ہے۔ انڈیا آپ کو US میں پہلے سے ادا کیے گئے ٹیکس کے لیے کریڈٹ کا دعوی کرنے دیتا ہے، لہذا آپ سے ایک ہی ڈیویڈنڈ پر دو بار چارج نہیں کیا جاتا ہے۔ آپ اس ڈیویڈنڈ پر اپنے ہندوستانی ٹیکس سے US ٹیکس کو گھٹاتے ہیں اور صرف فرق ادا کرتے ہیں، اگر کوئی ہے۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>غیر ملکی ٹیکس کریڈٹ کا دعوی کرنے کے لیے آپ کو اپنا انکم ٹیکس ریٹرن فائل کرنے سے پہلے فارم 67 فائل کرنا ہوگا، اس کے ساتھ متعلقہ شیڈول TR اور ITR میں شیڈول FSI۔ فارم 67 وہ دستاویز ہے جو ہندوستانی ٹیکس نظام کو بتاتی ہے، \"میں نے پہلے ہی اتنا ٹیکس بیرون ملک ادا کیا ہے، براہ کرم مجھے اس کا کریڈٹ دیں۔\" فارم چھوٹ جائے گا اور آپ کریڈٹ کھو سکتے ہیں، لہذا یہ اختیاری کاغذی کارروائی نہیں ہے۔</p>\n</div></div>\n<p>آئیے دیکھتے ہیں کہ کریڈٹ کام کر رہا ہے۔ کہو کہ آپ کو 10,000 روپے کا US ڈیویڈنڈ ملا ہے۔ US نے 25% روک لیا، جو کہ 2,500 روپے ہے، لہذا آپ تک 7,500 روپے پہنچ گئے۔ ہندوستان میں پورے 10,000 روپے ٹیکس کے قابل ہیں۔ فرض کریں کہ آپ کا سلیب 20% ہے، جس سے ہندوستانی ٹیکس 2,000 روپے بنتا ہے۔ آپ کا 2,500 روپے کا 2,000 روپے کا ٹیکس اس ڈیویڈنڈ پر آپ کے 2,000 روپے کے ہندوستانی ٹیکس سے بڑا ہے، لہذا غیر ملکی ٹیکس کریڈٹ اس کا مکمل احاطہ کرتا ہے اور آپ ڈیویڈنڈ پر کوئی اضافی ہندوستانی ٹیکس ادا نہیں کرتے ہیں۔ رقم پر ایک بار ٹیکس لگایا گیا تھا، دو بار نہیں، جو بالکل وہی ہے جو DTAA کے لیے ہے۔</p>\n<h2 id=\"schedule-fa-you-must-disclose-even-with-no-gain\">شیڈول FA: آپ کو ظاہر کرنا ضروری ہے، یہاں تک کہ بغیر کسی فائدہ کے</h2>\n<p>یہاں ایک قاعدہ ہے جس کا آپ پر کتنا ٹیکس واجب الادا ہے اور ہر چیز کا انکشاف سے کوئی لینا دینا نہیں ہے۔ ایک رہائشی ہندوستانی جو غیر ملکی اثاثوں کا مالک ہے ان کو انکم ٹیکس ریٹرن کے شیڈول FA میں رپورٹ کرنا چاہیے۔ US شیئرز اور US درج کردہ ETFs غیر ملکی اثاثے ہیں، اس لیے ان کا تعلق شیڈول FA میں ہے۔</p>\n<p>لوگوں کا جو حصہ غلط ہوتا ہے وہ یہ سوچتا ہے کہ انکشاف کی ضرورت صرف اس وقت ہوتی ہے جب منافع ہو۔ یہ نہیں ہے. آپ کو شیڈول FA میں اپنے US ہولڈنگز کی اطلاع دینی چاہیے یہاں تک کہ اگر آپ نے کچھ بھی نہیں بیچا، یہاں تک کہ کوئی فائدہ نہیں ہوا، چاہے اسٹاک گر جائے۔ ملکیت ہی وہ ہے جو ظاہر کرنے کے فرض کو متحرک کرتی ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>نفع یا نقصان سے قطع نظر جب آپ غیر ملکی اثاثہ رکھتے ہیں تو شیڈول FA کا انکشاف لازمی ہے۔ یہ ایک ایسی جگہ ہے جو آرام دہ اور پرسکون نہ ہو۔ غیر ملکی اثاثوں کو ظاہر نہ کرنے کے ساتھ ایک الگ قانون کے تحت بہت سنجیدگی سے برتاؤ کیا جاتا ہے، اور محفوظ عادت آسان ہے: US شیئر کے مالک ہوں، ہر سال شیڈول FA میں اس کا اعلان کریں۔</p>\n</div></div>\n<p>لہذا آپ کا US پورٹ فولیو فائل کرنے کے وقت دو الگ الگ ملازمتیں تخلیق کرتا ہے۔ ایک منافع اور منافع پر کوئی ٹیکس ادا کر رہا ہے، جس کی مدد غیر ملکی ٹیکس کریڈٹ سے ہوتی ہے۔ دوسرا شیڈول FA میں ہولڈنگز کا انکشاف کر رہا ہے چاہے کوئی ٹیکس واجب الادا ہے۔ ان دو خیالات کو اپنے ذہن میں الگ رکھیں اور US سرمایہ کاری الجھنا محسوس کرنا بند کر دیتی ہے۔</p>\n<h2 id=\"lrs-and-the-20-tcs-on-money-sent-abroad\">بیرون ملک بھیجی گئی رقم پر LRS اور 20% TCS</h2>\n<p>جاننے کے لیے ایک اور نمبر ہے، اور یہ ظاہر ہوتا ہے کہ آپ نے ایک روپیہ منافع کما لیا ہے۔ یہ اس رقم کے بارے میں ہے جو آپ پہلے حصص خریدنے کے لیے ہندوستان سے باہر بھیجتے ہیں۔ بیرون ملک رقم بھیجنا لبرلائزڈ ریمیٹینس اسکیم کے تحت آتا ہے، LRS، وہ چینل جو رہائشی افراد کو سالانہ حد کے اندر بیرون ملک رقوم بھیجنے دیتا ہے۔</p>\n<p>LRS کے تحت ترسیلات پر، ایک مالی سال میں 7 لاکھ روپے سے زیادہ رقم پر 20% ٹیکس جمع کیا جاتا ہے، یا TCS لاگو ہوتا ہے۔ اچھی خبر یہ ہے کہ TCS کوئی ٹیکس نہیں ہے جسے آپ کھو چکے ہیں۔ یہ ایک کریڈٹ ہے۔ جب آپ فائل کرتے ہیں تو یہ آپ کی مجموعی ٹیکس کی ذمہ داری کے خلاف ایڈجسٹ ہو جاتا ہے، یا اگر آپ نے واجب الادا رقم سے زیادہ ادائیگی کی ہے تو ریفنڈ ہو جاتا ہے، بالکل TDS کی طرح۔</p>\n<table>\n<thead>\n<tr>\n<th>US اسٹاکس کے لیے سال میں بیرون ملک بھیجی گئی رقم</th>\n<th>TCS علاج</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>7 لاکھ روپے تک</td>\n<td>نہیں TCS</td>\n</tr>\n<tr>\n<td>7 لاکھ روپے سے اوپر کا حصہ</td>\n<td>20% TCS، جسے آپ فائل کرتے وقت کریڈٹ کے طور پر دوبارہ دعوی کرتے ہیں۔</td>\n</tr>\n</tbody></table>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>20% TCS تکلیف دہ محسوس ہوتا ہے کیونکہ یہ آپ کے بینک اکاؤنٹ کو سامنے چھوڑ دیتا ہے، لیکن یاد رکھیں کہ یہ آپ کے اپنے پیسے کی صرف ایک عارضی پارکنگ ہے۔ جب آپ فائل کرتے ہیں تو آپ اسے اپنے ٹیکس کے خلاف واپس دعوی کرتے ہیں۔ اپنے بینک سے ترسیلات زر اور TCS کا ریکارڈ رکھیں تاکہ آپ پورا کریڈٹ لے سکیں اور اس رقم کو پیچھے نہ چھوڑیں۔</p>\n</div></div>\n<h2 id=\"putting-your-us-portfolio-together\">اپنے US پورٹ فولیو کو ایک ساتھ رکھنا</h2>\n<p>پیچھے ہٹیں اور پوری تصویر صرف چار متحرک حصوں پر مشتمل ہے۔ جب آپ سرمایہ کاری کے لیے رقم بھیجتے ہیں، تو LRS کی حد کو دیکھیں اور یاد رکھیں کہ 7 لاکھ روپے سے زیادہ 20% TCS قابل وصولی ہے۔ جب آپ فروخت کرتے ہیں تو، آپ کے کیپیٹل گین پر صرف ہندوستان میں ٹیکس لگایا جاتا ہے، 24 مہینوں کے بعد 12.5% ​​پر یا 24 ماہ کے اندر آپ کے سلیب پر، جیسا کہ ہمارے 3,00,000 روپے کے نفع میں جس کی لاگت 37,500 روپے جمع سیس ہے۔ جب آپ ڈیویڈنڈ وصول کرتے ہیں، تو US 25% رکھتا ہے، انڈیا ٹیکس سلیب پر رکھتا ہے، اور فارم 67 آپ کو فارن ٹیکس کریڈٹ دیتا ہے تاکہ ایک ہی رقم پر دو بار ٹیکس نہیں لگایا جاتا ہے۔ اور ہر سال، منافع ہو یا نہ ہو، آپ شیڈول FA میں ہولڈنگز کا انکشاف کرتے ہیں۔ ان چاروں کو جانیں، اپنے بیانات کو صاف ستھرا رکھیں، اور US پورٹ فولیو ٹیکس کے وقت ہندوستانی سے زیادہ مشکل نہیں ہے۔</p>\n<p>یہ باب صرف سیکھنے کے لیے ہے اور ذاتی ٹیکس مشورہ نہیں ہے۔ کراس بارڈر ٹیکس کے قوانین، معاہدے کی شرحیں اور انکشاف کے فارمز تبدیل ہوتے ہیں، اس لیے براہ کرم فائل کرنے سے پہلے کسی اہل چارٹرڈ اکاؤنٹنٹ سے موجودہ پوزیشن کی تصدیق کریں، خاص طور پر جب غیر ملکی اثاثے شامل ہوں۔</p>\n","toc":[{"level":2,"text":"کیپٹل گین: 24 ماہ کی لائن","id":"capital-gains-the-24-month-line"},{"level":2,"text":"ایک طویل مدتی کام کی مثال","id":"a-worked-long-term-example"},{"level":2,"text":"منافع: 25% US رکھتا ہے، اور آپ اسے کیسے واپس حاصل کرتے ہیں","id":"dividends-the-25-the-us-keeps-and-how-you-get-it-back"},{"level":2,"text":"شیڈول FA: آپ کو ظاہر کرنا ضروری ہے، یہاں تک کہ بغیر کسی فائدہ کے","id":"schedule-fa-you-must-disclose-even-with-no-gain"},{"level":2,"text":"بیرون ملک بھیجی گئی رقم پر LRS اور 20% TCS","id":"lrs-and-the-20-tcs-on-money-sent-abroad"},{"level":2,"text":"اپنے US پورٹ فولیو کو ایک ساتھ رکھنا","id":"putting-your-us-portfolio-together"}],"imgCount":1,"hasContent":true},"15":{"html":"<p>کسی ایسے شخص کی تصویر بنائیں جس نے، دو سال پہلے، سرمایہ کاری کرنے والی ایپ کے ذریعے چند US شیئرز میں معمولی رقم رکھی۔ کچھ بھی ڈرامائی نہیں، شاید 90,000 روپے دو یا تین معروف ناموں پر پھیلے ہوئے ہیں۔ حصص بمشکل منتقل ہوئے، وہاں کوئی ڈیویڈنڈ نہیں تھا جس کی بات کی جائے، اور ٹیکس کے وقت سوچ سادہ اور بہت ہی انسانی تھی: کوئی حقیقی فائدہ نہیں تھا، اس لیے محکمہ ٹیکس کو بتانے کے لیے کچھ نہیں ہے۔ یہ واحد مفروضہ ان سب سے مہنگی غلطیوں میں سے ایک ہے جو ایک ہندوستانی باشندہ کر سکتا ہے، کیونکہ کسی غیر ملکی اثاثے کی اطلاع دینے کے فرض کا اس سے کوئی تعلق نہیں ہے کہ آیا آپ نے اس پر پیسہ کمایا ہے۔</p>\n<p>یہ باب اسی فرض کے بارے میں ہے۔ یہ آپ کے ٹیکس ریٹرن کے ایک حصے میں رہتا ہے جسے شیڈول FA کہتے ہیں، اور اس کے پیچھے غیر معمولی طور پر تیز دانتوں والا ایک قانون بیٹھا ہے، بلیک منی ایکٹ آف 2015۔ ایک بار جب آپ دونوں کو سمجھ جائیں گے، تو آپ دیکھیں گے کہ غیر ملکی ہولڈنگ کو ظاہر کرنا اختیاری ہاؤس کیپنگ کیوں نہیں ہے لیکن ایک لائن جسے آپ آسانی سے عبور نہیں کرتے ہیں۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/taxation/images/diagram-schedule-fa.png\" alt=\"شیڈول FA پوچھتا ہے کہ بیرون ملک آپ کی ملکیت کیا ہے، نہ کہ آپ نے کیا کمایا، اور غیر رپورٹ شدہ غیر ملکی اثاثہ بلیک منی ایکٹ کے تحت آسکتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>شیڈول FA پوچھتا ہے کہ بیرون ملک آپ کی ملکیت کیا ہے، نہ کہ آپ نے کیا کمایا، اور غیر رپورٹ شدہ غیر ملکی اثاثہ بلیک منی ایکٹ کے تحت آسکتا ہے۔</figcaption></figure>\n<h2 id=\"schedule-fa-a-disclosure-that-ignores-your-profit\">شیڈول FA: ایک ایسا انکشاف جو آپ کے منافع کو نظر انداز کرتا ہے۔</h2>\n<p>شیڈول FA انکم ٹیکس ریٹرن کا ایک سیکشن ہے جہاں ایک رہائشی کو اپنے پاس موجود ہر غیر ملکی اثاثے کی فہرست دینی چاہیے۔ US شیئرز، فارن ایکسچینج ٹریڈڈ فنڈز (ETFs)، اوورسیز بروکریج اکاؤنٹس اور غیر ملکی بینک اکاؤنٹس سبھی یہاں سے تعلق رکھتے ہیں۔</p>\n<p>وہ حصہ جو لوگوں کو دور کرتا ہے یہ ہے۔ جیسا کہ چیزیں AY 2026-27 کے لیے ہیں، ایک رہائشی کو شیڈول FA میں تمام غیر ملکی اثاثوں کو ظاہر کرنا چاہیے چاہے کوئی فائدہ نہ ہو۔ صفر منافع ڈیوٹی کو بند نہیں کرتا ہے۔ ایک فلیٹ شیئر کی قیمت اسے بند نہیں کرتی ہے۔ یہاں تک کہ ایک ہولڈنگ جو کھوئی ہوئی قیمت کو اب بھی ظاہر کرنا ضروری ہے۔ شیڈول یہ نہیں پوچھ رہا ہے کہ \"کیا آپ نے بیرون ملک کچھ کمایا\"، یہ پوچھ رہا ہے کہ \"بیرون ملک آپ کے پاس کیا ہے\"، اور یہ دو بالکل مختلف سوالات ہیں۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>شیڈول FA ملکیت کی اطلاع دیتا ہے، آمدنی نہیں۔ اگر آپ رہائشی ہیں اور آپ کے پاس US شیئرز یا غیر ملکی ETFs ہیں، تو آپ کو ہر سال ان کا انکشاف کرنا چاہیے، یہاں تک کہ صفر نفع، صفر ڈیویڈنڈ، یا نقصان کے ساتھ۔ \"میں نے اس پر کچھ نہیں بنایا\" باکس کو خالی چھوڑنے کی کوئی معقول وجہ نہیں ہے۔</p>\n</div></div>\n<p>یہ ایماندار سرمایہ کاروں کو کسی سے زیادہ پکڑتا ہے۔ کوئی شخص جس نے احتیاط سے اپنے ہندوستانی کیپیٹل گین کی اطلاع دی، ہر ایک روپیہ واجب الادا ادا کیا، اور صرف یہ فرض کیا کہ ایک بیکار US ہولڈنگ بہت چھوٹا یا معاملہ کے لیے بہت پرسکون ہے، تب بھی خلاف ورزی ہو سکتی ہے۔ آمدنی صفر تھی، لیکن انکشاف کبھی اختیاری نہیں تھا۔</p>\n<h2 id=\"what-counts-as-a-foreign-asset\">غیر ملکی اثاثہ کے طور پر کیا شمار ہوتا ہے</h2>\n<p>آپ کو مکمل قانونی فہرست کو حفظ کرنے کی ضرورت نہیں ہے، لیکن آپ کو ان مشترکہ ہولڈنگز کو پہچاننا چاہیے جو ہندوستانی تاجر یا سرمایہ کار کے پاس ہونے کا امکان ہے۔ ان سب کا دھاگہ ایک ہی ہے: ہندوستان سے باہر بیٹھی ملکیت۔</p>\n<table>\n<thead>\n<tr>\n<th>غیر ملکی ہولڈنگ</th>\n<th>شیڈول FA میں جاتا ہے۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>US حصص براہ راست منعقد ہوئے۔</td>\n<td>جی ہاں</td>\n</tr>\n<tr>\n<td>غیر ملکی ETFs اور میوچل فنڈز</td>\n<td>جی ہاں</td>\n</tr>\n<tr>\n<td>بیرون ملک بروکریج اکاؤنٹ</td>\n<td>جی ہاں</td>\n</tr>\n<tr>\n<td>غیر ملکی بینک اکاؤنٹ</td>\n<td>جی ہاں</td>\n</tr>\n<tr>\n<td>غیر ملکی کمپنی کے شیئرز ایک ایپ کے ذریعے خریدے گئے۔</td>\n<td>جی ہاں</td>\n</tr>\n</tbody></table>\n<p>جس لمحے آپ کا پیسہ بیرون ملک رہنے والا کوئی اثاثہ خریدتا ہے، شیڈول FA تصویر میں ہوتا ہے، قطع نظر اس اثاثہ کی کارکردگی کیسی ہے۔ ایک ہولڈنگ جو دگنی ہو جائے اور ایک ہولڈنگ جو آدھی ہو جائے انکشاف کے مقصد کے لیے بالکل یکساں سلوک کیا جاتا ہے۔ دونوں کو رپورٹ کرنا ضروری ہے۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>ہر سال دو الگ الگ سوالات ہوتے ہیں۔ سب سے پہلے، کیا غیر ملکی اثاثہ آمدنی پیدا کرتا ہے (فروخت پر حاصل، ایک منافع)، جس پر آپ عام طریقے سے ٹیکس لگاتے ہیں اور جس کے لیے آپ پہلے سے روکے گئے US ٹیکس پر غیر ملکی ٹیکس کریڈٹ کا دعوی کر سکتے ہیں۔ دوسرا، کیا آپ کے پاس کوئی غیر ملکی اثاثہ ہے، جسے شیڈول FA ہمیشہ جاننا چاہتا ہے۔ آپ \"کوئی آمدنی نہیں\" کا جواب دے سکتے ہیں اور پھر بھی ملکیت پر \"ہاں\" کا مقروض ہے۔</p>\n</div></div>\n<h2 id=\"the-lrs-route-and-the-20-percent-tcs\">LRS روٹ اور 20 فیصد TCS</h2>\n<p>US حصص خریدنے کے لیے آپ کو سب سے پہلے بیرون ملک رقم بھیجنی ہوگی، اور یہ لبرلائزڈ ریمیٹنس اسکیم کے تحت ہوتا ہے، جسے عام طور پر مختصر کرکے LRS کردیا جاتا ہے۔ یہ وہ ونڈو ہے جو ایک رہائشی کو سالانہ حد کے اندر بیرون ملک رقوم بھیجنے دیتی ہے۔</p>\n<p>یہاں دو نمبر اہم ہیں۔ 20% TCS (مآخذ پر ٹیکس جمع کیا گیا، ایک ایڈوانس ٹیکس جو سسٹم پہلے سے جمع کرتا ہے) ایک سال میں 7 لاکھ روپے سے زیادہ کی ترسیلات پر لاگو ہوتا ہے۔ یقین دہانی کرنے والی بات یہ ہے کہ یہ TCS وہ رقم نہیں ہے جو آپ کھوتے ہیں۔ یہ آپ کے PAN کے خلاف جمع کیا جاتا ہے اور جب آپ فائل کرتے ہیں، اپنے ٹیکس کے خلاف سیٹ آف کرتے ہیں یا آپ کو ریفنڈ کرتے ہیں تو آپ اسے کریڈٹ کے طور پر دوبارہ دعوی کرتے ہیں۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>فرض کریں کہ آپ ایک سال میں 12 لاکھ روپے بیرون ملک بھجواتے ہیں US شیئرز خریدنے کے لیے۔ پہلے 7 لاکھ روپے کا نمبر TCS ہے۔ بقیہ 5 لاکھ روپے 20% TCS، جو کہ 5,00,000 کا 20% ہے، 1,00,000 روپے کے برابر ہے۔ وہ 1,00,000 روپے ختم نہیں ہوئے۔ یہ آپ کے PAN کے خلاف ظاہر ہوتا ہے، اور جب آپ اپنا ریٹرن فائل کرتے ہیں تو آپ اسے کریڈٹ کے طور پر واپس کرنے کا دعویٰ کرتے ہیں، اس لیے آپ کے لیے اصل لاگت وقت ہے، روپیہ نہیں۔</p>\n</div></div>\n<h2 id=\"the-black-money-act-and-why-this-rule-bites\">بلیک منی ایکٹ، اور یہ اصول کیوں کاٹتا ہے۔</h2>\n<p>اب وہ حصہ جو کاغذی کارروائی کی ڈیوٹی کو کہیں زیادہ سنگین چیز میں بدل دیتا ہے۔ شیڈول FA میں غیر ملکی اثاثوں کی اطلاع دینے میں ناکامی صرف عام انکم ٹیکس جرمانے کے تحت نہیں آتی ہے۔ اس کا تعاقب بلیک منی (غیر ظاہر شدہ غیر ملکی آمدنی اور اثاثے) ایکٹ 2015 کے تحت کیا جا سکتا ہے، یہ ایک الگ اور بہت سخت قانون ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>بلیک منی ایکٹ 2015 کے تحت نتیجہ</th>\n<th>اس کا کیا مطلب ہے۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>جرمانہ</td>\n<td>ظاہر نہ کرنے پر 10 لاکھ روپے سالانہ</td>\n</tr>\n<tr>\n<td>قید</td>\n<td>6 ماہ سے 7 سال</td>\n</tr>\n<tr>\n<td>غیر ظاہر شدہ آمدنی پر ٹیکس</td>\n<td>30%</td>\n</tr>\n</tbody></table>\n<p>جاننے کے لیے ایک اہم راحت ہے، اور یہ حال ہی میں بدل گیا ہے۔ 1 اکتوبر 2024 سے، یہ 10 لاکھ روپے کا جرمانہ لاگو نہیں ہوتا ہے جہاں سال کے دوران غیر منقولہ جائیداد کے علاوہ آپ کے غیر ملکی اثاثوں کی کل قیمت 20 لاکھ روپے سے کم رہتی ہے۔ لہٰذا اس لائن کے نیچے آرام سے چند US شیئرز کا معمولی انعقاد، خود بخود 10 لاکھ روپے کے جرمانے کو متوجہ نہیں کرے گا۔ قانون کا پرانا ورژن، جو کہ چھوٹی چھوٹی ہولڈنگز کو بھی نقصان پہنچا سکتا ہے، بڑے پیمانے پر بہت سخت کے طور پر دیکھا جاتا تھا، اور یہ تراش خراش اسے ٹھیک کرتا ہے۔</p>\n<p>کارو آؤٹ کیا کرتا ہے NOT ظاہر کرنے کی ڈیوٹی کو بند کرنا ہے۔ آپ کو ہر سال شیڈول FA میں ہولڈنگ کی اطلاع دینی چاہیے، چاہے اس کا سائز کچھ بھی ہو۔ ریلیف چھوٹے غیر منقولہ غیر منقولہ اثاثوں کے جرمانے کو نرم کرتا ہے۔ یہ غیر افشاء کو محفوظ نہیں بناتا، اور یہ بڑے غیر ملکی اثاثوں، بیرون ملک غیر منقولہ جائیداد، یا کسی غیر ظاہر شدہ غیر ملکی آمدنی کو بالکل بھی پناہ نہیں دیتا۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>بلیک منی ایکٹ کے تحت غیر ظاہر شدہ غیر ملکی اثاثہ کے لیے 10 لاکھ روپے سالانہ جرمانہ ہو سکتا ہے، اس کے ساتھ چھ ماہ سے سات سال تک کی ممکنہ قید اور غیر ظاہر شدہ آمدنی پر 30 فیصد ٹیکس ہو سکتا ہے۔ اکتوبر 2024 سے ایک تراشی ہوئی ہے: یہ جرمانہ لاگو نہیں ہوتا ہے جہاں جائیداد کے علاوہ آپ کے غیر ملکی اثاثے سال میں 20 لاکھ روپے سے کم رہتے ہیں۔ لیکن شیڈول FA ڈسکلوزر ڈیوٹی اب بھی ہر غیر ملکی ہولڈنگ کے لیے ہے چاہے وہ چھوٹی کیوں نہ ہو، اور اثاثے زیادہ ہونے یا کوئی آمدنی چھپنے پر جرمانہ سخت ہوتا ہے۔ محفوظ راستہ کوئی تبدیلی نہیں ہے: ہر سال ہر چیز کا انکشاف کریں۔</p>\n</div></div>\n<h2 id=\"a-cautionary-scenario\">ایک احتیاطی منظر</h2>\n<p>افتتاح سے سرمایہ کار کے پاس واپس جائیں۔ اسے میرا بلاؤ۔ کچھ سال پہلے اس نے ایک ایپ کے ذریعے تقریباً 90,000 روپے تین US شیئرز میں منتقل کیے، جزوی طور پر تجسس سے باہر۔ حصص ایک طرف بڑھ گئے، تقریباً کچھ بھی ادا نہیں کیا، اور اس نے ایمانداری کے ساتھ انہیں ایک رسمی \"غیر ملکی اثاثہ\" سمجھنا چھوڑ دیا۔ ہر سال اس نے اپنا ریٹرن فائل کیا، اپنی تنخواہ اور اپنے ہندوستانی سرمائے کے منافع کا اعلان کیا، مکمل ادائیگی کی، اور شیڈول FA کو خالی چھوڑ دیا کیونکہ، اس کے ذہن میں، رپورٹ کرنے کے لیے کوئی غیر ملکی آمدنی نہیں تھی۔</p>\n<p>وہ ٹھیک کہتی تھی کہ غیر ملکی آمدنی نہیں تھی۔ اسے یاد آیا کہ ایک غیر ملکی اثاثہ تھا۔ وہ مختلف چیزیں ہیں، اور شیڈول FA دوسری کے بارے میں پوچھتا ہے۔</p>\n<p>میرا کی پوزیشن میں خطرہ اس کے US شیئرز پر ٹیکس نہیں ہے، جو کہ نہ ہونے کے برابر ہے۔ خطرہ یہ ہے کہ غیر رپورٹ شدہ غیر ملکی اثاثہ، چاہے وہ چھوٹا ہو، بلیک منی ایکٹ کے تحت آتا ہے، جہاں جرمانہ 10 لاکھ روپے سالانہ ہے اور معاملہ مجرمانہ بھی بن سکتا ہے۔ ایک ایسا انعقاد جس سے اسے تقریباً کچھ حاصل نہیں ہوا، بدترین صورت میں، اسے اس کی قیمت سے کئی گنا زیادہ جرمانے کا سامنا کرنا پڑا، صرف اس وجہ سے کہ ایک باکس سال بہ سال خالی رہ جاتا ہے۔</p>\n<p>اس کا سمجھدار حل پرسکون ہے۔ ہولڈنگ کا انکشاف کریں، مثالی طور پر ایک چارٹرڈ اکاؤنٹنٹ کے ساتھ اس کی رہنمائی کرتے ہوئے، اس کے ماضی کے ریٹرن کو لائن میں لائیں، اور اب سے شیڈول FA کو فائلنگ کے ایک معمول کے، نہ چھوڑے جانے والے حصے کے طور پر پیش کریں۔ اسے جلد ٹھیک کرنے کی لاگت بہت کم ہے۔ بعد میں ملنے کی قیمت نہیں ہے۔</p>\n<h2 id=\"staying-on-the-right-side-of-it\">اس کے دائیں طرف رہنا</h2>\n<p>حقیقی طور پر یقین دلانے والی سچائی یہ ہے کہ اس سے بچنے کے لیے یہ سب سے آسان سنگین خطرات میں سے ایک ہے، کیونکہ تعمیل میں آپ کو تھوڑی سی دیکھ بھال اور اچھے ریکارڈ کے سوا کچھ نہیں دینا پڑتا۔</p>\n<ul>\n<li>ہر غیر ملکی ہولڈنگ کی ایک سادہ فہرست رکھیں، آپ نے اسے کس تاریخ میں خریدا، اور آپ نے کیا ادا کیا۔</li>\n<li>ہر سال شیڈول FA میں ان سب کو ظاہر کریں، فائدہ یا کوئی فائدہ نہیں، نقصان پر بھی۔</li>\n<li>اپنی LRS ترسیلات اور 20% TCS کو ٹریک کریں جو 7 لاکھ سے اوپر لاگو ہوتا ہے، اور دعوی کریں کہ جب آپ فائل کرتے ہیں تو TCS بطور کریڈٹ واپس کریں۔</li>\n<li>غیر ملکی اثاثوں کے ساتھ رہائشی فارم جو عام طور پر فائل کرتا ہے وہ ہے ITR-2، یا ITR-3 اگر آپ بطور کاروبار بھی تجارت کرتے ہیں۔</li>\n<li>جب غیر ملکی اثاثے تصویر میں ہوں تو چارٹرڈ اکاؤنٹنٹ کو لائیں۔ یہ بالکل وہی علاقہ ہے جہاں ایک چھوٹی سی پیشہ ورانہ فیس بہت بڑی ذہنی سکون خریدتی ہے۔</li>\n</ul>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>شیڈول کو اسی عادت کا حصہ بنائیں جس طرح اپنے بروکر کے بیانات جمع کرنا۔ ہر فائلنگ سیزن کے آغاز پر ایک بار فیصلہ کریں کہ ہر غیر ملکی ہولڈنگ چاہے کتنی ہی چھوٹی یا کتنی ہی خاموش کیوں نہ ہو۔ جس سرمایہ کار کو کبھی بھی بلیک منی ایکٹ کے بارے میں فکر کرنے کی ضرورت نہیں ہے وہ صرف وہی ہے جو باکس کو کبھی خالی نہیں چھوڑتا ہے۔</p>\n</div></div>\n<p>یہ باب سیکھنے کے لیے ہے، فائل کرنے کے لیے نہیں۔ ٹیکس کے قوانین اور ان کے اندر موجود اعداد و شمار سال بہ سال تبدیل ہوتے رہتے ہیں، اور غیر ملکی اثاثے ایک اعلیٰ داؤ پر لگے ہوئے ہیں، اس لیے اپنا ریٹرن جمع کرانے سے پہلے کسی قابل چارٹرڈ اکاؤنٹنٹ سے اپنی پوزیشن کی تصدیق کریں۔</p>\n","toc":[{"level":2,"text":"شیڈول FA: ایک ایسا انکشاف جو آپ کے منافع کو نظر انداز کرتا ہے۔","id":"schedule-fa-a-disclosure-that-ignores-your-profit"},{"level":2,"text":"غیر ملکی اثاثہ کے طور پر کیا شمار ہوتا ہے","id":"what-counts-as-a-foreign-asset"},{"level":2,"text":"LRS روٹ اور 20 فیصد TCS","id":"the-lrs-route-and-the-20-percent-tcs"},{"level":2,"text":"بلیک منی ایکٹ، اور یہ اصول کیوں کاٹتا ہے۔","id":"the-black-money-act-and-why-this-rule-bites"},{"level":2,"text":"ایک احتیاطی منظر","id":"a-cautionary-scenario"},{"level":2,"text":"اس کے دائیں طرف رہنا","id":"staying-on-the-right-side-of-it"}],"imgCount":1,"hasContent":true},"16":{"html":"<p>ایک تاجر جسے ہم کہیں گے ارجن کا کرپٹو میں مصروف سال گزرا۔ اس نے خریدا ایک سکہ خوبصورتی سے نکلا اور اس نے صحت مند منافع بک کیا۔ ایک اور سکہ جس کے بارے میں اسے یقین تھا کہ غلط ہو گیا اور اس نے اسے نقصان میں بیچ دیا۔ جب ٹیکس کا سیزن آیا تو اس نے وہ رقم کی جو کوئی ایکویٹی سرمایہ کار کرے گا: اس نے جیتنے والے کو ہارنے والے کے خلاف جال لگایا، صرف اس پر ٹیکس ادا کرنے کی امید رکھی جو بچا تھا۔ پھر اس نے دریافت کیا کہ کرپٹو حصص کی طرح کام نہیں کرتا۔ اس کے نقصان کو محض نظر انداز کر دیا گیا، اور اس نے جیتنے والے سکے کے پورے منافع پر ٹیکس واجب الادا تھا گویا ہارنے والا کبھی ہوا ہی نہیں۔</p>\n<p>یہ ہندوستانی ٹیکس میں قوانین کا واحد سخت ترین مجموعہ ہے، اور یہ اس پر لاگو ہوتا ہے جسے قانون ورچوئل ڈیجیٹل اثاثہ جات، یا VDAs کہتا ہے، جو کہ کرپٹو کوائنز اور ٹوکنز کا باقاعدہ نام ہے۔ قوانین پیچیدہ نہیں ہیں، لیکن وہ غیرمعمولی طور پر ناقابل معافی ہیں، اور جن لوگوں کو تکلیف پہنچتی ہے وہ تقریباً ہمیشہ وہی ہوتے ہیں جنہوں نے فرض کیا کہ کرپٹو پر ان کی ہر چیز کی طرح ٹیکس لگایا جائے گا۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/taxation/images/diagram-crypto-tax.png\" alt=\"سیکشن 115BBH کے تحت کرپٹو گین کو فلیٹ 30%، فروخت پر 1% TDS، اور نقصانات کا سامنا کرنا پڑتا ہے جن کو ختم یا آگے نہیں بڑھایا جا سکتا۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>سیکشن 115BBH کے تحت Crypto کے منافع کو فلیٹ 30%، فروخت پر 1% TDS، اور نقصانات کا سامنا کرنا پڑتا ہے جن کو ختم یا آگے نہیں بڑھایا جا سکتا۔</figcaption></figure>\n<h2 id=\"a-flat-30-percent-whatever-your-slab\">فلیٹ 30 فیصد، جو بھی آپ کا سلیب ہو۔</h2>\n<p>پہلا اصول سرخی والا ہے۔ سیکشن 115BBH کے تحت کریپٹو پر حاصلات پر فلیٹ 30%، نیز سرچارج جہاں یہ لاگو ہوتا ہے اور سب سے اوپر 4% ہیلتھ اور ایجوکیشن سیس لگایا جاتا ہے۔ یہاں صرف فروخت کی قیمت مائنس لاگت کی قیمت ہے۔</p>\n<p>لفظ \"فلیٹ\" اہم ہے۔ حصص یا تنخواہ کے ساتھ، ایک چھوٹا کمانے والا کم شرح ادا کرتا ہے اور صرف بڑی آمدنی 30% تک پہنچ جاتی ہے۔ کرپٹو ان سب کو نظر انداز کرتا ہے۔ چاہے آپ کی کل آمدنی معمولی ہو یا زیادہ، سکے پر حاصل ہونے والے منافع پر 30% ٹیکس لگایا جاتا ہے۔ ابتدائی کے لیے کوئی کم بینڈ نہیں ہے، اور سلیب سسٹم جو آپ نے پہلے ابواب میں سیکھا ہوگا اس آمدنی پر بالکل بھی لاگو نہیں ہوتا ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>سیکشن 115BBH کے تحت Crypto گین پر فلیٹ 30% ٹیکس لگایا جاتا ہے، نیز سیس، چاہے آپ کی دوسری آمدنی کتنی ہی کم ہو۔ سلیب ریٹ جو کم کمانے والے کو تنخواہ یا حصص پر تحفظ فراہم کرتے ہیں آپ کو یہاں کوئی ریلیف نہیں دیتے۔ فائدہ فروخت کی قیمت مائنس لاگت ہے، اور اس کا 30% ٹیکس میں جاتا ہے۔</p>\n</div></div>\n<h2 id=\"only-the-cost-is-deductible\">صرف لاگت کٹوتی ہے۔</h2>\n<p>دوسرا قاعدہ اس 30% کو لاگو کرنے سے پہلے آپ جو منہا کر سکتے ہیں اسے کم کرتا ہے۔ جب آپ نفع کا حساب لگاتے ہیں، تو صرف ایک چیز جو آپ کٹوتی کر سکتے ہیں وہ ہے حصول کی قیمت، یعنی آپ نے اصل میں سکے کے لیے کیا ادا کیا ہے۔ اور کسی چیز کی اجازت نہیں۔</p>\n<p>وہ \"اور کچھ نہیں\" سخت ہے۔ آپ ایکسچینج فیس یا ٹرانزیکشن چارجز کاٹ نہیں سکتے۔ آپ کسی بھی انفراسٹرکچر، سافٹ ویئر یا بجلی کی لاگت کاٹ نہیں سکتے۔ آپ اس رقم پر سود کاٹ نہیں سکتے جو آپ نے خریدنے کے لیے لیا تھا۔ کاروباری آمدنی یا یہاں تک کہ عام سرمائے کے منافع کے ساتھ عام طور پر ایسے اخراجات ہوتے ہیں جنہیں آپ خالص کر سکتے ہیں، لیکن یہاں دروازہ بند ہے۔ لاگت کی قیمت، فروخت کی قیمت باہر، اور فرق پر ٹیکس لگایا جاتا ہے۔</p>\n<p>ایک فوری مثال کاٹنے کو ظاہر کرتی ہے۔ تصور کریں کہ آپ 1,00,000 میں ایک سکہ خریدتے ہیں، راستے میں 1,000 فیس ادا کرتے ہیں، بعد میں اسے 1,50,000 میں بیچتے ہیں، اور باہر جاتے وقت مزید 1,000 فیس ادا کرتے ہیں۔ آپ کا حقیقی نقد منافع 50,000 مائنس فیس کے 2,000 سے ہے، جو کہ 48,000 ہے۔ لیکن قابل ٹیکس نفع اب بھی 1,50,000 مائنس 1,00,000، 50,000 کے برابر ہے، اور اس پورے 50,000 پر 30% چارج کیا جاتا ہے۔ فیس آپ کی جیب سے نکل آئی لیکن آپ کو کوئی ریلیف نہیں ملا۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>اس کا عملی اثر یہ ہے کہ آپ کا اصل، بعد از فیس منافع ٹیکس کے حساب سے کم ہے۔ اگر فیس آپ کی تجارت میں کھا جاتی ہے، تب بھی ٹیکس مین خام قیمت سے خام فروخت تک کے منافع کی پیمائش کرتا ہے اور ان فیسوں کو مکمل طور پر نظر انداز کرتا ہے۔ تجارت سے پہلے اسے اپنی توقعات کے مطابق بنائیں، بعد میں نہیں۔</p>\n</div></div>\n<h2 id=\"the-1-percent-tds-on-every-sale\">ہر فروخت پر 1 فیصد TDS</h2>\n<p>تیسرا اصول ایک کٹوتی ہے جو فروخت کے وقت ہوتی ہے۔ سیکشن 194S کے تحت VDA کی فروخت پر 1% TDS (ماخذ پر ٹیکس کٹوتی) لاگو ہوتا ہے۔ سادہ الفاظ میں، جب کوئی سکہ بیچا جاتا ہے، تو فروخت کی قیمت کا 1% واپس رکھا جاتا ہے اور بیچنے والے کے PAN کے خلاف جمع کر دیا جاتا ہے۔ یہ ایک چھوٹی سی حد سے اوپر جاتا ہے، جو مخصوص افراد کے لیے ایک سال میں 50,000 روپے اور دوسروں کے لیے 10,000 روپے ہے۔</p>\n<p>یہ TDS 30% کے اوپر کوئی اضافی ٹیکس نہیں ہے۔ یہ آپ کے ٹیکس کی پیشگی قسط ہے جسے آپ فائل کرتے وقت ایڈجسٹ کرتے ہیں۔ اگر آپ کا حتمی ٹیکس زیادہ ہے، تو آپ بیلنس ادا کرتے ہیں۔ اگر یہ کم ہے، تو آپ فرق واپس کرنے کا دعوی کرتے ہیں۔ اس کا اصل مقصد محکمہ کو ہر کرپٹو فروخت کا واضح ٹریل دینا ہے، جو کہ کسی تجارت کو پوشیدہ سمجھنے سے پہلے یاد رکھنے کے قابل ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>سیکشن 194S کے تحت 1% TDS کا مطلب ہے کہ محکمہ آپ کی کرپٹو سیلز کو دیکھتا ہے چاہے آپ ان کی اطلاع دیں یا نہیں۔ یہ دہلیز کے اوپر ہر تصرف پر چھوڑا ہوا نقش ہے۔ کریپٹو کو مکمل طور پر دکھائی دینے والا سمجھیں، آپ کے PAN کے خلاف ظاہر ہونے والے TDS کو جوڑیں، اور ایمانداری سے رپورٹ کریں۔ یہ فرض کرنا کہ سرگرمی چھپی ہوئی ہے ایک مہنگی غلطی ہے۔</p>\n</div></div>\n<h2 id=\"the-harshest-rule-losses-go-nowhere\">سخت ترین اصول: نقصان کہیں نہیں جاتا</h2>\n<p>یہ وہ اصول ہے جس نے ارجن کو حیران کر دیا، اور یہ وہی ہے جو کرپٹو کو حقیقی طور پر سزا دیتا ہے۔ کرپٹو ٹریڈ پر ہونے والے نقصان کو کسی بھی چیز کے خلاف ختم نہیں کیا جا سکتا۔ آپ کی تنخواہ کے خلاف نہیں، حصص پر کیپیٹل گین کے خلاف نہیں، کاروباری آمدنی کے خلاف نہیں، اور سب سے زیادہ تکلیف دہ بات یہ ہے کہ دوسرے کرپٹو پر حاصل ہونے والے منافع کے خلاف بھی نہیں۔ اس کے اوپری حصے میں، نقصان کو آئندہ سال تک بھی نہیں بڑھایا جا سکتا۔</p>\n<p>اس کے ساتھ بیٹھو یہ کتنا غیر معمولی ہے۔ ٹیکس کے تقریباً ہر دوسرے کونے میں، نقصان کی قدر ہوتی ہے: یہ اب ایک مماثل نفع کو کم کر دیتا ہے، یا یہ بعد میں منافع کو پناہ دینے کے لیے آپ کی واپسی کا انتظار کرتا ہے۔ ایک کرپٹو نقصان نہیں ہے. یہ اس سال کے ٹیکس کو کم نہیں کرتا ہے اور یہ اگلے سال تک زندہ نہیں رہتا ہے۔ یہ صرف غائب ہو جاتا ہے.</p>\n<p>یہی وجہ ہے کہ کرپٹو احتیاط کو ایک طرح سے انعام دیتا ہے جس طرح کچھ اثاثے کرتے ہیں۔ حصص کا تاجر نقصانات کو جانتے ہوئے کم از کم جیتنے والوں پر ٹیکس کو نرم کر کے کچھ ہارنے والی پوزیشن لے سکتا ہے۔ ایک کرپٹو تاجر کو ایسا کوئی کشن نہیں ملتا۔ ہر ہارنے والی تجارت ایک صاف، مکمل نقصان ہے جس میں ٹیکس کا کوئی فائدہ نہیں ہے، اس لیے چھوٹے سائز کرنے اور لاپرواہ شرط لگانے سے گریز کرنے کا نظم ان بازاروں سے بھی زیادہ اہمیت رکھتا ہے جو آپ پہلے سے جانتے ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>اثاثہ</th>\n<th>کیا نقصان ایک مماثل فائدہ کو کم کر سکتا ہے؟</th>\n<th>کیا نقصان آگے بڑھ سکتا ہے؟</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>فہرست شدہ حصص (سرمایہ کاری)</td>\n<td>ہاں، قوانین کے اندر</td>\n<td>ہاں، کئی سالوں سے</td>\n</tr>\n<tr>\n<td>کاروباری آمدنی</td>\n<td>جی ہاں، تنخواہ کے علاوہ زیادہ تر سروں کے خلاف</td>\n<td>ہاں، اگر وقت پر دائر کیا جائے۔</td>\n</tr>\n<tr>\n<td>کرپٹو (VDA)</td>\n<td>نہیں، دوسرے کرپٹو کے خلاف بھی نہیں۔</td>\n<td>نہیں</td>\n</tr>\n</tbody></table>\n<h2 id=\"worked-example-two-coins-one-hard-lesson\">کام کی مثال: دو سکے، ایک مشکل سبق</h2>\n<p>آئیے ہم ارجن کے سال کو اعداد میں ڈالتے ہیں، کیونکہ اعداد و شمار اصول کو ناقابل فراموش بناتے ہیں۔</p>\n<p>وہ ایک سکہ 2,00,000 میں خریدتا ہے اور بعد میں اسے 3,00,000 میں فروخت کرتا ہے۔ فائدہ 3,00,000 مائنس 2,00,000، 1,00,000 کے برابر ہے۔ ٹیکس 1,00,000 کا 30% ہے جو کہ 30,000 ہے، اس کے علاوہ اس 30,000 پر 4% سیس، جو کہ 1,200 ہے۔ تو جیتنے والے سکے کا بل 31,200 ہے۔</p>\n<p>اسی سال وہ ایک اور سکہ 1,00,000 میں خریدتا ہے اور اسے 60,000 میں فروخت کرتا ہے۔ نقصان 1,00,000 مائنس 60,000، 40,000 کے برابر ہے۔</p>\n<p>ہر جبلت کا کہنا ہے کہ 40,000 کے نقصان کو 1,00,000 کے فائدے میں کاٹنا چاہئے، اس پر صرف 60,000 پر ٹیکس لگا دیا جائے گا۔ ایسا نہیں ہوتا۔ نقصان کو کریپٹو گین کے خلاف بالکل بھی سیٹ نہیں کیا جا سکتا۔ اس پر پورے 1,00,000 نفع پر ٹیکس لگایا جاتا ہے، اس لیے وہ اب بھی 31,200 کا مقروض ہے، حالانکہ دونوں سکوں پر اس کا اصل نقد منافع صرف 1,00,000 مائنس 40,000 تھا، جو کہ 60,000 ہے۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>جیتنے والا سکہ: 2,00,000 خریدا، 3,00,000 بیچا، 1,00,000 کا فائدہ، 30% پر ٹیکس 30,000 کے برابر، علاوہ 1,200 کا سیس، کل 31,200۔ کھوئے ہوئے سکے: خریدا 1,00,000، بیچا 60,000، نقصان 40,000۔ 40,000 کا نقصان جیتنے والے سکے پر ٹیکس کو کچھ بھی نہیں کم کرتا ہے۔ ارجن صرف 60,000 کے حقیقی نقد منافع پر 31,200 ادا کرتا ہے، اور کھوئے ہوئے 40,000 کو اگلے سال تک نہیں لے جایا جا سکتا۔</p>\n</div></div>\n<p>یہ فرق، مجموعی فاتح پر 30% ادا کرنا جبکہ حقیقی نقصان کو ایسا سمجھا جاتا ہے جیسے ایسا کبھی ہوا ہی نہیں، کرپٹو ٹیکس کی وضاحتی خصوصیت ہے۔ یہی وجہ ہے کہ پوزیشن کا سائز اور نظم و ضبط یہاں کسی اور جگہ سے بھی زیادہ اہمیت رکھتا ہے: نقصان سے آپ کو پیسے لگتے ہیں اور ٹیکس کے وقت آپ کو کچھ بھی واپس نہیں ملتا ہے۔</p>\n<h2 id=\"where-it-goes-schedule-vda\">یہ کہاں جاتا ہے: شیڈول VDA</h2>\n<p>آخر میں، آپ یہ سب کہاں رپورٹ کرتے ہیں؟ کریپٹو حاصلات کا اعلان واپسی کے ایک وقف شدہ حصے میں کیا جاتا ہے جسے شیڈول VDA کہتے ہیں۔ آپ وہاں رپورٹ کرتے ہیں کہ آیا آپ اپنے کرپٹو کو بطور سرمایہ کار یا تاجر کے طور پر پیش کرتے ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>آپ کا حال</th>\n<th>فارم جس میں شیڈول VDA ہوتا ہے۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>کرپٹو کو ایک سرمایہ کار کے طور پر رکھا گیا، سرمایہ حاصل ہوا۔</td>\n<td>ITR-2</td>\n</tr>\n<tr>\n<td>کرپٹو ایک کاروبار کے طور پر تجارت کرتا تھا۔</td>\n<td>ITR-3</td>\n</tr>\n</tbody></table>\n<p>فارم مختلف ہے، لیکن شیڈول VDA انکشاف کے لیے عام گھر ہے۔ اسے احتیاط سے پُر کریں، اسے 1% TDS سے جوڑیں جو آپ کے PAN کے خلاف پہلے سے بیٹھے ہوئے ہیں، اور اپنے خرید و فروخت کے ریکارڈ کو محفوظ رکھیں، کیونکہ حصول کی لاگت ایک اور صرف کٹوتی ہے جو قانون آپ کو دعوی کرنے دے گا۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>تجارت کرنے سے پہلے، کرپٹو ٹیکس کی وضاحت کرنے والے تین نمبروں کو اندرونی بنائیں: منافع پر 30% فلیٹ، ہر فروخت پر 1% TDS، اور کسی بھی نقصان کے لیے صفر قدر۔ اگر آپ اپنی پوزیشنوں کا سائز جانتے ہوئے کہ نقصان کو جان کر آپ کو کسی بھی طرح سے مدد نہیں ملتی ہے، تو آپ کرپٹو کے ساتھ اس احتیاط کے ساتھ سلوک کریں گے جس کا وہ مستحق ہے بجائے اس امید کے جو کہ ابتدائی افراد کو پکڑتا ہے۔</p>\n</div></div>\n<p>یہ باب سیکھنے کے اصولوں کی وضاحت کرتا ہے، نہ کہ فائلنگ ایڈوائس کے طور پر۔ کرپٹو ٹیکس کا قانون سخت ہے اور اب بھی تیار ہو رہا ہے، اور اعداد و شمار سال بہ سال تبدیل ہو سکتے ہیں، اس لیے فائل کرنے سے پہلے کسی قابل چارٹرڈ اکاؤنٹنٹ سے اپنی پوزیشن کی تصدیق کریں۔</p>\n","toc":[{"level":2,"text":"فلیٹ 30 فیصد، جو بھی آپ کا سلیب ہو۔","id":"a-flat-30-percent-whatever-your-slab"},{"level":2,"text":"صرف لاگت کٹوتی ہے۔","id":"only-the-cost-is-deductible"},{"level":2,"text":"ہر فروخت پر 1 فیصد TDS","id":"the-1-percent-tds-on-every-sale"},{"level":2,"text":"سخت ترین اصول: نقصان کہیں نہیں جاتا","id":"the-harshest-rule-losses-go-nowhere"},{"level":2,"text":"کام کی مثال: دو سکے، ایک مشکل سبق","id":"worked-example-two-coins-one-hard-lesson"},{"level":2,"text":"یہ کہاں جاتا ہے: شیڈول VDA","id":"where-it-goes-schedule-vda"}],"imgCount":1,"hasContent":true},"17":{"html":"<p>آخری باب کے بعد، ایک تاجر کو یہ سوچنے پر معاف کیا جا سکتا ہے کہ تمام کرپٹو پر ایک ہی ظالمانہ طریقے سے ٹیکس لگایا گیا ہے: ایک فلیٹ 30%، کوئی خرچ نہیں، نقصان پر کوئی ریلیف نہیں۔ لہذا جب وہی تاجر خود سکے کے بجائے کرپٹو فیوچرز میں لین دین شروع کرتا ہے تو فطری مفروضہ یہ ہے کہ وہاں بھی 30% اصول ان کی پیروی کرتا ہے۔ ایسا نہیں ہو سکتا۔ کرپٹو فیوچرز ٹیکس کی دنیا کے ایک حقیقی طور پر مختلف، اور بہت کم طے شدہ، کونے میں بیٹھتے ہیں، اور یہ باب اس بات کا ایک ایماندارانہ دورہ ہے کہ ہم کیا جانتے ہیں، کیا امکان ہے، اور جو ابھی تک کوئی آپ سے وعدہ نہیں کر سکتا۔</p>\n<p>آئیے پہلی سطر سے واضح ہو جائیں، کیوں کہ یہاں صفائی سے زیادہ ایمانداری اہمیت رکھتی ہے۔ بھارت میں کرپٹو فیوچر کا علاج مکمل طور پر طے نہیں ہوا ہے۔ محکمہ ٹیکس نے واضح رہنمائی جاری نہیں کی ہے، اور تنازعات کی حقیقی گنجائش موجود ہے۔ اس کے بعد کیا احتیاط، عام طور پر پڑھائی جاتی ہے، کوئی ضمانت نہیں، اور آپ کو اسے کسی پیشہ ور کے ساتھ بات چیت کا نقطہ آغاز سمجھنا چاہیے، نہ کہ حتمی جواب کے طور پر۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/taxation/images/diagram-crypto-fno.png\" alt=\"کریپٹو فیوچر مشتق ہیں، سکے کی منتقلی نہیں، لہذا فلیٹ 30% عام طور پر لاگو نہیں ہوتا ہے، لیکن قواعد غیر متزلزل رہتے ہیں۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>کریپٹو فیوچر مشتق ہیں، سکے کی منتقلی نہیں، لہذا فلیٹ 30% عام طور پر لاگو نہیں ہوتا ہے، لیکن قواعد غیر طے شدہ رہتے ہیں۔</figcaption></figure>\n<h2 id=\"futures-are-a-bet-on-price-not-a-coin-you-own\">فیوچر قیمت پر شرط ہیں، نہ کہ آپ کا اپنا کوئی سکہ</h2>\n<p>اس سے شروع کریں کہ ایک کرپٹو مستقبل اصل میں کیا ہے۔ جب آپ مستقبل کی تجارت کرتے ہیں، تو آپ خود سکے خرید یا فروخت نہیں کر رہے ہوتے۔ آپ ایک معاہدہ کر رہے ہیں جس کی قیمت سکے کی قیمت کو ٹریک کرتی ہے۔ آپ کبھی بھی بنیادی اثاثہ کی ملکیت اس طرح نہیں لیتے جیسے آپ اسپاٹ مارکیٹ میں سکہ خریدتے وقت کرتے ہیں۔</p>\n<p>یہ فرق ٹیکس کے لئے پوری بال گیم ہے۔ سیکشن 115BBH، پچھلے باب کا فلیٹ 30% اصول، ورچوئل ڈیجیٹل اثاثہ کی منتقلی کے ارد گرد لکھا گیا ہے۔ ایک کریپٹو مستقبل ایک مشتق ہے، نہ کہ VDA کی منتقلی، لہذا سیکشن 115BBH عام طور پر اس پر لاگو نہیں ہوتا ہے۔ 30% سخت مشینری سکوں کی خرید و فروخت کے لیے بنائی گئی تھی، اور سکے کی قیمت پر ایک معاہدہ، زیادہ تر ریڈنگز میں، ایک مختلف جانور ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>کرپٹو فیوچر مشتق ہیں، سکے کی منتقلی نہیں۔ چونکہ سیکشن 115BBH کے تحت فلیٹ 30% ایک ورچوئل ڈیجیٹل اثاثہ کی منتقلی کے ارد گرد لکھا گیا ہے، یہ عام طور پر مستقبل کے معاہدے تک نہیں پہنچتا ہے۔ یہ مرکزی وجہ ہے کہ کرپٹو فیوچرز کے ساتھ سپاٹ کرپٹو سے مختلف سلوک کیا جاتا ہے، حالانکہ معاملہ تنازعات سے بالاتر نہیں ہے۔</p>\n</div></div>\n<h2 id=\"the-likely-treatment-business-income-at-slab\">ممکنہ علاج: سلیب پر کاروباری آمدنی</h2>\n<p>اگر فلیٹ 30% لاگو نہیں ہوتا ہے، تو کیا کرتا ہے؟ عام پڑھنا یہ ہے کہ کرپٹو فیوچرز سے حاصل ہونے والے منافع کو کاروباری آمدنی کے طور پر سمجھا جاتا ہے، جس پر ایک فلیٹ فگر کے بجائے آپ کے عام سلیب کی شرح پر ٹیکس لگایا جاتا ہے۔ کچھ لوگ زیادہ قدامت پسندانہ نظریہ رکھتے ہیں اور سرگرمی کو قیاس آرائی کے طور پر دیکھتے ہیں، لیکن وسیع سمت ایک ہی ہے: یہ وہ آمدنی ہے جو باقاعدہ سلیب سسٹم میں جاتی ہے۔</p>\n<p>اس کے دو نتائج ہیں جو سپاٹ کریپٹو قواعد سے زیادہ نرم ہیں۔ سب سے پہلے، سلیب کی شرح بہت سے تاجروں کے لیے فلیٹ 30% سے کم ہو سکتی ہے، کیونکہ نچلے بینڈز آپ کی آمدنی کے حصے پر 5%، 10% اور 15% ٹیکس لگاتے ہیں، اس سے پہلے کہ اوپر کی شرح تک پہنچ جائے۔ دوسرا، کیونکہ یہ کاروباری آمدنی ہے، اخراجات اور کم از کم کچھ نقصان کا سیٹ آف دستیاب ہوسکتا ہے، جن میں سے کوئی بھی سپاٹ کریپٹو دنیا میں موجود نہیں ہے۔</p>\n<p>اس بارے میں سوچیں کہ ایک حقیقی تاجر کے لیے ان دو نکات کا کیا مطلب ہے۔ پلیٹ فارم کی رکنیت، ڈیٹا کے اخراجات، اور دیگر حقیقی کاروباری اخراجات مستقبل کی آمدنی کے مقابلے میں کٹوتی کے قابل ہو سکتے ہیں، جہاں سپاٹ کریپٹو قوانین نے انہیں مکمل طور پر نظر انداز کر دیا ہو گا۔ ہارنے والا مہینہ جیتنے والے مہینے پر ٹیکس کو نرم کر سکتا ہے، بجائے اس کے کہ بغیر کسی نشان کے غائب ہو جائے۔ اس طرح سلوک کیا گیا، کرپٹو فیوچر سزا دینے والی جگہ کرپٹو حکومت کے مقابلے میں دوسری مارکیٹوں میں عام ٹریڈنگ کے بہت قریب نظر آتے ہیں۔ ریلیف حقیقی ہے، لیکن یہ مکمل طور پر درجہ بندی کو برقرار رکھنے پر منحصر ہے، جس کا کوئی بھی وعدہ نہیں کر سکتا۔</p>\n<table>\n<thead>\n<tr>\n<th>فیچر</th>\n<th>سپاٹ کریپٹو (سکے خریدنا)</th>\n<th>کرپٹو فیوچرز (عام پڑھنا)</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>حکمرانی کا نظام</td>\n<td>سیکشن 115BBH کے تحت 30% فلیٹ</td>\n<td>عام طور پر سلیب پر کاروباری آمدنی</td>\n</tr>\n<tr>\n<td>اخراجات قابل کٹوتی</td>\n<td>صرف سکے کی قیمت</td>\n<td>کاروباری اخراجات کی اجازت دی جا سکتی ہے۔</td>\n</tr>\n<tr>\n<td>نقصان سیٹ آف</td>\n<td>بالکل اجازت نہیں ہے۔</td>\n<td>کچھ سیٹ آف لاگو ہو سکتا ہے۔</td>\n</tr>\n<tr>\n<td>1% TDS فروخت پر ہے۔</td>\n<td>جی ہاں، دفعہ 194S کے تحت</td>\n<td>نہیں</td>\n</tr>\n</tbody></table>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>اس میں سے کوئی بھی خامی یا ٹیکس ڈاج نہیں ہے۔ یہ ایک سادہ قانونی حقیقت سے نکلتا ہے: مستقبل کا معاہدہ سکہ نہیں ہے۔ لیکن \"عام طور پر سمجھا جاتا ہے\" اس جملے میں حقیقی کام کر رہا ہے۔ جدول میں سازگار نکات ممکنہ پوزیشن ہیں، کوئی طے شدہ نہیں، یہی وجہ ہے کہ اس باب کا اختتامی حصہ اتنا ہی اہمیت رکھتا ہے جتنا کہ اس باب کا۔</p>\n</div></div>\n<h2 id=\"no-1-percent-tds-here-but-a-serious-offshore-problem\">یہاں کوئی 1 فیصد TDS نہیں، لیکن ایک سنگین آف شور مسئلہ</h2>\n<p>ایک عملی فرق واضح طور پر بیان کرنے کے قابل ہے۔ سیکشن 194S کے تحت 1% TDS، جو سکے کی ہر جگہ فروخت پر کاٹتا ہے، کرپٹو فیوچرز پر لاگو نہیں ہوتا ہے۔ کرپٹو فیوچر ٹریڈ پر کوئی 1% TDS نہیں ہے، کیونکہ، دوبارہ، منسلک کرنے کے لیے VDA کی کوئی منتقلی نہیں ہے۔</p>\n<p>بڑا مسئلہ ٹیکس کا نہیں ہے، یہ فارن ایکسچینج کا قانون ہے۔ ہندوستان سے باہر کے پلیٹ فارم پر اکاؤنٹ کو فنڈ دینے کا مطلب ہے کہ لبرلائزڈ ریمیٹنس اسکیم کے تحت بیرون ملک رقم بھیجنا، اور یہاں بہت سے تاجروں کو ایک جال نظر آتا ہے: LRS قوانین واضح طور پر ترسیلات زر کی ممانعت کرتے ہیں جو سمندر پار ایکسچینجز یا ہم منصبوں کو مارجن یا مارجن کال کی نوعیت میں ہوتے ہیں، اور وہ مستقبل میں ترسیلات زر یا آپشنز کی اجازت نہیں دیتے۔ دوسرے لفظوں میں، کرپٹو فیوچر مارجن کو فنڈ دینے کے لیے بیرون ملک رقم بھیجنا عام طور پر پہلی جگہ LRS کے استعمال کی اجازت نہیں ہے، اس سے قطع نظر کہ آپ کسی بھی ٹیکس سے فائدہ اٹھا سکتے ہیں۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>یہ مت سمجھیں کہ آف شور کریپٹو فیوچر ٹھیک ہے جب تک آپ ٹیکس ادا کرتے ہیں۔ RBI کی لبرلائزڈ ریمیٹینس اسکیم کے تحت، سمندر پار ایکسچینجز کو مارجن یا مارجن کالز، اور بیرون ملک مشتقات کے لیے ترسیلات ممنوع ہیں۔ اس لیے آف شور کریپٹو فیوچر اکاؤنٹ کو فنڈ دینا غیر ملکی زر مبادلہ کے قانون (FEMA) کی خلاف ورزی کر سکتا ہے، جو کہ انکم ٹیکس سے الگ اور سنگین معاملہ ہے۔ یہ ان شعبوں میں سے ایک ہے جہاں صحیح قدم یہ ہے کہ آپ کام کرنے سے پہلے کسی اہل پیشہ ور سے بات کریں، اس کے بعد نہیں۔</p>\n</div></div>\n<p>یہاں تک کہ جہاں رقم کسی اجازت شدہ مقصد کے لیے بیرون ملک منتقل ہوتی ہے، 20% TCS جو کہ ایک سال میں 7 لاکھ روپے سے زیادہ کی ترسیلات زر پر لاگو ہوتا ہے، آپ کے PAN کے خلاف ایک واضح، قابل شناخت نقش چھوڑتا ہے، جو بعد میں کریڈٹ کے طور پر دوبارہ حاصل کیا جاسکتا ہے۔ FEMA پابندی، غیر طے شدہ انکم ٹیکس ٹریٹمنٹ، اور اس نظر آنے والی منی ٹریل کے درمیان، ایماندارانہ نتیجہ آسان ہے: یہ بازار کا کوئی گوشہ نہیں ہے کہ اتفاق سے گھوم جائے۔</p>\n<h2 id=\"worked-example-how-the-bill-can-differ\">کام کی مثال: بل کیسے مختلف ہو سکتا ہے۔</h2>\n<p>نمبر داؤ کو ٹھوس بناتے ہیں۔ فرض کریں کہ ایک تاجر ایک سال میں کرپٹو فیوچرز پر 3,00,000 کا منافع کماتا ہے، اور مثال کے طور پر فرض کریں کہ یہ منافع ان کی دوسری آمدنی کے اوپر 20% سلیب بینڈ میں آتا ہے۔</p>\n<p>اگر کرپٹو فیوچرز پر اسپاٹ کرپٹو کی طرح 30% فلیٹ کے تحت ٹیکس لگایا گیا تو ٹیکس 3,00,000 کا 30% ہوگا، جو کہ 90,000 ہے، اور سیس بھی۔ عام مطالعہ کے تحت، جیسا کہ کاروباری آمدنی پر 20% سلیب کی شرح سے ٹیکس لگایا جاتا ہے، اس سلائس پر ٹیکس 3,00,000 کا تقریباً 20% ہوگا، جو کہ 60,000 ہے، علاوہ سیس بھی۔ اس ایک اعداد و شمار پر یہ تقریباً 30,000 کا فرق ہے، اس سے پہلے کہ آپ اخراجات اور نقصان کے سیٹ آف کو بھی شمار کریں جس کی کاروباری علاج اجازت دے سکتا ہے لیکن سپاٹ کریپٹو منع کرتا ہے۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>کرپٹو فیوچر منافع 3,00,000۔ فلیٹ 30% پر اسپاٹ کرپٹو کے طور پر سمجھا جاتا ہے، ٹیکس 90,000 پلس سیس ہوگا۔ کاروباری آمدنی کو 20% سلیب بینڈ میں گرنے کے طور پر سمجھا جاتا ہے، ٹیکس تقریباً 60,000 پلس سیس ہوگا، جس میں تقریباً 30,000 کی بچت ہوگی، جس میں حقیقی اخراجات کو کم کرنے کا امکان ہے۔ کیچ یہ ہے کہ ہلکا نتیجہ اس درجہ بندی پر منحصر ہے جس کی ٹیکس ڈیپارٹمنٹ نے باضابطہ طور پر تصدیق نہیں کی ہے۔ نمبر حقیقی ہے، لیکن اس کے پیچھے غیر یقینی صورتحال بھی ہے۔</p>\n</div></div>\n<p>مثال کی بات یہ نہیں ہے کہ کم بل کا جشن منایا جائے۔ یہ ظاہر کرنا ہے کہ درجہ بندی درست ہونے کے قابل کیوں ہے، اور حمایت کے بغیر اپنے حق میں اندازہ لگانا کیوں خطرناک ہے۔ اسی 3,00,000 پر مادی طور پر مختلف طریقوں سے ٹیکس لگایا جا سکتا ہے اس سوال کی بنیاد پر جس کا ابھی تک مکمل جواب نہیں دیا گیا ہے۔</p>\n<h2 id=\"the-honest-part-the-rules-are-unsettled\">ایماندار حصہ: قواعد غیر آباد ہیں۔</h2>\n<p>اب سب سے اہم سیکشن، اور اس کی وجہ یہ باب دوسروں سے زیادہ محتاط ہے۔ کرپٹو فیوچرز کا علاج ایک گرے ایریا ہے۔ محکمہ ٹیکس نے اس بارے میں واضح، مخصوص رہنمائی نہیں دی ہے اور جہاں قانون خاموش ہے وہاں معقول لوگ اور معقول ٹیکس افسران اختلاف کر سکتے ہیں۔ اس کا مطلب ہے کہ قانونی چارہ جوئی کا حقیقی خطرہ ہے: آپ کی نیک نیتی کے ساتھ جو موقف اختیار کیا جاتا ہے اس پر سوال اٹھایا جا سکتا ہے، اور آپ کو اس کا دفاع کرنا پڑ سکتا ہے۔</p>\n<p>آپ اس غیر یقینی صورتحال کو دور نہیں کر سکتے، لیکن آپ خود کو اس سے بچا سکتے ہیں، اور تحفظ زیادہ تر نظم و ضبط اور ریکارڈ کے بارے میں ہے۔</p>\n<ul>\n<li>ہر تجارت، ہر معاہدے، اور ہر ترسیل کا مکمل ریکارڈ رکھیں، بشمول LRS TCS آپ کے PAN کے خلاف جمع کیے گئے ہیں۔</li>\n<li>کسی بھی اخراجات کا ثبوت رکھیں جس کا آپ کسی کاروباری علاج کے تحت دعوی کرنا چاہتے ہیں۔</li>\n<li>یہ مت سمجھیں کہ سب سے زیادہ سازگار پڑھنا خود بخود محفوظ ہے۔ دستاویز کریں کہ آپ نے اپنی پوزیشن کیوں لی۔</li>\n<li>آف شور پلیٹ فارم کی سرگرمی کو مکمل طور پر نظر آنے والی سمجھیں، کیونکہ ترسیلات زر کی وجہ سے ایسا ہوتا ہے۔</li>\n<li>فائل کرنے سے پہلے ایک چارٹرڈ اکاؤنٹنٹ کو شامل کریں، کوئی سوال آنے کے بعد نہیں۔ یہ بالکل وہی صورتحال ہے جس کے لیے پیشہ ورانہ مشورہ موجود ہے۔</li>\n</ul>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>جب قواعد غیر طے شدہ ہوں، جیتنے والا اقدام ہوشیار ترین تشریح تلاش کرنا نہیں ہے، یہ اس تاجر کا ہے جس کے ریکارڈ اتنے صاف ہوں کہ کسی بھی معقول موقف کی وضاحت اور تائید کی جا سکے۔ آپ کنٹرول نہیں کر سکتے کہ قانون کیسے طے کرتا ہے۔ آپ کنٹرول کر سکتے ہیں کہ آیا آپ نے سب کچھ دستاویزی کیا، ہر چیز کا اعلان کیا، اور مشورہ لیا۔ ایسا کریں، اور سرمئی علاقہ بہت کم خوفناک ہو جاتا ہے۔</p>\n</div></div>\n<p>یہ باب ایک حقیقی طور پر غیر آباد علاقے کی وضاحت کرتا ہے اور یہ صرف تعلیم کے لیے ہے، ٹیکس کے مشورے کے لیے نہیں۔ چونکہ کرپٹو فیوچرز کے قواعد بدل سکتے ہیں اور ان کی مختلف تشریح کی جا سکتی ہے، اس لیے اپنی فائلنگ کے لیے اس پڑھنے پر بھروسہ نہ کریں۔ ایک قابل چارٹرڈ اکاؤنٹنٹ کے ساتھ بیٹھیں، اپنی مخصوص تجارتوں کو دیکھیں، اور مل کر اپنی پوزیشن کا فیصلہ کریں۔</p>\n","toc":[{"level":2,"text":"فیوچر قیمت پر شرط ہیں، نہ کہ آپ کا اپنا کوئی سکہ","id":"futures-are-a-bet-on-price-not-a-coin-you-own"},{"level":2,"text":"ممکنہ علاج: سلیب پر کاروباری آمدنی","id":"the-likely-treatment-business-income-at-slab"},{"level":2,"text":"یہاں کوئی 1 فیصد TDS نہیں، لیکن ایک سنگین آف شور مسئلہ","id":"no-1-percent-tds-here-but-a-serious-offshore-problem"},{"level":2,"text":"کام کی مثال: بل کیسے مختلف ہو سکتا ہے۔","id":"worked-example-how-the-bill-can-differ"},{"level":2,"text":"ایماندار حصہ: قواعد غیر آباد ہیں۔","id":"the-honest-part-the-rules-are-unsettled"}],"imgCount":1,"hasContent":true},"18":{"html":"<p>دو دوستوں انجلی اور وکرم کی تصویر بنائیں۔ دونوں نے پچھلے سال بازاروں میں پیسہ کمایا، دونوں نیک نیتی سے اپنے ٹیکس جمع کروانے کے لیے بیٹھ گئے، اور دونوں نے اپنے اعداد و شمار انکم ٹیکس کی ویب سائٹ پر ایک فارم میں ٹائپ کیے تھے۔ تین ماہ بعد، ان میں سے صرف ایک کو نوٹس موصول ہوا۔ فرق یہ نہیں تھا کہ انہوں نے کتنا کمایا، اور یہ ایمانداری کا نہیں تھا۔ یہ صفحہ کے بالکل اوپر ایک واحد انتخاب تھا: انہوں نے کون ساITRفارم منتخب کیا۔</p>\n<p>آپ کے ITR فارم کا انتخاب ایک بورنگ انتظامی قدم کی طرح لگتا ہے، جس طرح سے آپ \"حقیقی\" نمبروں تک پہنچنے کے لیے جلدی کرتے ہیں۔ لیکن یہ ٹیکس کے چند فیصلوں میں سے ایک ہے جہاں ایک غلط کلک، خود بخود، آپ کی پوری واپسی کو غلط بنا سکتا ہے۔ اچھی خبر یہ ہے کہ تاجروں اور سرمایہ کاروں کے لیے اصول نظر آنے سے کہیں زیادہ آسان ہے۔ ایک بار جب آپ اپنے آپ کو چار شکلوں کے ایک چھوٹے سے نقشے پر رکھ سکتے ہیں، تو آپ کو بالکل پتہ چل جائے گا کہ آپ کا تعلق کہاں سے ہے، اور کیوں۔</p>\n<h2 id=\"the-four-forms-on-one-map\">ایک نقشے پر چار شکلیں۔</h2>\n<p>چار انکم ٹیکس ریٹرن فارم ہیں جو ایک فرد کو ملنے کا امکان ہے۔ ہر ایک مختلف قسم کے ٹیکس دہندگان کے لیے بنایا گیا ہے۔ ان کے بارے میں چار دروازوں کے طور پر سوچو، اور آپ کا کام صحیح راستے سے چلنا ہے.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/taxation/images/diagram-itr-forms.png\" alt=\"چار ITR ایک سادہ نقشے کے طور پر بنتے ہیں، جس میں دکھایا گیا ہے کہ ہر ایک کس قسم کے تاجر یا سرمایہ کار کے لیے بنایا گیا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>چار ITR ایک سادہ نقشے کے طور پر بنتے ہیں، جس میں دکھایا گیا ہے کہ ہر ایک کس قسم کے تاجر یا سرمایہ کار کے لیے بنایا گیا ہے۔</figcaption></figure>\n<table>\n<thead>\n<tr>\n<th>آپ کون ہیں۔</th>\n<th>فارم</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>تنخواہ اور ایک سادہ سرمایہ کار، چھوٹی آمدنی</td>\n<td>ITR-1 (سہج)، لیکن NOT کاروبار یا F&amp;O کے لیے</td>\n</tr>\n<tr>\n<td>کیپٹل گین کے ساتھ سرمایہ کار، غیر ملکی اثاثے، یا کرپٹو بطور کیپٹل گین</td>\n<td>ITR-2</td>\n</tr>\n<tr>\n<td>F&amp;O، انٹرا ڈے، یا بطور کاروبار تجارت؛ کرپٹو بطور کاروبار</td>\n<td>ITR-3 (زیادہ تر تاجر)</td>\n</tr>\n<tr>\n<td>محدود اہل مقدمات میں فرضی ٹیکس</td>\n<td>ITR-4 (سگم)</td>\n</tr>\n</tbody></table>\n<p>اس پورے باب میں واحد سب سے مفید جملہ یہ ہے: <strong>زیادہ تر فعال تاجر ITR-3 پر ختم ہوتے ہیں۔</strong> اگر آپ فیوچرز اور آپشنز کی تجارت کرتے ہیں، یا آپ انٹرا ڈے کرتے ہیں، یا آپ ٹریڈنگ کو کاروبار سمجھتے ہیں، تو یہ آپ کا دروازہ ہے۔ اس باب میں باقی سب کچھ واقعی اس کی تصدیق کرنے میں آپ کی مدد کرنے کے بارے میں ہے، اور یہ سمجھنے کے بارے میں ہے کہ آسان شکلیں آپ کے لیے کیوں موزوں نہیں ہوں گی۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>فارم اس بارے میں نہیں ہے کہ آپ نے کتنا کمایا۔ یہ اس بارے میں ہے کہ آپ نے کتنی آمدنی حاصل کی۔ تنخواہ، کیپیٹل گین، اور کاروباری آمدنی ہر ایک کا اپنا گھر ہوتا ہے، اور آپ جو فارم منتخب کرتے ہیں اس کا اتنا وسیع ہونا ضروری ہے کہ آپ کی ہر قسم کی آمدنی ہو سکے۔</p>\n</div></div>\n<h2 id=\"itr-1-and-itr-4-the-simple-forms-and-their-limits\">ITR-1 اور ITR-4، سادہ شکلیں (اور ان کی حدود)</h2>\n<p><strong>ITR-1، جسے سہج بھی کہا جاتا ہے،</strong> سب سے آسان شکل ہے. یہ ایک تنخواہ دار شخص کے لیے ہے جس کی کچھ سود کی آمدنی بھی ہے اور شاید ایک گھر کی جائیداد بھی، جس کی کل آمدنی معمولی ہے۔ ایک خالص بچت کرنے والا جو پیسہ بینک میں رکھتا ہے اور فکسڈ ڈپازٹ، بغیر کسی شیئر کی تجارت کے، یہاں آرام سے رہتا ہے۔</p>\n<p>جال یہ ہے کہ ITR-1 کبھی بھی بازاروں کے لیے ڈیزائن نہیں کیا گیا تھا۔ جس لمحے آپ کو حصص یا میوچل فنڈز کی فروخت سے کیپیٹل گین حاصل ہوتا ہے، ITR-1 صحیح شکل اختیار کرنا بند کر دیتا ہے، کیونکہ اس میں ان کی اطلاع دینے کی کوئی جگہ نہیں ہے۔ اور یہ بالکل کاروباری آمدنی کو روک نہیں سکتا، جو کہ F&amp;O اور انٹرا ڈے کی پیداوار ہے۔ لہذا اگر آپ نے کوئی سنجیدہ تجارت کی ہے تو، ITR-1 غلط دروازہ ہے، فل اسٹاپ۔</p>\n<p><strong>ITR-4، جسے سوگم بھی کہا جاتا ہے،</strong> فرضی ٹیکسیشن اسکیم کے لیے بنایا گیا ہے، جہاں چھوٹے کاروبار اور پیشہ ور افراد پوری کتابوں کو برقرار رکھنے کے بجائے ٹرن اوور کے ایک مقررہ فیصد کے طور پر آمدنی کا اعلان کرتے ہیں۔ یہ فرضی اصولوں کے تحت، ایک چھوٹے دکاندار یا ایک آزاد پیشہ ور کے لیے موزوں ہے۔ تاجروں کے لیے یہ صرف محدود اہل معاملات میں لاگو ہوتا ہے، اور زیادہ تر فعال F&amp;O تاجر اس میں صفائی کے ساتھ فٹ نہیں ہوتے ہیں۔ چارٹرڈ اکاؤنٹنٹ کے ساتھ بات چیت کرنے کے لیے ITR-4 کو ایک خاص کیس کے طور پر سمجھیں، نہ کہ آپ کی ڈیفالٹ۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>اگر آپ نے F&amp;O کی تجارت کی یا سال کے دوران ایک بار بھی انٹرا ڈے کیا اور آپ ITR-1 تک پہنچ گئے، تو آپ نے تقریباً یقینی طور پر غلط فارم کا انتخاب کیا ہے۔ ITR-1 میں سرمائے کے منافع کے لیے کوئی گنجائش نہیں ہے اور نہ ہی کاروباری آمدنی کے لیے کوئی گنجائش ہے۔ یہ پہلے مرحلے میں سب سے عام ابتدائی غلطی ہے۔</p>\n</div></div>\n<h2 id=\"itr-2-the-investor-s-form\">ITR-2، سرمایہ کار کی شکل</h2>\n<p><strong>ITR-2</strong> سرمایہ کار کے لیے فارم ہے جو تجارتی کاروبار نہیں چلا رہا ہے۔ اگر آپ کی مارکیٹ کی سرگرمی حصص اور میوچل فنڈز خرید رہی ہے اور انہیں ہولڈ کر رہی ہے، تاکہ آپ کا منافع کاروباری آمدنی کے بجائے کیپیٹل گین ہو، ITR-2 عام طور پر وہ جگہ ہے جہاں آپ کا تعلق ہے۔</p>\n<p>ITR-2 وسیع ہے۔ اس میں تنخواہ، ایک سے زیادہ گھر کی جائیداد، اور قلیل مدتی اور طویل مدتی دونوں طرح کے سرمائے کے فوائد ہو سکتے ہیں۔ اہم طور پر، یہ وہ شکل بھی ہے جو لے جاتی ہے۔ <strong>شیڈول FA</strong>، وہ سیکشن جہاں ایک رہائشی کو غیر ملکی اثاثوں کو ظاہر کرنا چاہیے جیسے کہ US شیئرز اور ETFs، اور <strong>شیڈول VDA</strong>، جہاں کرپٹو کی اطلاع دی جاتی ہے جب آپ اسے کیپیٹل گین کے طور پر دیکھ رہے ہوتے ہیں۔ لہٰذا پرسکون طویل مدتی سرمایہ کار جو کچھ ہندوستانی اسٹاکس، چند US شیئرز، اور سرمایہ کاری کے طور پر رکھے گئے ایک چھوٹے سے کریپٹو کا مالک ہے ITR-2 پر سب کچھ کرسکتا ہے۔</p>\n<p>ایک فوری ٹیسٹ آپ کو اپنے آپ کو رکھنے میں مدد کرتا ہے۔ پوچھیں: \"کیا میں ایک سرمایہ کار ہوں جو کبھی کبھار فروخت کرتا ہوں، یا میں ایک تاجر ہوں جو کوئی سرگرمی چلا رہا ہوں؟\" ڈیلیوری کے حصص اور ان کے فوائد کے لیے رکھے گئے میوچل فنڈز کیپٹل گین ہیں، اور وہ ITR-2 علاقہ ہے۔ F&amp;O اور انٹرا ڈے کاروباری آمدنی ہیں، اور یہ آپ کو ITR-3 کی طرف دھکیلتا ہے۔</p>\n<p>ایک چیز جو ITR-2 نہیں کر سکتا وہ ہے کاروباری آمدنی۔ اس میں \"کاروبار یا پیشے کے منافع اور فوائد\" کے لیے کوئی سیکشن نہیں ہے۔ اور یہ بالکل لائن F&amp;O اور انٹرا ڈے کراس ہے۔ جس لمحے آپ کی سرگرمی کاروباری آمدنی بن جاتی ہے، ITR-2 اب کافی نہیں رہے گا، اور آپ ITR-3 تک چلے جائیں گے۔</p>\n<h2 id=\"itr-3-the-trader-s-home\">ITR-3، تاجر کا گھر</h2>\n<p><strong>ITR-3</strong> وہ فارم ہے جسے سب سے زیادہ فعال تاجر استعمال کرتے ہیں، اور ایک بار جب آپ سمجھ جاتے ہیں کہ کیوں، پورا نقشہ اپنی جگہ پر کلک کرتا ہے۔ ITR-3 واحد انفرادی شکل ہے جو رپورٹ کر سکتی ہے۔ <strong>کاروباری آمدنی</strong>، وہ بالٹی جس میں F&amp;O اور انٹرا ڈے ہوتا ہے۔</p>\n<p>کورس میں پہلے کی درجہ بندی کو یاد رکھیں۔ مستقبل اور اختیارات غیر قیاس آرائی پر مبنی کاروباری آمدنی ہیں۔ انٹرا ڈے ایکویٹی قیاس آرائی پر مبنی کاروباری آمدنی ہے۔ دونوں کو \"کاروبار یا پیشے کے منافع اور فوائد\" کے تحت رپورٹ کیا گیا ہے اور وہ حصہ صرف ITR-3 میں رہتا ہے۔ لہذا اگر آپ مشتقات کی تجارت کرتے ہیں یا انٹرا ڈے کرتے ہیں تو، ITR-3 اختیاری نہیں ہے، یہ تعریف کے لحاظ سے درست شکل ہے۔</p>\n<p>جو چیز ITR-3 کو اتنا طاقتور بناتی ہے وہ یہ ہے کہ یہ چاروں میں سب سے زیادہ مکمل ہے۔ اس میں وہ سب کچھ ہو سکتا ہے جو دوسری شکلوں میں ہو سکتی ہے اور پھر کاروبار کی آمدنی سب سے اوپر شامل کر سکتی ہے۔ تنخواہ، گھر کی جائیداد، آپ کی ڈیلیوری کی سرمایہ کاری سے حاصل ہونے والا سرمایہ، شیڈول FA میں غیر ملکی اثاثے، شیڈول VDA میں کرپٹو چاہے کیپیٹل گین کے طور پر یا کاروبار کے طور پر، اور آپ کی F&amp;O اور انٹرا ڈے کاروباری آمدنی، سب ایک ہی واپسی پر۔ یہی وجہ ہے کہ مصروف شخص جو سرمایہ کاری اور تجارت دونوں کرتا ہے تقریباً ہمیشہ یہاں آتا ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>اگر آپ F&amp;O کی تجارت کرتے ہیں اور آپ پرانے ٹیکس نظام کا انتخاب بھی کرتے ہیں، تو فارم 10-IEA۔ کو یاد رکھیں۔ چونکہ آپ کی کاروباری آمدنی ہے، اس لیے پہلے سے طے شدہ نئے نظام سے آپٹ آؤٹ کرنے کے لیے سیکشن 139(1) کے تحت مقررہ تاریخ کے اندر فارم 10-IEA‎ کی ضرورت ہوتی ہے۔ اسے یاد کرنا آسان ہے، لہذا فائل کرنے سے پہلے اسے جھنڈا لگائیں۔</p>\n</div></div>\n<h2 id=\"when-you-both-invest-and-trade\">جب آپ سرمایہ کاری اور تجارت دونوں کرتے ہیں۔</h2>\n<p>یہاں وہ صورتحال ہے جو زیادہ تر لوگوں کو الجھا دیتی ہے، اور یہ آپ کے خیال سے کہیں زیادہ عام ہے۔ آپ کی تنخواہ ہے۔ آپ کے پاس طویل مدتی کے لیے کچھ حصص بھی ہوتے ہیں، جو آپ کو فروخت کرتے وقت کیپٹل نفع دیتا ہے۔ اور اس طرف، آپ کچھ F&amp;O لاٹوں کی تجارت کرتے ہیں، جو کہ کاروباری آمدنی ہے۔ ایک سال میں تین مختلف قسم کی آمدنی۔ کون سی شکل؟</p>\n<p>ایک بار جب آپ اسے دیکھتے ہیں تو جواب تسلی بخش ہے: <strong>اسی ریٹرن پر آپ کو کیپیٹل گینز AND کاروباری آمدنی ہو سکتی ہے۔</strong> آپ دو بار فائل نہیں کرتے ہیں اور آپ ان کے درمیان انتخاب نہیں کرتے ہیں۔ ITR-3 دونوں کو ایک ساتھ لے جانے کے لیے بنایا گیا ہے۔ آپ کی طویل مدتی سرمایہ کاری کیپٹل گین شیڈول میں جاتی ہے، آپ کا F&amp;O کاروبار کے شیڈول میں، تنخواہ کے حصے میں آپ کی تنخواہ، اور یہ سب ایک فارم پر کل آمدنی میں اضافہ کرتا ہے۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p><strong>وکرم سے ملو۔</strong> سال کے دوران اس نے تنخواہ حاصل کی، کچھ حصص بیچے جو اس نے دو سال سے رکھے تھے اور 80,000 روپے کا طویل مدتی سرمایہ حاصل کیا، اور 40,000 روپے کے چھوٹے کاروبار کے منافع کے لیے مستقبل اور اختیارات کا کاروبار کیا۔</p>\n<p>وہ ITR-1 کا استعمال نہیں کر سکتا، کیونکہ اس میں نہ تو سرمایہ حاصل ہوتا ہے اور نہ ہی کاروباری آمدنی۔ وہ ITR-2 کا استعمال نہیں کر سکتا، کیونکہ اگرچہ اس میں اس کی تنخواہ اور اس کے سرمائے کے فوائد ہیں، لیکن اس میں F&amp;O کاروباری منافع کی کوئی گنجائش نہیں ہے۔ F&amp;O فیصلہ کن عنصر ہے۔ وکرم فائلیں۔ <strong>ITR-3</strong>جہاں اس کی تنخواہ، اس کا 80,000 کیپٹل گین، اور اس کا 40,000 کاروباری منافع سب ایک ساتھ آرام سے بیٹھتے ہیں۔ ایک شکل، تینوں قسم کی آمدنی۔</p>\n<p>اس کے برعکس، اس کی دوست انجلی نے صرف ایک سرمایہ کار کے طور پر شیئرز رکھے تھے اور اس نے کبھی F&amp;O کو نہیں چھوا، اس لیے اس کا کیپیٹل گین ITR-2 میں صاف طور پر فٹ بیٹھتا ہے۔ ایک ہی بازار، مختلف دروازے، کیونکہ آمدنی کی قسم مختلف تھی۔</p>\n</div></div>\n<p>سادہ اصول جو اس سے نکلتا ہے: <strong>اپنی آمدنی کی سب سے زیادہ مانگ کے مطابق فارم چنیں۔</strong> اگر آپ کے سال کا کوئی حصہ کاروباری آمدنی، F&amp;O یا انٹرا ڈے ہے، تو آپ کو ITR-3 کی ضرورت ہے، چاہے آپ کی زیادہ تر رقم تنخواہ یا سرمایہ کاری سے آئی ہو۔ سب سے زیادہ مطالبہ والی بالٹی فارم کا تعین کرتی ہے۔</p>\n<h2 id=\"why-the-wrong-form-makes-a-return-defective\">غلط فارم واپسی کو خراب کیوں بناتا ہے۔</h2>\n<p>تو اصل میں کسی کے ساتھ کیا ہوتا ہے جو غلط دروازہ چنتا ہے؟ یہیں سے انجلی اور وکرم کی کہانی واپس آتی ہے۔ غلط فارم پر جمع کرائی گئی واپسی کو سمجھا جا سکتا ہے۔ <strong>عیب دار</strong> محکمہ کے تحت ڈیفیکٹو ریٹرن نوٹس جاری کر سکتا ہے۔ <strong>دفعہ 139(9)</strong>آپ کو بتانا کہ آپ نے جو فارم استعمال کیا ہے وہ آپ کی رپورٹ کردہ آمدنی سے میل نہیں کھاتا، اور آپ کو اسے ٹھیک کرنے کے لیے ایک ونڈو دے رہا ہے۔</p>\n<p>ایک عیب دار واپسی دنیا کا خاتمہ نہیں ہے، لیکن یہ ایک سر درد ہے جس کی آپ کو ضرورت نہیں ہے۔ اگر آپ نوٹس کو نظر انداز کرتے ہیں یا ونڈو سے محروم رہتے ہیں، تو ریٹرن کو ایسا سمجھا جا سکتا ہے جیسے یہ کبھی فائل ہی نہیں کیا گیا تھا۔ اور ایک واپسی جسے فائل نہ ہونے کے طور پر سمجھا جاتا ہے وہ ایک تاجر کے پاس موجود سب سے قیمتی چیزوں میں سے ایک کھو دیتا ہے: نقصان کو آگے بڑھانے کی صلاحیت۔ اگر آپ نے غلط فارم پر F&amp;O کے نقصان کی اطلاع دی ہے اور واپسی غلط ہو جاتی ہے، تو آپ اس نقصان کو مستقبل کے منافع کے خلاف سیٹ کرنے کا حق کھو سکتے ہیں، جو بالکل وہی تحفظ ہے جس کے لیے آپ نے پہلی جگہ دائر کی تھی۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>غلط فارم کوئی چھوٹی ٹائپو نہیں ہے، یہ سیکشن 139(9) کے تحت پوری فائلنگ کو خراب کر سکتا ہے۔ سب سے زیادہ وجہ F&amp;O کو ITR-3 پر کاروباری آمدنی کے بجائے ITR-2 پر کیپیٹل گین کے طور پر رپورٹ کرنا ہے۔ F&amp;O کاروباری آمدنی ہے۔ اگر آپ کے پاس ہے تو، ITR-3 آپ کا فارم ہے۔</p>\n</div></div>\n<p>یہ سب ایک ساتھ رکھیں اور نقشہ اتنا چھوٹا ہے کہ آپ کے ذہن میں رکھا جائے۔ ایک خالص تنخواہ دار سیور جس میں مارکیٹ کی کوئی سرگرمی نہیں ہے ITR-1 استعمال کرتا ہے۔ سرمایہ حاصل کرنے والا سرمایہ کار، غیر ملکی حصص، یا کرپٹو بطور سرمایہ کاری رکھتا ہے ITR-2 استعمال کرتا ہے۔ F&amp;O، انٹرا ڈے، یا کاروبار کے طور پر تجارت کرنے والا کوئی بھی، جو سب سے زیادہ فعال تاجر ہے، ITR-3 استعمال کرتا ہے، اور ITR-3 خوشی سے اپنی سرمایہ کاری بھی کرتا ہے۔ ITR-4 ایک پیشہ ور کے ساتھ اٹھانے کے لیے ایک محدود فرضی معاملہ ہے۔ اپنی انتہائی مطلوبہ آمدنی کے مطابق انتخاب کریں، اور آپ پہلی بار دائیں دروازے سے گزرتے ہیں۔</p>\n<p>یہ باب صرف سیکھنے کے لیے ہے اور ٹیکس کا مشورہ نہیں ہے۔ ٹیکس فارم، نظام الاوقات، اور قواعد سال بہ سال بدلتے رہتے ہیں، اس لیے 2026-27 AY کے لیے فائل کرنے سے پہلے براہ کرم ایک قابل چارٹرڈ اکاؤنٹنٹ سے اپنے درست فارم کی تصدیق کریں۔</p>\n","toc":[{"level":2,"text":"ایک نقشے پر چار شکلیں۔","id":"the-four-forms-on-one-map"},{"level":2,"text":"ITR-1 اور ITR-4، سادہ شکلیں (اور ان کی حدود)","id":"itr-1-and-itr-4-the-simple-forms-and-their-limits"},{"level":2,"text":"ITR-2، سرمایہ کار کی شکل","id":"itr-2-the-investor-s-form"},{"level":2,"text":"ITR-3، تاجر کا گھر","id":"itr-3-the-trader-s-home"},{"level":2,"text":"جب آپ سرمایہ کاری اور تجارت دونوں کرتے ہیں۔","id":"when-you-both-invest-and-trade"},{"level":2,"text":"غلط فارم واپسی کو خراب کیوں بناتا ہے۔","id":"why-the-wrong-form-makes-a-return-defective"}],"imgCount":1,"hasContent":true},"19":{"html":"<p>زیادہ تر تاجروں کے لیے، ٹیکس ایک ایسی چیز ہے جو گھبراہٹ میں ہوتا ہے۔ جولائی آتا ہے، فائل کرنے کی آخری تاریخ ختم ہوتی ہے، اور اچانک آپ ایسے بیانات کی تلاش میں ہوتے ہیں جنہیں آپ نے کبھی محفوظ نہیں کیا، گیارہ مہینے پہلے کی تجارت کو یاد کرنے کی کوشش کرتے ہیں، اور دعا کرتے ہیں کہ تعداد میں اضافہ ہو۔ یہ دباؤ ہے، یہ غلطی کا شکار ہے، اور یہ مکمل طور پر قابل گریز ہے۔</p>\n<p>وہ تاجر جو فائل کرنے کے وقت پرسکون رہتے ہیں وہ زیادہ ذہین یا امیر نہیں ہوتے۔ انہوں نے ٹیکس کو واقعہ کی بجائے عادت میں بدل دیا۔ وہ ایک ہلکا پھلکا، سال بھر کا معمول رکھتے ہیں، تاکہ جب آخری تاریخ آتی ہے، فائلنگ صرف اس رقم کا جواب چھاپنا ہے جو وہ سارا سال خاموشی سے کام کرتے رہے ہیں۔ یہ آخری باب آپ کو وہ روٹین فراہم کرتا ہے: ایک ماہ بہ ماہ تال، مصالحت کے لیے دستاویزات، کسی پیشہ ور کو کب کال کرنا ہے، اور جمع کرانے کو دبانے سے پہلے چلانے کے لیے ایک دوستانہ چیک لسٹ۔ آئیے ٹیکس کو سالانہ خوف سے ایک ایسے پس منظر کے کام میں بدل دیتے ہیں جسے آپ بمشکل محسوس کرتے ہیں۔</p>\n<h2 id=\"the-year-round-mindset\">سال بھر کی ذہنیت</h2>\n<p>سارا راز یہ ہے: ایک تاجر کا ٹیکس ریٹرن ان ریکارڈوں سے بنایا جاتا ہے جو صرف اس وقت موجود ہوتا ہے جب سال ہو رہا ہو۔ آپ کا ٹرن اوور، آپ کے اخراجات، آپ کا ایڈوانس ٹیکس، آپ کی غیر ملکی ہولڈنگز، ان سب کو اس لمحے میں پکڑنا آسان ہے اور بعد میں دوبارہ تشکیل دینا تکلیف دہ ہے۔ لہذا مقصد یہ نہیں ہے کہ سال میں ایک بار \"اپنے ٹیکس\" کریں۔ یہ ہر سہ ماہی میں آپ کے ریکارڈ کو تازہ رکھنے کے لیے چند منٹ گزارنا ہے، اس لیے واپسی تقریباً خود لکھتی ہے۔</p>\n<p>واقعی صرف مٹھی بھر حرکت پذیر حصے ہیں۔ آپ اپنے بروکر سے اپنے نمبر لے لیتے ہیں، اگر آپ پر واجب الادا ہے تو آپ ایڈوانس ٹیکس وقت پر ادا کرتے ہیں، آپ اپنے ثبوت ایک جگہ پر رکھتے ہیں، آپ جو محکمہ پہلے سے جانتا ہے اس کے خلاف آپ صلح کرتے ہیں، اور آپ صحیح فارم پر وقت پر فائل کرتے ہیں۔ اس لوپ میں مہارت حاصل کریں اور آپ نے تجارتی ٹیکس کے عملی پہلو میں مہارت حاصل کر لی ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ٹیکس ایک عادت ہے، واقعہ نہیں۔ ہر سہ ماہی میں پانچ پرسکون منٹ جولائی میں پانچ بے ہودہ گھنٹے بچاتے ہیں، اور اس سے کہیں زیادہ اگر غلطی نوٹس میں بدل جاتی ہے۔ وہ تاجر جو جاتے وقت ریکارڈ کرتا ہے وہ تاجر ہے جو مقررہ وقت پر اچھی طرح سوتا ہے۔</p>\n</div></div>\n<h2 id=\"a-month-by-month-routine\">مہینہ بہ ماہ کا معمول</h2>\n<p>آپ کو ہر روز ٹیکس کے بارے میں سوچنے کی ضرورت نہیں ہے۔ آپ کو سال میں چند اینکر پوائنٹس کی ضرورت ہے۔ یہاں ایک سادہ کیلنڈر ہے جو پیشگی ٹیکس کی چار تاریخوں کے ارد گرد بنایا گیا ہے، جو پورے سال میں آسانی سے پھیلتا ہے اور آپ کو صاف کرنے کے لیے قدرتی لمحات فراہم کرتا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>جب</th>\n<th>کیا کرنا ہے</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>15 جون</td>\n<td>اگر آپ کا سال بھر کا خالص ٹیکس 10,000 روپے سے زیادہ ہونے کا امکان ہے تو پیشگی ٹیکس کی پہلی قسط ادا کریں۔ سال کے آغاز کے لیے اپنے بروکر سے ایک تازہ ٹیکس P&amp;L حاصل کریں۔</td>\n</tr>\n<tr>\n<td>15 ستمبر</td>\n<td>ایڈوانس ٹیکس کی دوسری قسط ادا کریں۔ اب تک اپنے ٹرن اوور کا جائزہ لیں اور اپنے اخراجات کی فائل کو اپ ڈیٹ کریں۔</td>\n</tr>\n<tr>\n<td>15 دسمبر</td>\n<td>تیسری قسط ادا کریں۔ چیک کریں کہ آیا آپ کا کاروبار آڈٹ کی حد کی طرف بڑھ رہا ہے تاکہ کوئی تعجب نہ ہو۔</td>\n</tr>\n<tr>\n<td>15 مارچ</td>\n<td>آخری قسط ادا کریں۔ سال کے نفع، نقصان اور ٹیکس کا تقریباً مکمل ڈرائی رن کریں۔</td>\n</tr>\n<tr>\n<td>جون سے جولائی (سال کے اختتام کے بعد)</td>\n<td>اپنے پورے سال کے بروکر ٹیکس P&amp;L اور ٹرن اوور کی رپورٹ ڈاؤن لوڈ کریں، AIS اور فارم 26AS کے ساتھ مفاہمت کریں، پھر وقت پر ITR-3 فائل کریں۔</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/taxation/images/diagram-advance-tax.png\" alt=\"سال بھر میں پیشگی ٹیکس کی چار تاریخیں، آپ کے ریکارڈ کو تازہ کرنے اور آپ پر واجب الادا رقم ادا کرنے کے قدرتی لمحات\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>سال بھر میں پیشگی ٹیکس کی چار تاریخیں، آپ کے ریکارڈ کو تازہ کرنے اور آپ پر واجب الادا رقم ادا کرنے کے قدرتی لمحات</figcaption></figure>\n<p>ایڈوانس ٹیکس وہ حصہ ہے جسے سب سے زیادہ ابتدائی لوگ یاد کرتے ہیں۔ اگر سال کے لیے آپ کا خالص ٹیکس 10,000 روپے سے زیادہ ہونے کا امکان ہے، تو آپ سے توقع کی جاتی ہے کہ آپ اسے سال بھر میں 15 جون، 15 ستمبر، 15 دسمبر، اور 15 مارچ کو ادا کریں گے، نہ کہ آخر میں ایک ساتھ۔ وقت پر ادائیگی کرنے سے سود سے بچا جاتا ہے، اور اپنے ریکارڈ کو انہی چار تاریخوں پر رکھنے کا مطلب ہے کہ آپ کی کتابیں کبھی بھی تین ماہ سے زیادہ پرانی نہیں ہوتیں۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>ابھی چار کیلنڈر یاد دہانیاں سیٹ کریں، ہر پیشگی ٹیکس کی تاریخ کے لیے ایک۔ جب ہر یاد دہانی فائر ہو جائے، تو ایک ہی نشست میں دو چیزیں کریں: آپ پر واجب الادا کوئی بھی ایڈوانس ٹیکس ادا کریں، اور اپنے بروکر سے تازہ ٹیکس P&amp;L ڈاؤن لوڈ کریں۔ دو چھوٹے کام، سال میں چار بار، اور آپ کی فائلنگ تین چوتھائی ہو چکی ہے۔</p>\n</div></div>\n<h2 id=\"the-four-documents-you-reconcile\">وہ چار دستاویزات جن سے آپ صلح کرتے ہیں۔</h2>\n<p>جب سال ختم ہوتا ہے، فائلنگ زیادہ تر مفاہمت کا عمل ہوتا ہے۔ آپ جانچ کر رہے ہیں کہ آپ کے اپنے ریکارڈ ان ریکارڈوں سے متفق ہیں جو محکمہ آپ کے بارے میں پہلے ہی جمع کر چکا ہے۔ چار دستاویزات تقریباً تمام کام کرتے ہیں۔</p>\n<p><strong>آپ کے بروکر ٹیکس پی اینڈ ایل اور ٹرن اوور رپورٹ</strong> آپ کا نقطہ آغاز ہے۔ آپ کا بروکر ایک بیان تیار کرتا ہے جو آپ کے حاصل شدہ منافع اور نقصانات کو ظاہر کرتا ہے اور، اہم بات یہ ہے کہ، آپ کے F&amp;O ٹرن اوور نے کنٹریکٹ ویلیو کے بجائے موافق اور ناموافق اختلافات کے مجموعہ کے طور پر مناسب طریقے سے حساب لگایا۔ یہ آپ کی کاروباری آمدنی کے اعداد و شمار کی ریڑھ کی ہڈی ہے۔</p>\n<p><strong>آپ کے اخراجات کے ثبوت</strong> وہ ہیں جو آپ کو اس کاروباری آمدنی کو قانونی طور پر کم کرنے دیتے ہیں۔ ہر کنٹریکٹ نوٹ، ہر سوفٹ ویئر یا خدمات کے لیے جو آپ تجارت کے لیے استعمال کرتے ہیں، اور اپنے بینک اسٹیٹمنٹس کو اپنے پاس رکھیں۔ یہ ایک تاجر کے لیے قابل کٹوتی کے کاروباری اخراجات ہیں، لیکن صرف اس صورت میں جب آپ انھیں دکھا سکتے ہیں، لہذا سال گزرنے کے ساتھ ساتھ انھیں محفوظ کریں۔</p>\n<p><strong>سالانہ معلوماتی بیان، AIS،</strong> آپ کے مالی سال کی محکمہ کی اپنی تصویر ہے۔ یہ آپ کے تجارت، سود، منافع، اور بینکوں، بروکرز، اور دیگر کے ذریعہ رپورٹ کردہ بڑے لین دین کو اکٹھا کرتا ہے۔ محکمہ آپ کے تجارتی ٹرن اوور کو STT اور AIS کے ذریعے ٹریک کرتا ہے، اس لیے آپ جو اعداد و شمار فائل کرتے ہیں ان کے مطابق ہونا چاہیے جو AIS دکھاتا ہے۔</p>\n<p><strong>فارم 26AS</strong> آپ کا ٹیکس کریڈٹ اسٹیٹمنٹ ہے۔ یہ آپ کی جانب سے پہلے سے کٹوتی یا جمع کیے گئے ٹیکس کو دکھاتا ہے، جیسے کہ TDS اور TCS، اور آپ نے جو ایڈوانس ٹیکس ادا کیا ہے۔ آپ اس میں مصالحت کرتے ہیں تاکہ آپ اپنے قرض کے ہر روپئے کا دعویٰ کریں اور اس طرح آپ کا حتمی ٹیکس حقیقت سے میل کھاتا ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>F&amp;O کو کیپٹل گین کے طور پر رپورٹ نہ کریں۔ یہ واحد سب سے عام اور سب سے مہنگی غلطی ہے جو ایک تاجر کرتا ہے۔ فیوچر اور آپشنز کاروباری آمدنی ہیں، جو کہ ITR-3 میں بتائی گئی ہے، نہ کہ قلیل مدتی یا طویل مدتی کیپٹل گین۔ غلط طریقے سے اس کی اطلاع دینا AIS اور نوٹس کے ساتھ مماثلت کو مدعو کرتا ہے، اور یہ آپ کی واپسی کو خراب بنا سکتا ہے۔</p>\n</div></div>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p><strong>ایک 60 سیکنڈ کی صلح، سادہ تعداد میں۔</strong> فرض کریں کہ آپ کا بروکر ٹیکس P&amp;L 9,000 روپے کے خالص منافع کے لیے 12,000 منافع، 8,000 نقصان، اور 5,000 منافع پر مشتمل 25,000 روپے کا F&amp;O ٹرن اوور دکھاتا ہے۔ آپ اپنا AIS کھولتے ہیں اور تصدیق کرتے ہیں کہ اس میں درج تجارتی سرگرمی بروکر کی رپورٹ کے مطابق ہے۔ آپ فارم 26AS کھولیں اور تصدیق کریں کہ آپ نے چار تاریخوں پر جو ایڈوانس ٹیکس ادا کیا ہے وہ کریڈٹ کے طور پر موجود ہے۔ تین دستاویزات، ایک مستقل کہانی۔ جب تینوں اتفاق کرتے ہیں، تو آپ کراس انگلیوں کے بجائے اعتماد کے ساتھ فائل کرتے ہیں۔</p>\n</div></div>\n<h2 id=\"when-to-bring-in-a-chartered-accountant\">چارٹرڈ اکاؤنٹنٹ کو کب لانا ہے۔</h2>\n<p>اپنے ٹیکس خود کرنا ایک عمدہ مقصد ہے، اور ایک تنخواہ دار سرمایہ کار کے لیے سادہ سرمائے کے منافع کے ساتھ یہ بہت قابل حصول ہے۔ لیکن تجارت میں جھریوں کا اضافہ ہوتا ہے، اور ایسے واضح لمحات ہوتے ہیں جب ایک قابل چارٹرڈ اکاؤنٹنٹ اپنی فیس کئی گنا زیادہ کماتا ہے۔ جب ان میں سے کوئی بھی سچ ہو تو کسی کو کال کریں۔</p>\n<p>جب آپ <strong>کاروبار بڑا ہے یا آڈٹ لاگو ہو سکتا ہے،</strong> کیونکہ آڈٹ کی حدیں، نقد رسید کے قواعد، اور کاروبار کا حساب کتاب ہی پیشہ ورانہ نگہداشت کا بدلہ دیتا ہے۔ جب آپ تھام لیں تو ایک لے آئیں <strong>غیر ملکی اثاثے،</strong> جیسا کہ US شیئرز یا ETFs، کیونکہ شیڈول FA انکشاف لازمی ہے چاہے بغیر کوئی فائدہ ہو اور اسے غلط کرنے کی سزائیں سخت ہیں۔ اور جب آپ ڈیل کرتے ہیں تو ایک لے آئیں <strong>کرپٹو،</strong> جہاں فلیٹ ریٹ رولز، بغیر سیٹ آف رولز، اور کرپٹو ڈیریویٹوز کا غیر طے شدہ علاج حقیقی طور پر مشکل ہے۔ مختصراً، جس لمحے ٹرن اوور، آڈٹ، غیر ملکی اثاثے، یا کرپٹو آپ کے سال میں داخل ہوتا ہے، ایک پیشہ ور کوئی عیش و آرام کی چیز نہیں ہے، یہ سمجھدار انشورنس ہے۔</p>\n<p>ڈیڈ لائن کو کبھی بھی پھسلنے نہ دینے کی ایک وجہ: مقررہ تاریخ تک، وقت پر ITR-3 فائل کرنا، جو آپ کے نقصان کی حفاظت کرتا ہے۔ اگر آپ تجارت کرتے ہیں اور آپ کو نقصان ہوتا ہے، تو وقت پر فائل کرنا بالکل اسی طرح ہے کہ آپ اس نقصان کو مستقبل کے منافع کے مقابلے میں طے کرنے کا حق رکھتے ہیں، غیر قیاس آرائی والے کاروباری نقصان کے لیے آٹھ تشخیصی سالوں تک۔ دیر سے فائل کریں اور آپ اس قیمتی کیری فارورڈ کو مکمل طور پر ضائع کر سکتے ہیں۔</p>\n<h2 id=\"the-final-pre-filing-checklist\">حتمی پری فائلنگ چیک لسٹ</h2>\n<p>آپ کورس کے اختتام پر پہنچ چکے ہیں، اس لیے آئیے آپ اپنی واپسی جمع کروانے سے پہلے ان سب کو ایک پرسکون چیک لسٹ میں لے آئیں۔ ہر لائن پر نشان لگائیں اور آپ نے اہم کام ٹھیک کر لیے ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>چیک کریں۔</th>\n<th>جب ہو گیا۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>بروکر کی رپورٹ</td>\n<td>آپ نے اپنے بروکر سے پورے سال کے ٹیکس P&amp;L اور ٹرن اوور کی رپورٹ ڈاؤن لوڈ کر لی ہے۔</td>\n</tr>\n<tr>\n<td>ایڈوانس ٹیکس</td>\n<td>اگر آپ کا خالص ٹیکس 10,000 روپے سے زیادہ ہے تو آپ نے چار تاریخوں میں ادائیگی کی، اور یہ فارم 26AS میں ظاہر ہوتا ہے۔</td>\n</tr>\n<tr>\n<td>اخراجات کے ثبوت</td>\n<td>کنٹریکٹ نوٹ، انوائس، اور بینک اسٹیٹمنٹس کو محفوظ اور مکمل کیا جاتا ہے۔</td>\n</tr>\n<tr>\n<td>مفاہمت</td>\n<td>آپ کے اعداد و شمار AIS اور فارم 26AS سے متفق ہیں۔</td>\n</tr>\n<tr>\n<td>صحیح شکل</td>\n<td>اگر آپ کے پاس F&amp;O یا انٹرا ڈے کاروباری آمدنی ہے تو آپ ITR-3 فائل کر رہے ہیں۔</td>\n</tr>\n<tr>\n<td>دائیں بالٹی</td>\n<td>F&amp;O کو کاروباری آمدنی کے طور پر رپورٹ کیا جاتا ہے، نہ کہ کیپٹل گین کے طور پر۔</td>\n</tr>\n<tr>\n<td>غیر ملکی اور کرپٹو</td>\n<td>شیڈول FA اور شیڈول VDA مکمل ہو جاتے ہیں اگر وہ آپ پر لاگو ہوتے ہیں۔</td>\n</tr>\n<tr>\n<td>وقت پر</td>\n<td>آپ اپنے نقصان کی حفاظت کے لیے مقررہ تاریخ تک فائل کر رہے ہیں۔</td>\n</tr>\n<tr>\n<td>پیشہ ورانہ چیک</td>\n<td>ایک چارٹرڈ اکاؤنٹنٹ نے اس کا جائزہ لیا ہے اگر ٹرن اوور، آڈٹ، غیر ملکی اثاثے، یا کرپٹو شامل ہیں۔</td>\n</tr>\n</tbody></table>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>اگر آپ اس چیک لسٹ کی ہر سطر پر نشان لگا سکتے ہیں، تو آپ نے مشکل کام کر لیا ہے۔ اس کے بعد فائل کرنا آسان حصہ بن جاتا ہے: صحیح فارم میں، وقت پر ان نمبروں کو درج کرنا جن پر آپ پہلے سے ہی اعتماد کرتے ہیں۔ یہی سارا کھیل ہے۔</p>\n</div></div>\n<p>اس کورس کو انجام دینے کی حوصلہ افزا حقیقت یہ ہے۔ ٹیکس شروع میں خوفناک محسوس ہوا کیونکہ یہ ناواقف تھا، اس لیے نہیں کہ یہ آپ سے باہر تھا۔ اب آپ سمجھ گئے ہیں کہ آمدنی کی تین بالٹیاں، سلیب اور رجیم، کیپٹل گین اور STT کیسے کام کرتے ہیں، F&amp;O کاروباری آمدنی کیوں ہے، ٹرن اوور اور آڈٹس کا اندازہ کیسے لگایا جاتا ہے، US اسٹاکس اور غیر ملکی اثاثوں کے ساتھ کیسے سلوک کیا جاتا ہے، کس طرح کرپٹو پر ٹیکس لگایا جاتا ہے، جو کہITRکے بغیر آپ کے سال کا ریکارڈ رکھتا ہے۔ یہ اس موضوع کا ایک حقیقی، عملی حکم ہے جسے زیادہ تر تاجر کبھی بھی بنانے کی زحمت نہیں کرتے۔</p>\n<p>آپ کو ہر نمبر کو حفظ کرنے کی ضرورت نہیں ہے۔ آپ کو صرف عادت کو برقرار رکھنا ہے، صحیح لمحات پر مدد طلب کرنا ہے، اور ایمانداری سے اور وقت پر فائل کرنا ہے۔ ایسا کریں، اور ٹیکس اس چیز سے رک جاتا ہے جس سے آپ ڈرتے ہیں اور یہ ایک سنجیدہ، پیشہ ور تاجر ہونے کا ایک اور حصہ بن جاتا ہے۔ اس کے ذریعے دیکھنے کے لئے اچھا کیا. اب اعتماد کے ساتھ فائل کریں۔</p>\n<p>یہ باب، اور یہ کورس، صرف سیکھنے کے لیے ہے اور ٹیکس کا مشورہ نہیں ہے۔ ٹیکس کے قوانین، شرحیں اور فارم ہر سال تبدیل ہوتے ہیں، اس لیے 2026-27 کے لیے فائل کرنے سے پہلے ہمیشہ ایک اہل چارٹرڈ اکاؤنٹنٹ سے اپنی مخصوص صورتحال کی تصدیق کریں۔</p>\n","toc":[{"level":2,"text":"سال بھر کی ذہنیت","id":"the-year-round-mindset"},{"level":2,"text":"مہینہ بہ ماہ کا معمول","id":"a-month-by-month-routine"},{"level":2,"text":"وہ چار دستاویزات جن سے آپ صلح کرتے ہیں۔","id":"the-four-documents-you-reconcile"},{"level":2,"text":"چارٹرڈ اکاؤنٹنٹ کو کب لانا ہے۔","id":"when-to-bring-in-a-chartered-accountant"},{"level":2,"text":"حتمی پری فائلنگ چیک لسٹ","id":"the-final-pre-filing-checklist"}],"imgCount":1,"hasContent":true}}
